window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s28-62","number":62,"surah":28,"verses":[41],"references":[{"surah":28,"verses":[41]}],"verseLabel":"القصص: 41","question":"ما بلاغة المجاز في قوله: ﴿يَدْعُونَ إِلَى النَّارِ﴾؟","answer":"هم لا يدعون إلى النار تصريحًا، وإنما إلى الكفر والمعاصي المؤدية إليها؛ فسمّى دعوتهم باسم مآلها ليكشف عاقبة اتباعهم ويقبح قيادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص225، تحت عنوان «بلاغة المجاز في قوله: ﴿إلى النار﴾»","url":""}]},{"id":"s28-63","number":63,"surah":28,"verses":[42],"references":[{"surah":28,"verses":[42]}],"verseLabel":"القصص: 42","question":"ما بلاغة التعبير بالإتباع في قوله: ﴿وَأَتْبَعْنَاهُمْ فِي هَذِهِ الدُّنْيَا لَعْنَةً﴾؟","answer":"صوّر اللعنة كأنها شيء يلحقهم ويلازمهم حيث ساروا، فلا تفارقهم في الدنيا؛ فزاد الإتباع معنى الدوام والإحاطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص230، تحت عنوان «بلاغة التعبير بالإتباع»","url":""}]},{"id":"s28-173","number":173,"surah":28,"verses":[42],"references":[{"surah":28,"verses":[42]}],"verseLabel":"القصص: 42","question":"ما سر التعبير باسم المفعول في قوله: ﴿مِنَ الْمَقْبُوحِينَ﴾؟","answer":"اسم المفعول يدل على أنهم مطرودون مبعدون موسومون بالقبح والخزي، فصارت الصفة واقعة عليهم ثابتة لا أمرًا عابرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص231–232، تحت عنوان «سر التعبير باسم المفعول ﴿المقبوحين﴾»","url":""}]},{"id":"s28-174","number":174,"surah":28,"verses":[42],"references":[{"surah":28,"verses":[42]}],"verseLabel":"القصص: 42","question":"ما بلاغة الجملة الاسمية في قوله: ﴿هُمْ مِنَ الْمَقْبُوحِينَ﴾؟","answer":"أفادت ثبوت قبح حال فرعون وجنوده يوم القيامة ودوامه، وأكدت أنهم مستقرون في زمرة المبعدين المذمومين.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص232، تحت عنوان «بلاغة التعبير بالجملة الاسمية»","url":""}]},{"id":"s28-64","number":64,"surah":28,"verses":[44,45,46],"references":[{"surah":28,"verses":[44,45,46]}],"verseLabel":"القصص: 44-46","question":"ما بلاغة تكرار ﴿وَمَا كُنْتَ﴾ في نفي حضور النبي أحداث موسى؟","answer":"كرر النفي مع كل مشهد ليؤكد استقلال كل واقعة بكون النبي لم يشهدها، فيتضاعف الدليل على أن معرفته الدقيقة بها وحي من الله لا مشاهدة ولا تعلمًا من البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص258، تحت عنوان «بلاغة تكرار ﴿وما كنت﴾»","url":""}]},{"id":"s28-175","number":175,"surah":28,"verses":[44,45,46],"references":[{"surah":28,"verses":[44,45,46]}],"verseLabel":"القصص: 44-46","question":"ما سر جمع الأحوال الثلاثة المنفية في قوله: ﴿وَمَا كُنْتَ﴾؟","answer":"جمع نفي وجوده عند إعطاء موسى التوراة، وفي أهل مدين، وبجانب الطور؛ لأنها مواقف عظيمة متباعدة لا سبيل إلى إحاطة النبي بتفاصيلها إلا بالوحي، فاشتد بها برهان نبوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص266، تحت عنوان «سر جمع هذه الأحوال الثلاثة المنفية»","url":""}]},{"id":"s28-65","number":65,"surah":28,"verses":[46],"references":[{"surah":28,"verses":[46]}],"verseLabel":"القصص: 46","question":"ما معنى الاستدراك في قوله: ﴿وَلَكِنْ رَحْمَةً مِنْ رَبِّكَ﴾؟","answer":"دفع الاستدراك توهم أن غياب النبي عن تلك الوقائع يمنع علمه بها؛ فلم يشهدها، ولكن رحمة الله أوصلت إليه خبرها بالوحي وأرسلته لينذر قومًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص267، تحت عنوان «معنى الاستدراك في قوله: ﴿ولكن﴾»","url":""}]},{"id":"s28-176","number":176,"surah":28,"verses":[46],"references":[{"surah":28,"verses":[46]}],"verseLabel":"القصص: 46","question":"ما بلاغة الحذف في قوله: ﴿وَلَكِنْ رَحْمَةً مِنْ رَبِّكَ﴾؟","answer":"حذف العامل في ﴿رحمة﴾ إيجازًا، ويقدّر بما يناسب السياق: ولكن رحمناك أو أرسلناك أو أعلمناك بالوحي رحمة من ربك؛ فجمع الامتنان بالنبوة والرحمة بالأمة في عبارة موجزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص268، تحت عنوان «بلاغة الحذف في ﴿ولكن رحمة﴾»","url":""}]},{"id":"s28-66","number":66,"surah":28,"verses":[47],"references":[{"surah":28,"verses":[47]}],"verseLabel":"القصص: 47","question":"ما دلالة ﴿لَوْلَا﴾ في قوله: ﴿وَلَوْلَا أَنْ تُصِيبَهُمْ مُصِيبَةٌ﴾؟","answer":"هي لامتناع الجواب لوجود الشرط؛ أي إن إرسال الرسول وقع لئلا يحتجوا عند نزول العقوبة بأنهم لم يأتهم نذير، فكان بعثه قطعًا لمعذرتهم وإقامة للحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص276، تحت عنوان «دلالة التعبير بـ (لولا) في السياق»","url":""}]},{"id":"s28-177","number":177,"surah":28,"verses":[47],"references":[{"surah":28,"verses":[47]}],"verseLabel":"القصص: 47","question":"ما بلاغة حذف جواب ﴿لَوْلَا﴾ في قوله: ﴿وَلَوْلَا أَنْ تُصِيبَهُمْ مُصِيبَةٌ﴾؟","answer":"حذف جوابها لدلالة السياق عليه، وتقديره: لما أرسلناك؛ فاستغنى عنه بما بعده، ووجّه الذهن إلى عظم المصيبة وافتضاح اعتذارهم إذا نزلت قبل البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص279، تحت عنوان «بلاغة حذف جواب (لولا)»","url":""}]},{"id":"s28-67","number":67,"surah":28,"verses":[48],"references":[{"surah":28,"verses":[48]}],"verseLabel":"القصص: 48","question":"ما دلالة تعدد القراءات في قوله: ﴿سِحْرَانِ تَظَاهَرَا﴾؟","answer":"قرئ ﴿ساحران﴾ فيراد شخصان، كقولهم موسى وهارون أو موسى ومحمد، وقرئ ﴿سحران﴾ فيراد كتابان، كالتوراة والقرآن؛ فتعددت صور افترائهم مع اتحاد مقصدهم في رد الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص294، تحت عنوان «دلالة تعدد القراءات الواردة في ﴿سحران﴾»","url":""}]},{"id":"s28-178","number":178,"surah":28,"verses":[48],"references":[{"surah":28,"verses":[48]}],"verseLabel":"القصص: 48","question":"لماذا قيل: ﴿تَظَاهَرَا﴾ دون «تعاونا»؟","answer":"التظاهر أبلغ في الاتحاد والقوة؛ فأصله من الظهر الذي يتقوى به الإنسان، فصوّر زعمهم أن كل واحد من الوحيين أو الرسولين يسند الآخر ويشتد به.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص294، تحت عنوان «إيثار التعبير بـ﴿تظاهرا﴾ دون (تعاونا)»","url":""}]},{"id":"s28-68","number":68,"surah":28,"verses":[49],"references":[{"surah":28,"verses":[49]}],"verseLabel":"القصص: 49","question":"ما بلاغة الأمر في قوله: ﴿فَأْتُوا بِكِتَابٍ مِنْ عِنْدِ اللَّهِ﴾؟","answer":"خرج الأمر إلى التعجيز والتحدي؛ إذ طالبهم بكتاب يقابل التوراة والقرآن وهم عاجزون عن الإتيان بمثلهما، فافتضح افتراؤهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص298، تحت عنوان «بلاغة الأمر في قوله: ﴿فأتوا﴾»","url":""}]},{"id":"s28-179","number":179,"surah":28,"verses":[49],"references":[{"surah":28,"verses":[49]}],"verseLabel":"القصص: 49","question":"ما دلالة وصف الكتاب المطلوب بأنه ﴿مِنْ عِنْدِ اللَّهِ﴾؟","answer":"قيد التحدي بكتاب منزل من عند الله لا بكلام يصنعه البشر، وفي ذلك مدح للتوراة والقرآن بإثبات مصدرهما الإلهي وإبطال دعوى السحر عنهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص299، تحت عنوان «دلالة وصف الكتاب بكونه من عند الله»","url":""}]},{"id":"s28-180","number":180,"surah":28,"verses":[49],"references":[{"surah":28,"verses":[49]}],"verseLabel":"القصص: 49","question":"ما دلالة صيغة التفضيل في قوله: ﴿هُوَ أَهْدَى مِنْهُمَا﴾؟","answer":"زاد التحدي إحكامًا؛ فلم يطلب كتابًا يماثلهما فحسب، بل أهدى منهما، فإذا عجزوا عن المماثلة كانوا عن الإتيان بالأهدى أعجز، فبطلت مزاعمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص299، تحت عنوان «دلالة التعبير بصيغة التفضيل ﴿أهدى﴾»","url":""}]},{"id":"s28-69","number":69,"surah":28,"verses":[50],"references":[{"surah":28,"verses":[50]}],"verseLabel":"القصص: 50","question":"ما دلالة نفي الاستجابة في قوله: ﴿فَإِنْ لَمْ يَسْتَجِيبُوا لَكَ﴾؟","answer":"المراد عدم إجابتهم إلى التحدي بالإتيان بكتاب أهدى، وهو عجز لا مجرد امتناع؛ فبان أنهم لا يملكون حجة تقابل الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص304، تحت عنوان «دلالة التعبير بنفي الاستجابة»","url":""}]},{"id":"s28-181","number":181,"surah":28,"verses":[50],"references":[{"surah":28,"verses":[50]}],"verseLabel":"القصص: 50","question":"ما بلاغة القصر في قوله: ﴿إِنَّمَا يَتَّبِعُونَ أَهْوَاءَهُمْ﴾؟","answer":"قصر اتباعهم على الأهواء، فنفى أن يكون لهم دليل أو هدى يستندون إليه، وكشف أن تكذيبهم ناشئ عن الرغبة الجامحة والتعصب.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص305–306، تحت عنوان «بلاغة أسلوب القصر»","url":""}]},{"id":"s28-70","number":70,"surah":28,"verses":[51],"references":[{"surah":28,"verses":[51]}],"verseLabel":"القصص: 51","question":"ما سرّ التعبير بـ﴿وَلَقَدْ وَصَّلْنَا لَهُمُ الْقَوْلَ﴾؟","answer":"«وصلنا» تصور تتابع نزول القرآن واتصال بعضه ببعض: وعدًا ووعيدًا، وقصصًا ومواعظ، بحسب الحكمة والمصلحة. وتفيد صيغة التفعيل كثرة هذا التوصيل، بما يعينهم على الفهم والانتفاع والتذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص314، تحت عنوان «دلالة التعبير بالفعل (وصل) مادة وصيغة»","url":""}]},{"id":"s28-71","number":71,"surah":28,"verses":[52],"references":[{"surah":28,"verses":[52]}],"verseLabel":"القصص: 52","question":"ما دلالة تركيب الجملة في قوله: ﴿هُمْ بِهِ يُؤْمِنُونَ﴾؟","answer":"ركّب الخبر من جملة فعلية داخل جملة اسمية؛ فالاسمية تثبت أصل إيمانهم ورسوخه، والمضارع يصور تجدده واستمراره كلما تلي القرآن وتبينت دلائله.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص319، تحت عنوان «دلالة التعبير بالجملة مركبة»","url":""}]},{"id":"s28-72","number":72,"surah":28,"verses":[54],"references":[{"surah":28,"verses":[54]}],"verseLabel":"القصص: 54","question":"ما دلالة تثنية ﴿مَرَّتَيْنِ﴾ في قوله: ﴿أُولَئِكَ يُؤْتَوْنَ أَجْرَهُمْ مَرَّتَيْنِ﴾؟","answer":"دلّت على مضاعفة أجرهم: لإيمانهم بكتابهم ثم بالقرآن، وقيل لإيمانهم بالقرآن قبل نزوله ثم بعده؛ فهي تصور تعدد أسباب الثواب وعظم جزائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص331، تحت عنوان «دلالة التعبير بمفردة المرة مثناة في ﴿مرتين﴾»","url":""}]},{"id":"s28-73","number":73,"surah":28,"verses":[55],"references":[{"surah":28,"verses":[55]}],"verseLabel":"القصص: 55","question":"ما علة فصل جملة ﴿سَلَامٌ عَلَيْكُمْ﴾ عما قبلها؟","answer":"فصلت لأنها استئناف بياني يجيب عما يثيره قولهم ﴿لكم أعمالكم﴾: ماذا يكون موقفكم منا؟ فجاء الجواب سلام متاركة ومسالمة لا مقابلة للجهل بالجهل.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص341، تحت عنوان «علة فصل جملة ﴿سلام عليكم﴾ عما قبلها»","url":""}]},{"id":"s28-74","number":74,"surah":28,"verses":[56],"references":[{"surah":28,"verses":[56]}],"verseLabel":"القصص: 56","question":"ما معنى الاستدراك في قوله: ﴿وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ﴾؟","answer":"استدرك بعد نفي هداية التوفيق عن النبي فأثبتها لله؛ فالرسول يدل ويبلغ، أما خلق الإيمان في القلب فإلى مشيئة الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص347، تحت عنوان «معنى (لكن) في جملة ﴿ولكن﴾»","url":""}]},{"id":"s28-182","number":182,"surah":28,"verses":[56],"references":[{"surah":28,"verses":[56]}],"verseLabel":"القصص: 56","question":"ما دلالة تقديم اسم الجلالة في قوله: ﴿وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ﴾؟","answer":"تقديم اسم الجلالة على الخبر الفعلي يقصر هداية التوفيق عليه سبحانه، فيقرر أن أحدًا لا يملك إدخال الإيمان في القلوب استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص348، تحت عنوان «دلالة تقديم اسم الجلالة على الخبر الفعلي»","url":""}]},{"id":"s28-75","number":75,"surah":28,"verses":[57],"references":[{"surah":28,"verses":[57]}],"verseLabel":"القصص: 57","question":"ما دلالة التعبير بـ﴿الْهُدَى﴾ في قولهم: ﴿إِنْ نَتَّبِعِ الْهُدَى مَعَكَ﴾؟","answer":"سموا القرآن والإسلام هدى، وفي ذلك إقرار منهم بأنه سبيل الحق والخير، لكنهم آثروا الخوف الدنيوي على اتباع ما عرفوا هدايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص355–356، تحت عنوان «دلالة التعبير بـ﴿الهدى﴾»","url":""}]},{"id":"s28-183","number":183,"surah":28,"verses":[57],"references":[{"surah":28,"verses":[57]}],"verseLabel":"القصص: 57","question":"ما دلالة التعبير بـ﴿نُتَخَطَّفْ﴾ مادة وصيغة؟","answer":"التخطف أخذ سريع متكرر من جهات شتى، وبناء الفعل للمفعول عمّم كل من قد يهاجمهم؛ فصوّروا خوفهم من استئصال عاجل إن آمنوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص356، تحت عنوان «دلالة التعبير بـ﴿نتخطف﴾ مادة وصيغة»","url":""}]},{"id":"s28-76","number":76,"surah":28,"verses":[57],"references":[{"surah":28,"verses":[57]}],"verseLabel":"القصص: 57","question":"ما غرض الاستفهام في قوله: ﴿أَوَلَمْ نُمَكِّنْ لَهُمْ حَرَمًا آمِنًا﴾؟","answer":"الاستفهام تقريري توبيخي يثبت أن الله أمّنهم في الحرم وهم على الكفر؛ فمن منحهم الأمن أولًا قادر على حفظه لهم إذا اتبعوا الهدى، فتسقط حجتهم بالخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص358، تحت عنوان «غرض الاستفهام في ﴿أولم نمكن﴾»","url":""}]},{"id":"s28-184","number":184,"surah":28,"verses":[57],"references":[{"surah":28,"verses":[57]}],"verseLabel":"القصص: 57","question":"ما الموقع البياني لجملة ﴿يُجْبَى إِلَيْهِ ثَمَرَاتُ كُلِّ شَيْءٍ﴾؟","answer":"جاءت صفة ثانية للحرم بعد أمنه، فجمعت نعمتَي الحماية والرزق في وصف واحد؛ وبذلك تم الرد على خوفهم من ضياع الأمن والمعاش معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص360، تحت عنوان «الموقع البياني لجملة ﴿يجبى إليه﴾»","url":""}]},{"id":"s28-77","number":77,"surah":28,"verses":[58],"references":[{"surah":28,"verses":[58]}],"verseLabel":"القصص: 58","question":"ما دلالة التعبير بالفعل ﴿بَطِرَتْ﴾؟","answer":"البطر طغيان النعمة وترك شكرها مع السعة، فصور أن أهل القرى قابلوا وفرة العيش بالجحود والأشر حتى استحقوا الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص370–371، تحت عنوان «دلالة التعبير بالفعل ﴿بطرت﴾»","url":""}]},{"id":"s28-185","number":185,"surah":28,"verses":[58],"references":[{"surah":28,"verses":[58]}],"verseLabel":"القصص: 58","question":"ما دلالة الإضافة في قوله: ﴿مَعِيشَتَهَا﴾؟","answer":"أضيفت المعيشة إلى القرى لأن المراد معيشة أهلها، وفي الإضافة استحضار النعمة التي عاشوها وعرفوها ثم كفروها بدل أن يؤدوا شكرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص371، تحت عنوان «دلالة الإضافة في ﴿معيشتها﴾»","url":""}]},{"id":"s28-78","number":78,"surah":28,"verses":[59],"references":[{"surah":28,"verses":[59]}],"verseLabel":"القصص: 59","question":"ما معنى ﴿حَتَّى﴾ في قوله: ﴿حَتَّى يَبْعَثَ فِي أُمِّهَا رَسُولًا﴾؟","answer":"جعلت بعث الرسول غاية يمتنع الإهلاك قبلها؛ فلا يعذب الله قرية حتى تقوم عليها الحجة بالرسالة والبيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص381، تحت عنوان «معنى ﴿حتى﴾ في ﴿حتى يبعث﴾»","url":""}]},{"id":"s28-186","number":186,"surah":28,"verses":[59],"references":[{"surah":28,"verses":[59]}],"verseLabel":"القصص: 59","question":"ما بلاغة التعبير عن كبرى القرى بقوله: ﴿فِي أُمِّهَا﴾؟","answer":"سميت كبرى القرى أمًّا لأنها أصل لما حولها ومجمع أهلها ومهبط أخبارهم؛ فبعث الرسول فيها أبلغ في انتشار الدعوة وبلوغ الحجة إلى القرى التابعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص382، تحت عنوان «بلاغة التعبير عن كبرى القرى بالأم»","url":""}]},{"id":"s28-187","number":187,"surah":28,"verses":[59],"references":[{"surah":28,"verses":[59]}],"verseLabel":"القصص: 59","question":"ما معنى ﴿إِلَّا﴾ في قوله: ﴿إِلَّا وَأَهْلُهَا ظَالِمُونَ﴾؟","answer":"أفادت قصر الإهلاك على حال تلبس أهل القرى بالظلم بعد قيام الحجة؛ فلا يقع العقاب اعتباطًا ولا قبل استحقاقهم له.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص386، تحت عنوان «معنى ﴿إلا﴾ في قوله: ﴿إلا وأهلها ظالمون﴾»","url":""}]},{"id":"s28-79","number":79,"surah":28,"verses":[60],"references":[{"surah":28,"verses":[60]}],"verseLabel":"القصص: 60","question":"ما معنى الواو في قوله: ﴿وَمَا عِنْدَ اللَّهِ خَيْرٌ وَأَبْقَى﴾؟","answer":"جمعت الواو بين صفتين متكاملتين لجزاء الآخرة: كمال الخيرية ودوام البقاء، في مقابل متاع الدنيا الذي قد يحسن لكنه ينقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص398، تحت عنوان «معنى (الواو) في قوله: ﴿وأبقى﴾»","url":""}]},{"id":"s28-80","number":80,"surah":28,"verses":[61],"references":[{"surah":28,"verses":[61]}],"verseLabel":"القصص: 61","question":"ما معنى الفاء في قوله: ﴿فَهُوَ لَاقِيهِ﴾؟","answer":"أفادت ترتب لقاء الوعد على ثبوته؛ فمن وعده الله وعدًا حسنًا فملاقاته له نتيجة حتمية، لأن وعد الله لا يتخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص411، تحت عنوان «معنى (الفاء) في قوله: ﴿فهو لاقيه﴾»","url":""}]},{"id":"s28-188","number":188,"surah":28,"verses":[61],"references":[{"surah":28,"verses":[61]}],"verseLabel":"القصص: 61","question":"ما نكتة المقابلة بين الوعد الحسن ومتاع الحياة الدنيا؟","answer":"قابل نعيم الآخرة الصادق الدائم بمتاع الدنيا العاجل الزائل، ثم قرن المتاع بإحضار صاحبه للعذاب؛ فانتفت المساواة بين المصيرين من كل وجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص416، تحت عنوان «نكتة المقابلة في الآية»","url":""}]},{"id":"s28-189","number":189,"surah":28,"verses":[61],"references":[{"surah":28,"verses":[61]}],"verseLabel":"القصص: 61","question":"ما نكتة حذف متعلق ﴿الْمُحْضَرِينَ﴾؟","answer":"حذف المحضر إليه ليذهب الذهن إلى كل هول، والسياق يقدره: المحضرين للعذاب أو النار؛ فزاد الحذف تهويلًا لموقف الكافرين وفضحًا لمصيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص419–420، تحت عنوان «نكتة حذف متعلق ﴿المحضرين﴾»","url":""}]},{"id":"s28-81","number":81,"surah":28,"verses":[62],"references":[{"surah":28,"verses":[62]}],"verseLabel":"القصص: 62","question":"ما غرض الاستفهام في قوله: ﴿أَيْنَ شُرَكَائِيَ﴾؟","answer":"خرج الاستفهام إلى التعجيز والتوبيخ؛ طلب منهم إحضار من زعموهم شركاء في مقام لا يملكون فيه وجودًا ولا نصرة، فانكشف بطلان دعواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص430–431، تحت عنوان «غرض الاستفهام، ولطيفته بـ﴿أين شركائي﴾»","url":""}]},{"id":"s28-82","number":82,"surah":28,"verses":[63],"references":[{"surah":28,"verses":[63]}],"verseLabel":"القصص: 63","question":"ما غرض الخبر في قول الرؤساء: ﴿أَغْوَيْنَاهُمْ كَمَا غَوَيْنَا﴾؟","answer":"أرادوا تبرئة أنفسهم من الإكراه؛ اعترفوا بأنهم زينوا الضلال لأتباعهم، لكن القوم قبلوه باختيارهم كما اختاره الرؤساء لأنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص440–441، تحت عنوان «غرض الخبر في ﴿أغويناهم كما غوينا﴾»","url":""}]},{"id":"s28-190","number":190,"surah":28,"verses":[63],"references":[{"surah":28,"verses":[63]}],"verseLabel":"القصص: 63","question":"ما معنى الكاف وغرضها في قوله: ﴿كَمَا غَوَيْنَا﴾؟","answer":"الكاف للتشبيه، ومعناها: أغويناهم إغواءً مماثلًا لغيّنا الاختياري؛ فسوت بين الفريقين في تحمل مسؤولية الضلال ونفت حجة الإكراه.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص440–441، تحت عنوان «معنى الكاف وغرضها في قوله: ﴿كما غوينا﴾»","url":""}]},{"id":"s28-83","number":83,"surah":28,"verses":[64],"references":[{"surah":28,"verses":[64]}],"verseLabel":"القصص: 64","question":"ما دلالة الأمر في قوله: ﴿ادْعُوا شُرَكَاءَكُمْ﴾؟","answer":"الأمر للتعجيز والتبكيت والتهكم؛ كلفهم استنصار معبوداتهم لإظهار عجزها وخيبة من علق بها رجاء الشفاعة والنصرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص452–453، تحت عنوان «دلالة التعبير بالدعاء وغرضه في فعل الأمر ﴿ادعوا﴾»","url":""}]},{"id":"s28-191","number":191,"surah":28,"verses":[64],"references":[{"surah":28,"verses":[64]}],"verseLabel":"القصص: 64","question":"ما معنى ﴿لَمْ﴾ في قوله: ﴿فَلَمْ يَسْتَجِيبُوا لَهُمْ﴾؟","answer":"نفت الاستجابة نفيًا قاطعًا في الماضي، فقلبت رجاءهم خيبة وأثبتت أن الشركاء عاجزون عن إجابة الدعاء أو دفع الضرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص456، تحت عنوان «معنى (لم) في قوله ﴿فلم يستجيبوا﴾»","url":""}]},{"id":"s28-84","number":84,"surah":28,"verses":[66],"references":[{"surah":28,"verses":[66]}],"verseLabel":"القصص: 66","question":"ما دلالة التعبير بالعمى في قوله: ﴿فَعَمِيَتْ عَلَيْهِمُ الْأَنْبَاءُ﴾؟","answer":"استعير العمى لاشتباه الحجج وخفائها عنهم؛ فهول القيامة أذهب قدرتهم على تبين جواب ينجيهم، وبقوا حائرين لا يهتدون.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص473، تحت عنوان «دلالة التعبير بالعمى في الفعل ﴿فعميت﴾»","url":""}]},{"id":"s28-192","number":192,"surah":28,"verses":[66],"references":[{"surah":28,"verses":[66]}],"verseLabel":"القصص: 66","question":"ما دلالة إسناد العمى إلى ﴿الْأَنْبَاءِ﴾؟","answer":"أسند العمى إلى الأنباء نفسها مبالغة، كأن الأخبار والأجوبة هي التي فقدت طريقها إليهم ولم تصل؛ فصور انقطاع كل حجة عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص474، تحت عنوان «دلالة إسناد الفعل (عمي) إلى ﴿الأنباء﴾»","url":""}]},{"id":"s28-193","number":193,"surah":28,"verses":[66],"references":[{"surah":28,"verses":[66]}],"verseLabel":"القصص: 66","question":"ما معنى الفاء في قوله: ﴿فَهُمْ لَا يَتَسَاءَلُونَ﴾؟","answer":"فرعت انقطاع سؤال بعضهم بعضًا على عماهم عن الجواب؛ فلما استوت حيرتهم ولم يملك أحد حجة لم يجدوا ما يسألون عنه أو يجيبون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص477، تحت عنوان «معنى (الفاء) في قوله ﴿فهم لا يتساءلون﴾»","url":""}]},{"id":"s28-85","number":85,"surah":28,"verses":[68],"references":[{"surah":28,"verses":[68]}],"verseLabel":"القصص: 68","question":"ما نكتة تقديم الخلق على الاختيار في قوله: ﴿يَخْلُقُ مَا يَشَاءُ وَيَخْتَارُ﴾؟","answer":"قدم الخلق لأنه دليل القدرة والعلم وأساس الاختيار؛ فمن تفرد بإيجاد الخلق وأحاط بهم هو وحده الأعلم بمن يصطفيه وما يصلح لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص497، تحت عنوان «نكتة تقديم الخلق على الاختيار»","url":""}]},{"id":"s28-194","number":194,"surah":28,"verses":[68],"references":[{"surah":28,"verses":[68]}],"verseLabel":"القصص: 68","question":"ما معاني ﴿مَا﴾ في قوله: ﴿مَا كَانَ لَهُمُ الْخِيَرَةُ﴾؟","answer":"يجوز أن تكون نافية، فتنفي عن الخلق حق الاعتراض والاختيار مع الله، ويجوز أن تكون موصولة مفعولًا لـ﴿يختار﴾؛ أي يختار لهم ما فيه خيرهم ومصلحتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص498–499، تحت عنوان «معاني ﴿ما﴾ في جملة ﴿ما كان لهم الخيرة﴾»","url":""}]},{"id":"s28-86","number":86,"surah":28,"verses":[71,72],"references":[{"surah":28,"verses":[71,72]}],"verseLabel":"القصص: 71-72","question":"ما دلالة الشرط الافتراضي في قوله: ﴿إِنْ جَعَلَ اللَّهُ عَلَيْكُمُ اللَّيْلَ سَرْمَدًا﴾؟","answer":"افترض دوام الليل لتنبيه الأبصار والعقول إلى نعمة التعاقب؛ فتخيل الحرمان يكشف عجز الخلق وافتقارهم إلى من يأتي بالضياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص536، تحت عنوان «دلالة التعبير بالشرط الافتراضي: ﴿إن جعل﴾»","url":""}]},{"id":"s28-195","number":195,"surah":28,"verses":[71,72],"references":[{"surah":28,"verses":[71,72]}],"verseLabel":"القصص: 71-72","question":"ما بلاغة تكرار الاستفهام في آيتي الليل والنهار السرمدين؟","answer":"كرر البنية في فرض دوام الليل ثم دوام النهار للتقرير والتوبيخ، ولإظهار أن كليهما نعمة لا يستقيم العيش إذا انفرد واستمر بلا تعاقب.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص548–549، تحت عنوان «بلاغة التكرار في الآية الثانية»","url":""}]},{"id":"s28-87","number":87,"surah":28,"verses":[73],"references":[{"surah":28,"verses":[73]}],"verseLabel":"القصص: 73","question":"ما بلاغة اللف والنشر في قوله: ﴿لِتَسْكُنُوا فِيهِ وَلِتَبْتَغُوا مِنْ فَضْلِهِ﴾؟","answer":"ذكر الليل والنهار ثم وزع عليهما الغايتين على الترتيب: السكون في الليل وطلب الرزق في النهار؛ فجمع وظائف الزمنين بعبارة موجزة واضحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص559، تحت عنوان «بلاغة اللف والنشر»","url":""}]},{"id":"s28-196","number":196,"surah":28,"verses":[73],"references":[{"surah":28,"verses":[73]}],"verseLabel":"القصص: 73","question":"ما معنى الواو ودلالتها في قوله: ﴿وَلَعَلَّكُمْ تَشْكُرُونَ﴾؟","answer":"عطفت غاية الشكر على غايتي السكون والابتغاء، فرفعت الانتفاع من مجرد قضاء المصالح إلى الاعتراف بالنعمة واستعمالها في الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص564، تحت عنوان «معنى الواو ودلالتها في ﴿ولعلكم﴾»","url":""}]},{"id":"s28-88","number":88,"surah":28,"verses":[76],"references":[{"surah":28,"verses":[76]}],"verseLabel":"القصص: 76","question":"ما سرّ التعبير بـ﴿إِنَّ قَارُونَ كَانَ مِنْ قَوْمِ مُوسَى فَبَغَى عَلَيْهِمْ﴾؟","answer":"كان قارون من قوم موسى وذا قرابة منه، لكن النسب والقرابة لم يمنعاه من البغي على قومه والكفر بالله.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص597–598، تحت عنوان «نكتة الإخبار عن انتساب قارون لقوم موسى»","url":""}]},{"id":"s28-89","number":89,"surah":28,"verses":[76],"references":[{"surah":28,"verses":[76]}],"verseLabel":"القصص: 76","question":"ما فائدة ذكر مفاتح خزائن قارون دون الخزائن؟","answer":"ذكر المفاتيح مبالغة في كثرة الأموال؛ فإذا كانت المفاتيح وحدها تثقل العصبة، فما الظن بما وراءها من الخزائن؟ فدل الأخف على ضخامة الأثقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص602–603، تحت عنوان «فائدة ذكر المفاتح دون الخزائن»","url":""}]},{"id":"s28-197","number":197,"surah":28,"verses":[76],"references":[{"surah":28,"verses":[76]}],"verseLabel":"القصص: 76","question":"ما دلالة التعبير بـ﴿تَنُوءُ﴾ مادة وصيغة؟","answer":"النوء النهوض بالثقل في جهد ومشقة؛ فصورت الكلمة أن العصبة تميل وتجهد تحت حمل المفاتح، مبالغة في ضخامة كنوز قارون.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص604، تحت عنوان «دلالة التعبير بالنوء مادة وصيغة»","url":""}]},{"id":"s28-198","number":198,"surah":28,"verses":[76],"references":[{"surah":28,"verses":[76]}],"verseLabel":"القصص: 76","question":"ما نكتة وصف العصبة بقوله: ﴿أُولِي الْقُوَّةِ﴾؟","answer":"خصهم بالقوة ليبلغ تصوير الثقل غايته؛ فما يعجز جماعة قوية ويشق عليها حمله لا بد أن يكون عظيمًا خارجًا عن المعتاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص605، تحت عنوان «نكتة وصف العصبة»","url":""}]},{"id":"s28-90","number":90,"surah":28,"verses":[76],"references":[{"surah":28,"verses":[76]}],"verseLabel":"القصص: 76","question":"ما معنى النهي في قوله: ﴿لَا تَفْرَحْ﴾؟","answer":"النهي ليس عن مطلق السرور، بل عن فرح البطر والأشر الذي يورث الاغترار والتعالي بالمال ويشغل عن شكر المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص607، تحت عنوان «معنى ﴿لا﴾ ودلالتها في ﴿لا تفرح﴾»","url":""}]},{"id":"s28-199","number":199,"surah":28,"verses":[76],"references":[{"surah":28,"verses":[76]}],"verseLabel":"القصص: 76","question":"ما بلاغة التعبير بالفرح عن التكبر في قوله: ﴿لَا تَفْرَحْ﴾؟","answer":"عبّر بالفرح عن لازمه وهو التكبر والبطر؛ لأن الابتهاج المذموم بالمال يفضي إلى الزهو على الناس، فكانت الكلمة كناية أو مجازًا يكشف باطن قارون.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص609، تحت عنوان «بلاغة التعبير بالفرح عن التكبر في الآية الكريمة»","url":""}]},{"id":"s28-91","number":91,"surah":28,"verses":[77],"references":[{"surah":28,"verses":[77]}],"verseLabel":"القصص: 77","question":"ما بلاغة الكناية في قوله: ﴿وَلَا تَنْسَ نَصِيبَكَ مِنَ الدُّنْيَا﴾؟","answer":"النهي عن النسيان كناية عن ترك النصيب المباح؛ أي لا تهمل حقك المشروع من الدنيا، فليس المراد ذهول الذاكرة بل حسن الانتفاع بلا إسراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص614، تحت عنوان «بلاغة الكناية في قوله ﴿ولا تنس نصيبك﴾»","url":""}]},{"id":"s28-200","number":200,"surah":28,"verses":[77],"references":[{"surah":28,"verses":[77]}],"verseLabel":"القصص: 77","question":"ما بلاغة الاحتراس في قوله: ﴿وَلَا تَنْسَ نَصِيبَكَ مِنَ الدُّنْيَا﴾؟","answer":"احتُرس به من توهم أن طلب الآخرة يقتضي تحريم كل متاع الدنيا؛ فأثبت الانتفاع المباح مع بقاء الأمر بالإحسان وأداء الحقوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص615، تحت عنوان «بلاغة الاحتراس في الآية»","url":""}]},{"id":"s28-92","number":92,"surah":28,"verses":[77],"references":[{"surah":28,"verses":[77]}],"verseLabel":"القصص: 77","question":"ما بلاغة التشبيه في قوله: ﴿وَأَحْسِنْ كَمَا أَحْسَنَ اللَّهُ إِلَيْكَ﴾؟","answer":"شبه إحسان العبد إلى الخلق بإحسان الله إليه من جهة البذل لا من جهة المقدار؛ فجعل النعمة باعثًا على شكرها وإيصال الخير إلى غيره بحسب الطاقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص616، تحت عنوان «بلاغة التشبيه في ﴿كما أحسن الله إليك﴾ ومعناه»","url":""}]},{"id":"s28-201","number":201,"surah":28,"verses":[77],"references":[{"surah":28,"verses":[77]}],"verseLabel":"القصص: 77","question":"ما نكتة حذف متعلق الإحسان الأول وإثباته في الثاني؟","answer":"حذف متعلق ﴿أحسن﴾ ليعم الإحسان إلى النفس والأهل وسائر الخلق، وذكر ﴿إليك﴾ في إحسان الله لتذكير قارون بالمنعم الذي انتهت إليه نعمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص617، تحت عنوان «نكتة حذف متعلق الإحسان الأول وإثباته في الثاني»","url":""}]},{"id":"s28-93","number":93,"surah":28,"verses":[78],"references":[{"surah":28,"verses":[78]}],"verseLabel":"القصص: 78","question":"ما بلاغة القصر بـ﴿إِنَّمَا﴾ في قول قارون: ﴿إِنَّمَا أُوتِيتُهُ عَلَى عِلْمٍ عِنْدِي﴾؟","answer":"قصر سبب حصول المال على علم يملكه، ردًا على من ذكّره بفضل الله؛ فكشف القصر استحقاقه الموهوم وجحوده للمنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص630–631، تحت عنوان «بلاغة استعمال القصر بـ﴿إنما﴾»","url":""}]},{"id":"s28-202","number":202,"surah":28,"verses":[78],"references":[{"surah":28,"verses":[78]}],"verseLabel":"القصص: 78","question":"ما دلالة الوصف بالظرف ﴿عِنْدِي﴾؟","answer":"أوهم الظرف تمكن العلم منه واختصاصه به، فزاد دعوى الاستقلال والاستحقاق، وفضح غروره بأن ما عنده من علم ومال ذاتي لا فضل لله فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص634، تحت عنوان «دلالة الوصف بالظرف ﴿عندي﴾»","url":""}]},{"id":"s28-94","number":94,"surah":28,"verses":[79],"references":[{"surah":28,"verses":[79]}],"verseLabel":"القصص: 79","question":"ما نكتة التعبير بـ﴿عَلَى﴾ في قوله: ﴿فَخَرَجَ عَلَى قَوْمِهِ﴾؟","answer":"أفادت الاستعلاء الحقيقي أو المجازي، فصورت خروج قارون متعاليًا بزينته مستعرضًا بها على قومه لا خروجًا عاديًا بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص650، تحت عنوان «نكتة التعبير بـ﴿على﴾»","url":""}]},{"id":"s28-203","number":203,"surah":28,"verses":[79],"references":[{"surah":28,"verses":[79]}],"verseLabel":"القصص: 79","question":"ما موقع الجار والمجرور ﴿فِي زِينَتِهِ﴾ ودلالته؟","answer":"جاء حالًا من قارون، فصور الزينة كأنها ظرف يحيط به من كل جانب؛ وبذلك برز قصده إلى استعراض الثراء وفتنة الأنظار.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص651، تحت عنوان «موقع الجار والمجرور ودلالته»","url":""}]},{"id":"s28-95","number":95,"surah":28,"verses":[80],"references":[{"surah":28,"verses":[80]}],"verseLabel":"القصص: 80","question":"ما المراد بقول أهل العلم: ﴿وَيْلَكُمْ﴾؟","answer":"هو زجر وتنبيه للمغترين بزينة قارون، لا دعاء مقصود به الهلاك؛ هزوا به الغافلين ليرجعوا عن تمنّي المتاع الزائل.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص660، تحت عنوان «توجيه المراد بالويل مضافا»","url":""}]},{"id":"s28-204","number":204,"surah":28,"verses":[80],"references":[{"surah":28,"verses":[80]}],"verseLabel":"القصص: 80","question":"ما نكتة حذف المفضل عليه في قوله: ﴿ثَوَابُ اللَّهِ خَيْرٌ﴾؟","answer":"حذف المفضل عليه لتعم الخيرية كل ما تمنوه من مال قارون وزينته، وفي الحذف تعظيم لثواب الله حتى كأنه لا يقاس بشيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص662، تحت عنوان «نكتة حذف المفضل عليه»","url":""}]},{"id":"s28-205","number":205,"surah":28,"verses":[80],"references":[{"surah":28,"verses":[80]}],"verseLabel":"القصص: 80","question":"ما بلاغة القصر في قوله: ﴿وَلَا يُلَقَّاهَا إِلَّا الصَّابِرُونَ﴾؟","answer":"قصر نيل هذه الحكمة والثواب على الصابرين تثبيتًا لهم وتعظيمًا لمنزلتهم، وتعريضًا بأن المفتونين بزينة الدنيا لا يبلغونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص665–666، تحت عنوان «إيثار التعبير بالقصر نفيا واستثناء»","url":""}]},{"id":"s28-96","number":96,"surah":28,"verses":[81],"references":[{"surah":28,"verses":[81]}],"verseLabel":"القصص: 81","question":"ما دلالة الطباق في قوله: ﴿فَخَسَفْنَا بِهِ وَبِدَارِهِ الْأَرْضَ﴾؟","answer":"قابل الخسف المنخفض خروجه المتعالي بزينة ماله؛ فطابق الجزاء حاله، وانقلب الظهور والعلو إلى غياب في طبقات الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص671، تحت عنوان «دلالة الطباق في الآية»","url":""}]},{"id":"s28-206","number":206,"surah":28,"verses":[81],"references":[{"surah":28,"verses":[81]}],"verseLabel":"القصص: 81","question":"ما دلالة العطف في قوله: ﴿بِهِ وَبِدَارِهِ﴾؟","answer":"جمع قارون وداره في الخسف، فصور زواله مع ما اعتز به من ملك؛ لم تبق الدار ولم تنفعه، بل صارت شريكة له في العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص672، تحت عنوان «دلالة العطف بين المخسوفين»","url":""}]},{"id":"s28-97","number":97,"surah":28,"verses":[82],"references":[{"surah":28,"verses":[82]}],"verseLabel":"القصص: 82","question":"ما المعاني المحتملة لـ﴿وَيْكَأَنَّ﴾؟","answer":"تحتمل أن تكون للتنبيه أو التعجب، وقيل مركبة من ألفاظ متعددة؛ وفي جميع التوجيهات تصور يقظة المتمنين بعد العبرة وانتقالهم من الغفلة إلى اليقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص685–686، تحت عنوان «المعاني المحتملة لـ﴿ويكأن﴾»","url":""}]},{"id":"s28-207","number":207,"surah":28,"verses":[82],"references":[{"surah":28,"verses":[82]}],"verseLabel":"القصص: 82","question":"ما دلالة التعبير بعنوان الألوهية في قوله: ﴿اللَّهَ يَبْسُطُ الرِّزْقَ﴾؟","answer":"ذكر اسم الجلالة يقرر انفراد الله باستحقاق العبادة وتدبير الرزق بسطًا وقدرًا بحكمة؛ فلا يشارك قارون ولا غيره في هذا التصرف.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص686، تحت عنوان «دلالة التعبير بعنوان الألوهية»","url":""}]},{"id":"s28-208","number":208,"surah":28,"verses":[82],"references":[{"surah":28,"verses":[82]}],"verseLabel":"القصص: 82","question":"ما بلاغة التذييل بقوله: ﴿وَيْكَأَنَّهُ لَا يُفْلِحُ الْكَافِرُونَ﴾؟","answer":"ذيل اعترافهم بقاعدة عامة تؤكد العبرة: لا فلاح لمن يستر نعمة الله ويجحد المنعم؛ فصار هلاك قارون شاهدًا على وعيد كل كافر.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص697، تحت عنوان «بلاغة التذييل بجملة ﴿ويكأنه لا يفلح الكافرون﴾»","url":""}]},{"id":"s28-98","number":98,"surah":28,"verses":[83],"references":[{"surah":28,"verses":[83]}],"verseLabel":"القصص: 83","question":"ما بلاغة الكناية عن نفي الفعل بنفي الإرادة في قوله: ﴿لَا يُرِيدُونَ عُلُوًّا... وَلَا فَسَادًا﴾؟","answer":"نفي إرادة العلو والفساد أبلغ من نفي وقوعهما؛ لأنه يصور قلوبًا طاهرة لا تميل إليهما أصلًا، فينتفي الفعل من بابه الأول.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص707–708، تحت عنوان «بلاغة الكناية عن نفي الفعل بنفي الإرادة»","url":""}]},{"id":"s28-209","number":209,"surah":28,"verses":[83],"references":[{"surah":28,"verses":[83]}],"verseLabel":"القصص: 83","question":"ما دلالة العطف وتكرار النفي في قوله: ﴿لَا يُرِيدُونَ عُلُوًّا... وَلَا فَسَادًا﴾؟","answer":"كرر ﴿لا﴾ وعطف الفساد على العلو لينفي كل واحد استقلالًا؛ فلا يكفي ترك الاستكبار مع الإفساد ولا ترك الفساد مع طلب العلو.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص709، تحت عنوان «دلالة العطف والتكرار»","url":""}]},{"id":"s28-99","number":99,"surah":28,"verses":[84],"references":[{"surah":28,"verses":[84]}],"verseLabel":"القصص: 84","question":"ما بلاغة القصر في قوله: ﴿فَلَا يُجْزَى الَّذِينَ عَمِلُوا السَّيِّئَاتِ إِلَّا مَا كَانُوا يَعْمَلُونَ﴾؟","answer":"قصر جزاء السيئة على مثلها بلا زيادة، فجمع التهديد بالعدل؛ في مقابل مضاعفة الحسنة فضلًا من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص723–724، تحت عنوان «علة إيثار القصر نفيا واستثناء»","url":""}]},{"id":"s28-100","number":100,"surah":28,"verses":[85],"references":[{"surah":28,"verses":[85]}],"verseLabel":"القصص: 85","question":"ما بلاغة افتتاح قوله: ﴿إِنَّ الَّذِي فَرَضَ عَلَيْكَ الْقُرْآنَ لَرَادُّكَ إِلَى مَعَادٍ﴾ بالتوكيد؟","answer":"أكد الوعد بإن واللام تثبيتًا لفؤاد النبي وتسلية له في مقام الفراق والأذى، وردًا على من يستبعد عودته ونصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص730، تحت عنوان «بلاغة افتتاح الآية بالتوكيد»","url":""}]},{"id":"s28-210","number":210,"surah":28,"verses":[85],"references":[{"surah":28,"verses":[85]}],"verseLabel":"القصص: 85","question":"ما دلالة التعبير بالرد في قوله: ﴿لَرَادُّكَ﴾؟","answer":"الرد يقتضي رجوعًا إلى موطن أو مقام سبق الاتصال به؛ فأشار إلى مكة أو الآخرة أو المنزلة الكريمة التي يرد إليها، مع ضمان الإرجاع والعناية.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص733، تحت عنوان «دلالة التعبير بالرد في ﴿لرادك﴾»","url":""}]},{"id":"s28-211","number":211,"surah":28,"verses":[85],"references":[{"surah":28,"verses":[85]}],"verseLabel":"القصص: 85","question":"ما غرض الإخبار بالرد إلى معاد؟","answer":"الغرض التسلية والتثبيت والوعد بالمآل الحسن بعد الخروج؛ وتعددت وجوه المعاد بين مكة والبعث والجنة والمقام المحمود، وكلها تحمل بشارة الرجوع والعاقبة الكريمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص734، تحت عنوان «غرض الإخبار بالرد إلى معاد»","url":""}]},{"id":"s28-101","number":101,"surah":28,"verses":[85],"references":[{"surah":28,"verses":[85]}],"verseLabel":"القصص: 85","question":"ما دلالة التعبير بعنوان الربوبية في قوله: ﴿رَبِّي أَعْلَمُ﴾؟","answer":"ناسب عنوان الربوبية مقام الاحتجاج والوعد بالهدى؛ فالرب هو المربي المدبر الذي يعلم من جاء به ومن تكون له عاقبة الدار.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص737–738، تحت عنوان «دلالة التعبير بعنوان الربوبية في قوله: ﴿ربي﴾»","url":""}]},{"id":"s28-102","number":102,"surah":28,"verses":[86],"references":[{"surah":28,"verses":[86]}],"verseLabel":"القصص: 86","question":"لماذا نُفي رجاء إلقاء الكتاب لا إلقاؤه في قوله: ﴿وَمَا كُنْتَ تَرْجُو أَنْ يُلْقَى إِلَيْكَ الْكِتَابُ﴾؟","answer":"نفى التطلع السابق إلى الوحي ليظهر أن القرآن اصطفاء محض لم يخطط له النبي ولم ينتظره؛ فجاء الإلقاء رحمة مفاجئة وتكريمًا من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص750، تحت عنوان «سر نفي رجاء الإلقاء لا الإلقاء»","url":""}]},{"id":"s28-103","number":103,"surah":28,"verses":[87],"references":[{"surah":28,"verses":[87]}],"verseLabel":"القصص: 87","question":"ما نكتة نون التوكيد في قوله: ﴿وَلَا يَصُدُّنَّكَ﴾؟","answer":"شددت النون النهي عن الاستجابة لأي صد عن آيات الله، وعظمت خطر الإعراض بعد نزول الوحي، مع أن الخطاب تثبيت للنبي وتعريض بمن يحاول صده.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص760، تحت عنوان «نكتة الإتيان بنون التوكيد في ﴿ولا يصدنك﴾»","url":""}]},{"id":"s28-212","number":212,"surah":28,"verses":[87],"references":[{"surah":28,"verses":[87]}],"verseLabel":"القصص: 87","question":"ما بلاغة التقييد بالبعدية في قوله: ﴿بَعْدَ إِذْ أُنْزِلَتْ إِلَيْكَ﴾؟","answer":"قيد النهي بما بعد الإنزال لبيان كمال قبح الصد بعد ظهور الحق وقيام الحجة؛ فبعد وصول الآيات لا يبقى إلا الثبات على تلاوتها والعمل بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص762، تحت عنوان «بلاغة التقييد بالبعدية»","url":""}]},{"id":"s28-104","number":104,"surah":28,"verses":[88],"references":[{"surah":28,"verses":[88]}],"verseLabel":"القصص: 88","question":"ما علة فصل قوله: ﴿كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ﴾ عما قبله؟","answer":"جاءت الجملة تقريرًا مستقلًا وتعليلًا للنهي عن دعاء إله آخر؛ فما سوى الله هالك، فلا يستحق العبادة إلا الباقي سبحانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص774، تحت عنوان «علة فصل ﴿كل شيء هالك إلا وجهه﴾ عما قبله»","url":""}]},{"id":"s28-213","number":213,"surah":28,"verses":[88],"references":[{"surah":28,"verses":[88]}],"verseLabel":"القصص: 88","question":"ما سر تعدد الجمل في قوله: ﴿كُلُّ شَيْءٍ هَالِكٌ... لَهُ الْحُكْمُ وَإِلَيْهِ تُرْجَعُونَ﴾؟","answer":"تتابعت الجمل لتقيم صفات التوحيد كاملة: بقاء الله وفناء ما سواه، وانفراده بالحكم، ومرجع الخلق إليه؛ فكل جملة تؤكد الأخرى وتبطل الشرك من جهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص779، تحت عنوان «سر تعدد الجمل في الآية»","url":""}]},{"id":"s28-214","number":214,"surah":28,"verses":[88],"references":[{"surah":28,"verses":[88]}],"verseLabel":"القصص: 88","question":"ما بلاغة رد العجز على الصدر في ختام سورة القصص؟","answer":"عاد آخر السورة إلى أولها؛ فالكتاب المبين عرض سنن الله في نجاة المؤمنين وهلاك الطغاة، ثم ختم بانفراد الله بالحكم والرجوع إليه، فانتظم المطلع والختام في مقصد واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص779، تحت عنوان «بلاغة رد العجز على الصدر»","url":""}]},{"id":"s28-105","number":105,"surah":28,"verses":[88],"references":[{"surah":28,"verses":[88]}],"verseLabel":"القصص: 88","question":"ما بلاغة الوصل بالواو في قوله: ﴿وَإِلَيْهِ تُرْجَعُونَ﴾؟","answer":"وصل الرجوع بالحكم لأن الجزاء ثمرة القضاء؛ فكما انفرد الله بالحكم كان مرجع الخلق جميعًا إليه للحساب والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص777، تحت عنوان «بلاغة الوصل بالواو في ﴿وإليه﴾»","url":""}]},{"id":"s28-106","number":106,"surah":28,"verses":[20],"references":[{"surah":28,"verses":[20]},{"surah":36,"verses":[20]}],"verseLabel":"القصص: 20؛ يس: 20","question":"لماذا قُدّم ﴿رَجُلٌ﴾ في القصص، وقُدّم ﴿مِنْ أَقْصَى الْمَدِينَةِ﴾ في يس؟","answer":"في القصص كان المقصود إبراز شجاعة الرجل الذي بادر إلى إنذار موسى، فقدم الفاعل على الأصل. وفي يس قدم بُعد المكان لإظهار بلوغ دعوة الرسل أقصى المدينة ودفع تهمة تواطؤ الرجل معهم؛ فناسب كل ترتيب مقامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص562–563، تحت عنوان «توجيه المتشابه اللفظي»","url":""}]},{"id":"s29-1","number":1,"surah":29,"verses":[1],"references":[{"surah":29,"verses":[1]}],"verseLabel":"العنكبوت: 1","question":"ما وجه استهلال سورة العنكبوت بالحروف المقطعة ﴿الم﴾؟","answer":"وجه المبحث استهلال السورة بالحروف المقطعة إلى تنبيه المخاطب لما سيذكر بعدها من تكاليف الإيمان. فليس التلفظ بالإيمان كافيًا دون تحمل ما يتبعه من امتحان؛ وجاء الافتتاح ليهيئ السامع لهذا المعنى العظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص795، تحت عنوان «براعة الاستهلال بالحروف المقطعة»","url":""}]},{"id":"s29-2","number":2,"surah":29,"verses":[2],"references":[{"surah":29,"verses":[2]}],"verseLabel":"العنكبوت: 2","question":"ما سرّ الاستفهام في ﴿أَحَسِبَ النَّاسُ أَنْ يُتْرَكُوا أَنْ يَقُولُوا آمَنَّا﴾؟","answer":"الاستفهام إنكاري توبيخي، وينفي حسبانهم أن مجرد قول «آمنا» يقتضي تركهم بلا امتحان. وفيه تقرير أن الابتلاء سنة تمتحن حقيقة الإيمان، لا أمر مستبعد عن المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص796، تحت عنوان «بلاغة الاستفهام في ﴿أحسب﴾»","url":""}]},{"id":"s29-3","number":3,"surah":29,"verses":[2],"references":[{"surah":29,"verses":[2]}],"verseLabel":"العنكبوت: 2","question":"ما نكتة بناء ﴿يُتْرَكُوا﴾ و﴿يُفْتَنُونَ﴾ للمفعول؟","answer":"بُني الفعلان للمفعول لأن المقصود وقوع الابتلاء لا تعيين فاعله؛ فالفتنة قد تأتي من جهات شتى، وفي الحذف تعميم لمصادرها وتركيز على ثبات المؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص798، تحت عنوان «نكتة بناء ﴿يتركوا﴾ و﴿يفتنون﴾ للمفعول»","url":""}]},{"id":"s29-63","number":63,"surah":29,"verses":[2],"references":[{"surah":29,"verses":[2]}],"verseLabel":"العنكبوت: 2","question":"ما دلالة التعبير بالفتن في قوله: ﴿وَهُمْ لَا يُفْتَنُونَ﴾؟","answer":"اختيرت الفتنة لأنها تجمع اختبار الإيمان بما يضطرب له الإنسان من خوف وأذى في النفس والمال؛ فدل اللفظ على شدة الابتلاء وتنوعه وتجدد وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص799–800، تحت عنوان «دلالة التعبير بالفتن في ﴿لا يفتنون﴾»","url":""}]},{"id":"s29-4","number":4,"surah":29,"verses":[3],"references":[{"surah":29,"verses":[3]}],"verseLabel":"العنكبوت: 3","question":"ما أوجه معنى ﴿فَلَيَعْلَمَنَّ اللَّهُ الَّذِينَ صَدَقُوا﴾ مع سبق علم الله؟","answer":"علم الله سابق لا يتجدد عن جهل. وذكر المبحث أن التعبير كناية عن الجزاء المبني على ظهور الصدق والكذب، أو عن تعلق العلم بالمعلوم عند وقوعه، أو أن المراد التمييز بين الصادق والكاذب بإظهار ما علمه الله من حالهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص804، تحت عنوان «بلاغة الجملة في ﴿فليعلمن الله الذين صدقوا﴾»","url":""}]},{"id":"s29-5","number":5,"surah":29,"verses":[4],"references":[{"surah":29,"verses":[4]}],"verseLabel":"العنكبوت: 4","question":"ما بلاغة ﴿أَمْ﴾ في قوله: ﴿أَمْ حَسِبَ الَّذِينَ يَعْمَلُونَ السَّيِّئَاتِ﴾؟","answer":"هي أم المنقطعة المتضمنة معنى بل وهمزة الإنكار؛ انتقلت من إنكار ترك المؤمنين بلا فتنة إلى توبيخ المسيئين على ظنهم الإفلات من قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص11، تحت عنوان «بلاغة التعبير بـ﴿أم﴾»","url":""}]},{"id":"s29-64","number":64,"surah":29,"verses":[4],"references":[{"surah":29,"verses":[4]}],"verseLabel":"العنكبوت: 4","question":"ما بلاغة المجاز في قوله: ﴿أَنْ يَسْبِقُونَا﴾؟","answer":"صوّر إفلات المسيئين من الجزاء بسباق يتقدمون فيه حتى يعجز الطالب عن إدراكهم؛ فهدم بهذا التصوير وهمهم في النجاة من سلطان الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص15، تحت عنوان «بلاغة المجاز في ﴿أن يسبقونا﴾»","url":""}]},{"id":"s29-6","number":6,"surah":29,"verses":[5],"references":[{"surah":29,"verses":[5]}],"verseLabel":"العنكبوت: 5","question":"ما دلالة قوله: ﴿فَإِنَّ أَجَلَ اللَّهِ لَآتٍ﴾؟","answer":"قرر أن الوقت الذي حدده الله للقاء والثواب والحساب واقع لا يتخلف؛ فطمأن المؤمنين بوعده وحثهم على الثبات والاستعداد.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص22–23، تحت عنوان «دلالة التعبير بـ﴿فإن أجل الله لآت﴾»","url":""}]},{"id":"s29-65","number":65,"surah":29,"verses":[5],"references":[{"surah":29,"verses":[5]}],"verseLabel":"العنكبوت: 5","question":"ما غرض توكيد قوله: ﴿فَإِنَّ أَجَلَ اللَّهِ لَآتٍ﴾؟","answer":"أكدت الجملة بإن واللام إزالة للتردد في البعث والوعد، وتحريضًا على الاستعداد للقاء الله، ولا سيما مع إنكار المشركين له.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص23–24، تحت عنوان «غرض توكيد ﴿فإن أجل الله لآت﴾»","url":""}]},{"id":"s29-7","number":7,"surah":29,"verses":[6],"references":[{"surah":29,"verses":[6]}],"verseLabel":"العنكبوت: 6","question":"ما دلالة التعبير بالنفس في قوله: ﴿لِنَفْسِهِ﴾؟","answer":"أبرز لفظ النفس حاجتها هي إلى مجاهدة الهوى وإصلاحها والارتقاء بها؛ فالمجاهدة منفعتها راجعة إلى ذات المجاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص30، تحت عنوان «دلالة التعبير بالنفس في ﴿لنفسه﴾»","url":""}]},{"id":"s29-66","number":66,"surah":29,"verses":[6],"references":[{"surah":29,"verses":[6]}],"verseLabel":"العنكبوت: 6","question":"ما علة فصل جملة ﴿إِنَّ اللَّهَ لَغَنِيٌّ عَنِ الْعَالَمِينَ﴾ عما قبلها؟","answer":"فُصلت لأنها تقرير وتعليل لمعنى قصر نفع الجهاد على صاحبه؛ فغنى الله عن العالمين يبين أنه لا يحتاج إلى جهادهم، وإنما شرعه رحمةً وإصلاحًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص30، تحت عنوان «علة فصل جملة: ﴿إن الله لغني عن العالمين﴾»","url":""}]},{"id":"s29-8","number":8,"surah":29,"verses":[7],"references":[{"surah":29,"verses":[7]}],"verseLabel":"العنكبوت: 7","question":"ما معنى الواو في قوله: ﴿وَلَنَجْزِيَنَّهُمْ﴾؟","answer":"عطفت الواو الجزاء على تكفير السيئات، فجمعت للمؤمنين إزالة الذنب وإثابة العمل؛ وفي الجمع إظهار لتفضل الله عليهم من جهتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص41–42، تحت عنوان «معنى (الواو) في جملة ﴿ولنجزينهم﴾»","url":""}]},{"id":"s29-9","number":9,"surah":29,"verses":[8],"references":[{"surah":29,"verses":[8]}],"verseLabel":"العنكبوت: 8","question":"ما دلالة أل في قوله: ﴿وَوَصَّيْنَا الْإِنْسَانَ﴾؟","answer":"أل للجنس، فشملت الوصية كل إنسان ذكرًا وأنثى، وأفادت عموم التكليف بالإحسان إلى الوالدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص50–51، تحت عنوان «دلالة (أل) في ﴿الإنسان﴾»","url":""}]},{"id":"s29-67","number":67,"surah":29,"verses":[8],"references":[{"surah":29,"verses":[8]}],"verseLabel":"العنكبوت: 8","question":"كيف وُجّه الجمع بين الإحسان إلى الوالدين وعدم طاعتهما في الشرك؟","answer":"الإحسان إليهما واجب، لكنه لا يستلزم طاعتهما في معصية الخالق؛ فيُصاحبان بالبر ويُرد أمر الشرك، ثم المرجع إلى الله للحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص59–60، تحت عنوان «توجيه الجمع بين الإحسان وعدم الطاعة للوالدين»","url":""}]},{"id":"s29-10","number":10,"surah":29,"verses":[8],"references":[{"surah":29,"verses":[8]}],"verseLabel":"العنكبوت: 8","question":"ما سرّ التعبير عن الشريك بـ﴿مَا لَيْسَ لَكَ بِهِ عِلْمٌ﴾؟","answer":"نفي العلم كناية عن نفي الحقيقة؛ فلا دليل يمكن أن يقوم على شريك معدوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص58–59، تحت عنوان «نكتة تعليق النهي عن الإشراك على انتفاء العلم»","url":""}]},{"id":"s29-11","number":11,"surah":29,"verses":[10],"references":[{"surah":29,"verses":[10]}],"verseLabel":"العنكبوت: 10","question":"ما سرّ التعبير عن المنافق بـ﴿فَإِذَا أُوذِيَ فِي اللَّهِ جَعَلَ فِتْنَةَ النَّاسِ كَعَذَابِ اللَّهِ﴾؟","answer":"شبه فتنة الناس بعذاب الله في أثرها عليه: كما يحمل الخوف من عذاب الله المؤمن على اجتناب الكفر، حمله خوف أذى الناس على ترك الإيمان. ففضح التشبيه فساد ميزانه؛ إذ سوى بين أمرين متفاوتين غاية التفاوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص79، تحت عنوان «بلاغة تشبيه الفتنة بالعذاب»","url":""}]},{"id":"s29-12","number":12,"surah":29,"verses":[10],"references":[{"surah":29,"verses":[10]}],"verseLabel":"العنكبوت: 10","question":"ما غرض التوكيد في قول المنافقين: ﴿إِنَّا كُنَّا مَعَكُمْ﴾؟","answer":"راكموا التوكيد بإن والجملة الاسمية وكان ليظهروا صدق دعواهم الكاذبة وليستميلوا المؤمنين عند النصر؛ فكثرة التوكيد تكشف اضطرابهم وحاجتهم إلى إثبات ما ليس واقعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص83–84، تحت عنوان «غرض التوكيد في جملة ﴿إنا كنا معكم﴾»","url":""}]},{"id":"s29-68","number":68,"surah":29,"verses":[10],"references":[{"surah":29,"verses":[10]}],"verseLabel":"العنكبوت: 10","question":"ما دلالة المعية في قولهم: ﴿كُنَّا مَعَكُمْ﴾؟","answer":"ادعوا المصاحبة في الدين والنصرة لا مجرد القرب، ليشاركوا المؤمنين ثمرة النصر من غير أن يتحملوا مشقته.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص84، تحت عنوان «دلالة المعية في ﴿معكم﴾»","url":""}]},{"id":"s29-13","number":13,"surah":29,"verses":[12],"references":[{"surah":29,"verses":[12]}],"verseLabel":"العنكبوت: 12","question":"ما معنى اللام ودلالة الأمر في قوله: ﴿وَلْنَحْمِلْ خَطَايَاكُمْ﴾؟","answer":"اللام لام الأمر، وقد وجه الكافرون الأمر إلى أنفسهم في صورة تعهد مؤكد بالحمل؛ فبالغوا في الإغراء بالاتباع مع أن وعدهم باطل لا يملكون الوفاء به.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص100، تحت عنوان «معنى (اللام)، ودلالة الأمر ﴿ولنحمل﴾»","url":""}]},{"id":"s29-69","number":69,"surah":29,"verses":[12],"references":[{"surah":29,"verses":[12]}],"verseLabel":"العنكبوت: 12","question":"ما علة فصل جملة ﴿إِنَّهُمْ لَكَاذِبُونَ﴾ عما قبلها؟","answer":"فُصلت لأنها حكم إلهي اعتراضي مستقل يكذب وعدهم، وليست من تمام مقولهم؛ فجاءت مؤكدة لتزيل كل ظن بصدقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص104، تحت عنوان «علة فصل جملة ﴿إنهم لكاذبون﴾ عما قبلها»","url":""}]},{"id":"s29-14","number":14,"surah":29,"verses":[13],"references":[{"surah":29,"verses":[13]}],"verseLabel":"العنكبوت: 13","question":"ما معنى الواو في قوله: ﴿وَلَيَحْمِلُنَّ أَثْقَالَهُمْ﴾؟","answer":"عطفت الواو ما يحمله المضلون من أوزار إضلال غيرهم على أوزار أنفسهم؛ فردت دعواهم حمل خطايا الأتباع وبينت أنهم يزدادون أثقالًا ولا ينقصون عن أحد شيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص105، تحت عنوان «معنى (الواو) في قوله: ﴿وليحملن أثقالهم﴾»","url":""}]},{"id":"s29-70","number":70,"surah":29,"verses":[13],"references":[{"surah":29,"verses":[13]}],"verseLabel":"العنكبوت: 13","question":"ما دلالة تنكير ﴿أَثْقَالًا﴾ وما فائدة الجناس في الآية؟","answer":"نكرت أثقالًا للتكثير والتهويل، وجانس اللفظ بين أثقالهم وأثقالًا لتصوير تراكم أوزارهم الذاتية وأوزار من أضلوهم في عبارة متماسكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص107–108، تحت عنوان «دلالة تنكير ﴿وأثقالا﴾ وفائدة الجناس»","url":""}]},{"id":"s29-15","number":15,"surah":29,"verses":[14],"references":[{"surah":29,"verses":[14]}],"verseLabel":"العنكبوت: 14","question":"ما نكتة التعبير بمفردة ﴿أَلْفَ﴾ في مدة لبث نوح؟","answer":"ذكر الألف يجسم طول المدة في السمع ويعظم صبر نوح وشدة إصرار قومه؛ فهو عدد بالغ يلفت إلى امتداد الدعوة والابتلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص120، تحت عنوان «نكتة التعبير بمفردة الـ﴿ألف﴾»","url":""}]},{"id":"s29-71","number":71,"surah":29,"verses":[14],"references":[{"surah":29,"verses":[14]}],"verseLabel":"العنكبوت: 14","question":"ما معنى ﴿إِلَّا﴾ في قوله: ﴿إِلَّا خَمْسِينَ عَامًا﴾؟","answer":"الاستثناء يحقق العدد ويحدد المدة بدقة بعد ذكر الألف، وفي إخراج الخمسين إبراز لطول ما بقي منها من غير إجمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص121، تحت عنوان «معنى ﴿إلا﴾ في قوله: ﴿إلا خمسين عاما﴾»","url":""}]},{"id":"s29-16","number":16,"surah":29,"verses":[14],"references":[{"surah":29,"verses":[14]}],"verseLabel":"العنكبوت: 14","question":"ما نكتة المغايرة بين ﴿سَنَةٍ﴾ و﴿عَامًا﴾ في الآية؟","answer":"اختيرت السنة لمدة الدعوة لما فيها من شدة وعناء مع عناد القوم، واختير العام للخمسين المستثناة لما ارتبط بها من رخاء ونجاة بعد الطوفان؛ فناسب كل لفظ حاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص121، تحت عنوان «نكتة المغايرة بين تمييز الأول بالسنة والثاني بالعام»","url":""}]},{"id":"s29-17","number":17,"surah":29,"verses":[15],"references":[{"surah":29,"verses":[15]}],"verseLabel":"العنكبوت: 15","question":"ما أوجه عود الضمير المؤنث في ﴿وَجَعَلْنَاهَا آيَةً لِلْعَالَمِينَ﴾؟","answer":"يحتمل أن يعود الضمير إلى السفينة المعهودة، أو إلى جنس السفن بوصفها نعمة وعلامة على القدرة، أو إلى حادثة إغراق قوم نوح وإنجائه ومن معه. وفي كل وجه يظهر جعل ذلك آية وعبرة للعالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص132–133، تحت عنوان «دلالة مرجع الضمير (ها) في ﴿وجعلناها﴾»","url":""}]},{"id":"s29-18","number":18,"surah":29,"verses":[16],"references":[{"surah":29,"verses":[16]}],"verseLabel":"العنكبوت: 16","question":"ما بلاغة عطف الأمر ﴿اتَّقُوهُ﴾ على ﴿اعْبُدُوا اللَّهَ﴾؟","answer":"جمع بين أصل الدين وحمايته: فالعبادة إخلاص الطاعة لله، والتقوى اتقاء الشرك والمعصية، وباجتماعهما يستقيم العمل ظاهرًا وباطنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص144–145، تحت عنوان «بلاغة عطف الأمر (اتقوا) على (اعبدوا)»","url":""}]},{"id":"s29-72","number":72,"surah":29,"verses":[16],"references":[{"surah":29,"verses":[16]}],"verseLabel":"العنكبوت: 16","question":"ما علاقة جملة ﴿ذَلِكُمْ خَيْرٌ لَكُمْ﴾ بما قبلها؟","answer":"جاءت تعليلًا للأمر بالعبادة والتقوى وترغيبًا فيهما؛ فالإشارة تعظم المأمور به وتقرر أن نفعه عائد إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص145، تحت عنوان «علاقة جملة ﴿ذلكم خير لكم﴾ بما قبلها»","url":""}]},{"id":"s29-73","number":73,"surah":29,"verses":[16],"references":[{"surah":29,"verses":[16]}],"verseLabel":"العنكبوت: 16","question":"ما معنى ﴿إِنْ﴾ ودلالتها في قوله: ﴿إِنْ كُنْتُمْ تَعْلَمُونَ﴾؟","answer":"هي شرطية تستنهض العلم الصحيح: فإن كانوا يعلمون حقًا لزمهم أن يدركوا خير العبادة والتقوى ويستجيبوا، وفيها تعريض بجهل من يخالف.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص147–148، تحت عنوان «معنى ﴿إن﴾ ودلالتها في ﴿إن كنتم تعلمون﴾»","url":""}]},{"id":"s29-19","number":19,"surah":29,"verses":[17],"references":[{"surah":29,"verses":[17]}],"verseLabel":"العنكبوت: 17","question":"لماذا أوثر التعبير بـ﴿تَخْلُقُونَ﴾ مادة وصيغة؟","answer":"أفاد الفعل أنهم يخترعون الأوثان وألوهيتها من غير أصل، وصيغة المضارع تصور استمرارهم وتجدد افترائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص156، تحت عنوان «إيثار التعبير بـ﴿وتخلقون﴾ مادة وصيغة»","url":""}]},{"id":"s29-20","number":20,"surah":29,"verses":[17],"references":[{"surah":29,"verses":[17]}],"verseLabel":"العنكبوت: 17","question":"ما بلاغة العطف بالفاء في قوله: ﴿فَابْتَغُوا عِنْدَ اللَّهِ الرِّزْقَ﴾؟","answer":"رتبت الفاء الأمر بطلب الرزق من الله على عجز الأوثان عن رزقهم؛ فإذا بطل رزقها لزم المبادرة إلى الرازق الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص161–162، تحت عنوان «بلاغة العطف بالفاء»","url":""}]},{"id":"s29-74","number":74,"surah":29,"verses":[17],"references":[{"surah":29,"verses":[17]}],"verseLabel":"العنكبوت: 17","question":"ما دلالة عطف العبادة على ابتغاء الرزق في قوله: ﴿وَاعْبُدُوهُ﴾؟","answer":"عطف العبادة على طلب الرزق ليدل على أن الرازق الحقيقي هو وحده المستحق للعبادة، وأن طلب العطاء لا ينفصل عن توحيده وطاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص163–164، تحت عنوان «دلالة عطف العبادة على ابتغاء الرزق»","url":""}]},{"id":"s29-21","number":21,"surah":29,"verses":[17],"references":[{"surah":29,"verses":[17]}],"verseLabel":"العنكبوت: 17","question":"ما سرّ التعبير في قول إبراهيم ﴿وَاشْكُرُوا لَهُ﴾ بدل «واشكروه»؟","answer":"تفيد اللام اختصاص الله بالشكر واستحقاقه له، مع ملاحظة إحسانه إلى عباده؛ فهو المنعم الذي يطلبون منه الرزق ويخلصون له العبادة والشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص165، تحت عنوان «سر تعدية الشكر باللام في قوله ﴿له﴾»","url":""}]},{"id":"s29-22","number":22,"surah":29,"verses":[18],"references":[{"surah":29,"verses":[18]}],"verseLabel":"العنكبوت: 18","question":"ما سر إيثار التعبير بالفعل ﴿تُقْلَبُونَ﴾؟","answer":"اختير القلب لتصوير التحول القهري من حال إلى حال: من الحياة إلى الموت ثم البعث والجزاء، وما يعقبه من انقلاب أحوال المؤمن والكافر.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص225–226، تحت عنوان «سر إيثار التعبير بالفعل ﴿تقلبون﴾ مادة وصيغة»","url":""}]},{"id":"s29-23","number":23,"surah":29,"verses":[19],"references":[{"surah":29,"verses":[19]}],"verseLabel":"العنكبوت: 19","question":"ما بلاغة الاستفهام في قوله: ﴿أَوَلَمْ يَرَوْا﴾؟","answer":"الاستفهام للإنكار والتوبيخ على إنكار البعث مع وضوح دليله، ويدعوهم إلى الاعتبار ببداية الخلق التي يشاهدون آثارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص187، تحت عنوان «بلاغة الاستفهام في قوله ﴿أولم يروا﴾»","url":""}]},{"id":"s29-75","number":75,"surah":29,"verses":[19],"references":[{"surah":29,"verses":[19]}],"verseLabel":"العنكبوت: 19","question":"ما دلالة التعبير بلفظ الرؤية في قوله: ﴿أَوَلَمْ يَرَوْا﴾؟","answer":"عبر بالرؤية لأنها أقرب طرق اليقين؛ فآثار بدء الخلق متجددة أمام الأبصار في المواليد والنبات، ومنها ينتقل العقل إلى إمكان الإعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص188، تحت عنوان «دلالة التعبير بلفظ الرؤية هنا»","url":""}]},{"id":"s29-76","number":76,"surah":29,"verses":[19],"references":[{"surah":29,"verses":[19]}],"verseLabel":"العنكبوت: 19","question":"ما دلالة التعبير بفعل البدء في قوله: ﴿يُبْدِئُ اللَّهُ الْخَلْقَ﴾؟","answer":"يدل البدء على الإيجاد من العدم، وجاء مضارعًا لتجدد شواهده؛ فمن قدر على الإنشاء أولًا قدر على الإعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص190، تحت عنوان «دلالة التعبير بفعل البدء دون سواه»","url":""}]},{"id":"s29-77","number":77,"surah":29,"verses":[19],"references":[{"surah":29,"verses":[19]}],"verseLabel":"العنكبوت: 19","question":"ما علاقة عبارة ﴿ثُمَّ يُعِيدُهُ﴾ بما قبلها ودلالتها؟","answer":"عطفت الإعادة على البدء لتجعلها نتيجة ثابتة لدليل الخلق الأول، وثم تبرز تفاوت الرتبة في تصورهم مع أن الإعادة على الله يسيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص192، تحت عنوان «علاقة عبارة ﴿ثم يعيده﴾ بما سبق ودلالتها»","url":""}]},{"id":"s29-24","number":24,"surah":29,"verses":[20],"references":[{"surah":29,"verses":[20]}],"verseLabel":"العنكبوت: 20","question":"ما الغرض من الأمر في قوله: ﴿سِيرُوا فِي الْأَرْضِ﴾؟","answer":"الأمر للإرشاد والحث على السفر المتأمل؛ فتغير المشاهد يوقظ الحس والعقل لرؤية دلائل قدرة الله في أصناف الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص203، تحت عنوان «الغرض من التعبير بالأمر»","url":""}]},{"id":"s29-78","number":78,"surah":29,"verses":[20],"references":[{"surah":29,"verses":[20]}],"verseLabel":"العنكبوت: 20","question":"ما بلاغة العطف بالفاء في قوله: ﴿فَانْظُرُوا كَيْفَ بَدَأَ الْخَلْقَ﴾؟","answer":"رتبت الفاء النظر على السير؛ فالسير وسيلة، والاعتبار بما تكشفه مشاهد الأرض غايته وثمرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص204، تحت عنوان «بلاغة العطف بالفاء»","url":""}]},{"id":"s29-79","number":79,"surah":29,"verses":[20],"references":[{"surah":29,"verses":[20]}],"verseLabel":"العنكبوت: 20","question":"لماذا أوثر التعبير بالنظر في قوله: ﴿فَانْظُرُوا﴾؟","answer":"أوثر النظر لأنه إدراك بالبصر هو أولى طرق العلم وأظهرها في هذا المقام، ثم يعبر منه العقل إلى معرفة قدرة الخالق.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص204، تحت عنوان «إيثار التعبير بالنظر دون سواه»","url":""}]},{"id":"s29-25","number":25,"surah":29,"verses":[20],"references":[{"surah":29,"verses":[20]}],"verseLabel":"العنكبوت: 20","question":"ما سر ذكر المسند إليه صريحًا بعد إضماره في قوله: ﴿ثُمَّ اللَّهُ يُنْشِئُ﴾؟","answer":"أظهر المسند إليه بعد أن كان مفهومًا لرفع شأن أمر النشأة الآخرة وتقرير أن منشئها هو خالق البداية نفسه، فلا يشاركه فيها أحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص207–208، تحت عنوان «سر ذكر المسند إليه صريحا بعد إضماره»","url":""}]},{"id":"s29-80","number":80,"surah":29,"verses":[20],"references":[{"surah":29,"verses":[20]}],"verseLabel":"العنكبوت: 20","question":"ما فائدة التصريح بالاسم الجليل في قوله: ﴿ثُمَّ اللَّهُ يُنْشِئُ﴾؟","answer":"اختير اسم الله الجامع لصفات الجلال والكمال ليكون أوقع في إثبات القدرة على الإعادة وأبلغ في توكيد الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص208، تحت عنوان «فائدة التصريح بالاسم الجليل»","url":""}]},{"id":"s29-26","number":26,"surah":29,"verses":[22],"references":[{"surah":29,"verses":[22]}],"verseLabel":"العنكبوت: 22","question":"ما سر التقييد بالجار والمجرور في قوله: ﴿فِي الْأَرْضِ﴾؟","answer":"استوعب القيد كل مكان من الأرض ظاهرًا وباطنًا؛ فلا يملك أحد الإفلات من قدرة الله أينما تقلب فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص233، تحت عنوان «سر التقييد بالجار والمجرور»","url":""}]},{"id":"s29-81","number":81,"surah":29,"verses":[22],"references":[{"surah":29,"verses":[22]}],"verseLabel":"العنكبوت: 22","question":"ما بلاغة العطف في قوله: ﴿وَلَا فِي السَّمَاءِ﴾؟","answer":"عطف السماء على الأرض ليغلق كل متوهم للهرب، ويقرر إحاطة القدرة الإلهية بالعالمين وأن النجاة من سلطان الله ممتنعة في كليهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص234، تحت عنوان «بلاغة العطف في قوله ﴿ولا في السماء﴾»","url":""}]},{"id":"s29-27","number":27,"surah":29,"verses":[23],"references":[{"surah":29,"verses":[23]}],"verseLabel":"العنكبوت: 23","question":"ما سرّ التعبير بالماضي في ﴿أُولَئِكَ يَئِسُوا مِنْ رَحْمَتِي﴾؟","answer":"من وجوهه أن اليأس يوم القيامة صُوّر بالماضي لتحقيق وقوعه، كأنه حصل وانقضى. وذكر المبحث وجهًا آخر: أن المراد حالهم في الدنيا، إذ أيسوا من الرحمة بإنكار البعث والثواب وعدم المبالاة بها؛ فلا ينحصر التعبير في الوجه الأول.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص250–251، تحت عنوان «دلالة التعبير بالفعل ﴿يئسوا﴾ ماضيا»","url":""}]},{"id":"s29-28","number":28,"surah":29,"verses":[24],"references":[{"surah":29,"verses":[24]}],"verseLabel":"العنكبوت: 24","question":"ما دلالة العطف بالحرف ﴿أَوْ﴾ في قولهم: ﴿اقْتُلُوهُ أَوْ حَرِّقُوهُ﴾؟","answer":"أفادت أو ترددهم واختلافهم في وسيلة التخلص منه، لا ترددهم في إرادة إيذائه؛ فكشفت اضطرابهم مع اجتماعهم على الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص265، تحت عنوان «دلالة العطف بالحرف ﴿أو﴾»","url":""}]},{"id":"s29-82","number":82,"surah":29,"verses":[24],"references":[{"surah":29,"verses":[24]}],"verseLabel":"العنكبوت: 24","question":"ما دلالة صيغة التضعيف في قوله: ﴿حَرِّقُوهُ﴾؟","answer":"دل التضعيف على المبالغة في الإحراق واستيعاب الجسد بالنار؛ فصور شدة حقدهم وتصعيدهم للعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص266، تحت عنوان «دلالة التعبير بصيغة التضعيف في ﴿حرقوه﴾»","url":""}]},{"id":"s29-29","number":29,"surah":29,"verses":[25],"references":[{"surah":29,"verses":[25]}],"verseLabel":"العنكبوت: 25","question":"ما سر إيثار المفعول لأجله ﴿مَوَدَّةَ بَيْنِكُمْ﴾؟","answer":"كشف المفعول لأجله أن اتخاذ الأوثان قام على مودة دنيوية متبادلة لا على برهان؛ فاتخذوها رابطًا اجتماعيًا يوافق أهواءهم، وهي رابطة مؤقتة تزول يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص275، تحت عنوان «سر إيثار المفعول لأجله: ﴿مودة﴾»","url":""}]},{"id":"s29-83","number":83,"surah":29,"verses":[25],"references":[{"surah":29,"verses":[25]}],"verseLabel":"العنكبوت: 25","question":"ما دلالة العطف بـ﴿ثُمَّ﴾ في قوله: ﴿ثُمَّ يَوْمَ الْقِيَامَةِ يَكْفُرُ بَعْضُكُمْ بِبَعْضٍ﴾؟","answer":"أفادت ثم التراخي الزماني والرتبي؛ فبعد طول المودة في الدنيا تنقلب يوم القيامة إلى براءة وعداوة، وفي ذلك تعظيم لهول التحول.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص278، تحت عنوان «بيان المراد من العطف بـ﴿ثم﴾»","url":""}]},{"id":"s29-84","number":84,"surah":29,"verses":[25],"references":[{"surah":29,"verses":[25]}],"verseLabel":"العنكبوت: 25","question":"ما دلالة العطف في قوله: ﴿وَيَلْعَنُ بَعْضُكُمْ بَعْضًا﴾؟","answer":"عطف اللعن على الكفر المتبادل ليصور تمام انقطاع المودة؛ فلا يكتفون بالتبرؤ، بل يدعو بعضهم على بعض بالطرد من الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص281، تحت عنوان «دلالة العطف في قوله ﴿ويلعن﴾»","url":""}]},{"id":"s29-30","number":30,"surah":29,"verses":[26],"references":[{"surah":29,"verses":[26]}],"verseLabel":"العنكبوت: 26","question":"لماذا أوثر التعبير بصفة الربوبية في قوله: ﴿إِلَى رَبِّي﴾؟","answer":"استحضرت الربوبية عناية الله وتربيته لعبده المهاجر، وقابلت ربَّه الحق بالأرباب الباطلة التي فارقها قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص294، تحت عنوان «إيثار التعبير بصفة الربوبية»","url":""}]},{"id":"s29-31","number":31,"surah":29,"verses":[27],"references":[{"surah":29,"verses":[27]}],"verseLabel":"العنكبوت: 27","question":"ما دلالة العطف في قوله: ﴿وَجَعَلْنَا فِي ذُرِّيَّتِهِ النُّبُوَّةَ وَالْكِتَابَ﴾؟","answer":"أضاف العطف إلى نعمة الذرية نعمة أعظم باقية، فجعل الله في نسله حمل الرسالة والكتاب لهداية الأمم.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص298، تحت عنوان «دلالة العطف في ﴿وجعلنا﴾»","url":""}]},{"id":"s29-85","number":85,"surah":29,"verses":[27],"references":[{"surah":29,"verses":[27]}],"verseLabel":"العنكبوت: 27","question":"ما علة التنصيص على ﴿النُّبُوَّةَ وَالْكِتَابَ﴾؟","answer":"نُص عليهما لأنهما أعظم وجوه التكريم وأدومها أثرًا: اصطفاء رسل من ذريته وإنزال الكتب عليهم، فبقيت رسالته في العالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص300، تحت عنوان «علة التنصيص على ذكر ﴿النبوة والكتاب﴾»","url":""}]},{"id":"s29-32","number":32,"surah":29,"verses":[29],"references":[{"surah":29,"verses":[29]}],"verseLabel":"العنكبوت: 29","question":"ما بلاغة التعبير بقطع السبيل في خطاب قوم لوط؟","answer":"جمع التعبير تعطيلهم السبيل الطبيعي لبقاء النوع وصدهم المارة بأفعالهم، فصور فسادهم في الفطرة وأمن المجتمع معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص320، تحت عنوان «بلاغة التعبير بقطع السبيل»","url":""}]},{"id":"s29-86","number":86,"surah":29,"verses":[29],"references":[{"surah":29,"verses":[29]}],"verseLabel":"العنكبوت: 29","question":"ما بلاغة الكناية في قوله: ﴿وَتَقْطَعُونَ السَّبِيلَ﴾؟","answer":"كنى بقطع السبيل عن الفعل الشاذ الذي يقطع طريق النسل، مع احتمال قطع طريق المسافرين؛ فجمع اللفظ قبح الفاحشة والإفساد العام بأدب العبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص321، تحت عنوان «بلاغة الكناية في ﴿السبيل﴾»","url":""}]},{"id":"s29-87","number":87,"surah":29,"verses":[29],"references":[{"surah":29,"verses":[29]}],"verseLabel":"العنكبوت: 29","question":"ما دلالة العطف في قوله: ﴿وَتَأْتُونَ فِي نَادِيكُمُ الْمُنْكَرَ﴾؟","answer":"عطف منكر النادي على الفاحشة وقطع السبيل ليبين تعدد جرائمهم وامتدادها من السلوك الخاص إلى المجال العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص322، تحت عنوان «دلالة العطف في ﴿وتأتون﴾»","url":""}]},{"id":"s29-88","number":88,"surah":29,"verses":[29],"references":[{"surah":29,"verses":[29]}],"verseLabel":"العنكبوت: 29","question":"ما بلاغة التعبير بقوله: ﴿فِي نَادِيكُمُ﴾؟","answer":"اختير النادي لأنه مجلس اجتماعهم؛ فدل على أنهم يجاهرون بالمنكر جماعة حتى صار مؤسسيًا معلنًا لا فعلًا خفيًا عارضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص323، تحت عنوان «بلاغة التعبير بقوله ﴿ناديكم﴾»","url":""}]},{"id":"s29-33","number":33,"surah":29,"verses":[31],"references":[{"surah":29,"verses":[31]}],"verseLabel":"العنكبوت: 31","question":"ما نكتة ذكر لوط مع العلم بنجاته؟","answer":"ذكره إبراهيم شفقةً عليه وخوفًا على المؤمنين في القرية، واستنقاذًا لهم من الهلاك، فأظهر اهتمامه بهم مع ثقته بوعد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص346–347، تحت عنوان «نكتة ذكر لوط مع العلم بنجاته»","url":""}]},{"id":"s29-89","number":89,"surah":29,"verses":[31],"references":[{"surah":29,"verses":[31]}],"verseLabel":"العنكبوت: 31","question":"ما بلاغة العدول عن الخصوص إلى العموم في جواب الملائكة: ﴿نَحْنُ أَعْلَمُ بِمَنْ فِيهَا﴾؟","answer":"سأل إبراهيم عن لوط خاصة، فعمموا الجواب ليطمئن إلى علمهم بجميع المستحقين للنجاة والهلاك، فكانت البشارة أوسع وأحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص348، تحت عنوان «بلاغة العدول عن الخصوص إلى العموم»","url":""}]},{"id":"s29-90","number":90,"surah":29,"verses":[31],"references":[{"surah":29,"verses":[31]}],"verseLabel":"العنكبوت: 31","question":"ما دلالة الاستثناء في قوله: ﴿إِلَّا امْرَأَتَهُ﴾؟","answer":"استثنيت امرأة لوط من أهله الناجين لأنها شاركت قومها الكفر والخيانة، فدل على أن القرابة لا تنفع مع فساد العقيدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص350، تحت عنوان «دلالة الاستثناء ﴿إلا امرأته﴾»","url":""}]},{"id":"s29-34","number":34,"surah":29,"verses":[33],"references":[{"surah":29,"verses":[33]}],"verseLabel":"العنكبوت: 33","question":"ما بلاغة استعمال مفردة ﴿سِيءَ﴾ في وصف لوط؟","answer":"أوجز الفعل شدة ما أصابه من غم بسبب خوفه على ضيوفه وعجزه عن حمايتهم؛ فأسند السوء إليه لتجسيد أثر الخبر في نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص359، تحت عنوان «بلاغة استعمال مفردة ﴿سيء﴾»","url":""}]},{"id":"s29-91","number":91,"surah":29,"verses":[33],"references":[{"surah":29,"verses":[33]}],"verseLabel":"العنكبوت: 33","question":"ما بلاغة الكناية في قوله: ﴿وَضَاقَ بِهِمْ ذَرْعًا﴾؟","answer":"كنى بضيق الذراع عن بلوغ العجز والحيرة؛ فصور لوطًا كمن قصرت قدرته عن حماية ضيوفه ولم يجد وسيلة للخلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص361، تحت عنوان «بلاغة الكناية في ﴿وضاق بهم ذرعا﴾»","url":""}]},{"id":"s29-35","number":35,"surah":29,"verses":[35],"references":[{"surah":29,"verses":[35]}],"verseLabel":"العنكبوت: 35","question":"ما نكتة استعمال مفردة ﴿تَرَكْنَا﴾ في قوله: ﴿وَلَقَدْ تَرَكْنَا مِنْهَا آيَةً بَيِّنَةً﴾؟","answer":"دل الترك على زوال القرية وبقاء أثر واحد مقصود للعبرة؛ فانفصلت الآية الباقية عن كل ما اندثر من مظاهرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص375، تحت عنوان «نكتة استعمال مفردة الترك مادة وصيغة»","url":""}]},{"id":"s29-92","number":92,"surah":29,"verses":[35],"references":[{"surah":29,"verses":[35]}],"verseLabel":"العنكبوت: 35","question":"إلى ماذا يعود الضمير في قوله: ﴿مِنْهَا﴾؟","answer":"يحتمل عوده إلى القرية نفسها أو إلى قصتها وحادثتها؛ وفي الوجهين بقيت علامة ظاهرة تشهد بما وقع لأهلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص376، تحت عنوان «تعيين مرجع الضمير»","url":""}]},{"id":"s29-93","number":93,"surah":29,"verses":[35],"references":[{"surah":29,"verses":[35]}],"verseLabel":"العنكبوت: 35","question":"ما نكتة جعل موطن العبرة ﴿لِقَوْمٍ يَعْقِلُونَ﴾؟","answer":"خص العقلاء لأن العقل السليم يحجز عن الفاحشة ويتجاوز مشاهدة الأثر إلى فهم سببه وعاقبته، فتتحول الآية عندهم إلى موعظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص377، تحت عنوان «نكتة جعل موطن العبرة لقوم يعقلون»","url":""}]},{"id":"s29-36","number":36,"surah":29,"verses":[38],"references":[{"surah":29,"verses":[38]}],"verseLabel":"العنكبوت: 38","question":"ما بلاغة استعمال مفردة ﴿تَبَيَّنَ﴾؟","answer":"دل الفعل على انكشاف مصارعهم وظهورها بعد نظر، وصيغته تصور وضوح الدليل وتدرج إدراكه حتى يستقر يقينًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص393، تحت عنوان «بلاغة استعمال مفردة ﴿تبين﴾»","url":""}]},{"id":"s29-94","number":94,"surah":29,"verses":[38],"references":[{"surah":29,"verses":[38]}],"verseLabel":"العنكبوت: 38","question":"لماذا اختيرت مفردة ﴿الْمَسَاكِنِ﴾ دون البيوت؟","answer":"المساكن أوسع من البيوت؛ تشمل مواضع إقامتهم وآثار عمرانهم، وتستحضر سكونها بعد أهلها حتى أصبحت خرائب شاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص394، تحت عنوان «بلاغة اختيار مفردة المساكن دون البيوت»","url":""}]},{"id":"s29-37","number":37,"surah":29,"verses":[38],"references":[{"surah":29,"verses":[38]}],"verseLabel":"العنكبوت: 38","question":"ما معنى الواو ودلالتها في قوله: ﴿وَعَادًا وَثَمُودَ﴾؟","answer":"عطفت الواو قصة عاد وثمود على ما سبق من الأمم، فضمتهما إلى سلسلة الشواهد على سنة إهلاك المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص391، تحت عنوان «معنى الواو ودلالتها»","url":""}]},{"id":"s29-95","number":95,"surah":29,"verses":[38],"references":[{"surah":29,"verses":[38]}],"verseLabel":"العنكبوت: 38","question":"ما نوع الواو وفائدتها في قوله: ﴿وَقَدْ تَبَيَّنَ لَكُمْ مِنْ مَسَاكِنِهِمْ﴾؟","answer":"هي واو حالية تجعل وضوح آثار مساكنهم حالًا مصاحبة للخبر عنهم؛ فالحجة قائمة مشاهدة وقت تذكير المخاطبين بعاقبتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص392، تحت عنوان «نوع الواو وفائدتها»","url":""}]},{"id":"s29-38","number":38,"surah":29,"verses":[40],"references":[{"surah":29,"verses":[40]}],"verseLabel":"العنكبوت: 40","question":"ما معنى الفاء في قوله: ﴿فَكُلًّا أَخَذْنَا بِذَنْبِهِ﴾؟","answer":"فرعت الفاء العقوبة على تكذيب الأمم المتقدم، وجاء الإجمال بكل بعد تعدد القصص ليجمعهم في قاعدة الجزاء بالذنب.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص413، تحت عنوان «معنى (الفاء)»","url":""}]},{"id":"s29-96","number":96,"surah":29,"verses":[40],"references":[{"surah":29,"verses":[40]}],"verseLabel":"العنكبوت: 40","question":"ما معنى الباء في قوله: ﴿بِذَنْبِهِ﴾؟","answer":"الباء سببية؛ فدلّت على أن ذنب كل أمة هو سبب أخذها، وأن العقوبة لم تقع ظلمًا بل بما كسبوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص415، تحت عنوان «معنى الباء»","url":""}]},{"id":"s29-97","number":97,"surah":29,"verses":[40],"references":[{"surah":29,"verses":[40]}],"verseLabel":"العنكبوت: 40","question":"ما معنى الفاء في قوله: ﴿فَمِنْهُمْ مَنْ أَرْسَلْنَا عَلَيْهِ حَاصِبًا﴾؟","answer":"جاءت الفاء تفصيلًا لطرائق الأخذ بعد إجمالها، فوزعت كل أمة على نوع العقوبة المناسب لذنبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص416، تحت عنوان «معنى الفاء»","url":""}]},{"id":"s29-39","number":39,"surah":29,"verses":[41],"references":[{"surah":29,"verses":[41]}],"verseLabel":"العنكبوت: 41","question":"ما سرّ تشبيه اتخاذ الأولياء ببيت العنكبوت؟","answer":"شبه حال من يتخذ من دون الله أولياء بحال العنكبوت التي تتخذ بيتًا تطلب به الحماية، مع أنه أوهن البيوت؛ فالمثل لفساد الاعتماد وعجز المتخذ، لا لمجرد رقة خيوط البيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص427–428، تحت عنوان «إجراء النظم على التشبيه التمثيلي المركب»","url":""}]},{"id":"s29-40","number":40,"surah":29,"verses":[41],"references":[{"surah":29,"verses":[41]}],"verseLabel":"العنكبوت: 41","question":"ما بلاغة الكناية في جملة الفاصلة: ﴿لَوْ كَانُوا يَعْلَمُونَ﴾؟","answer":"كنى الشرط عن نفي علمهم النافع؛ فلو أدركوا حقيقة ضعف ما اتخذوه أولياء لما تعلقوا بهم، لكنهم يتبعون الظن.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص430، تحت عنوان «بلاغة الكناية في جملة الفاصلة»","url":""}]},{"id":"s29-41","number":41,"surah":29,"verses":[43],"references":[{"surah":29,"verses":[43]}],"verseLabel":"العنكبوت: 43","question":"ما بلاغة الاستثناء المفرغ في قوله: ﴿وَمَا يَعْقِلُهَا إِلَّا الْعَالِمُونَ﴾؟","answer":"قصر الاستثناء فهم الأمثال حق الفهم على أهل العلم، فعظم شأنها وبين أن إدراك حكمتها يحتاج علمًا راسخًا لا سماعًا عابرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص447، تحت عنوان «بلاغة الاستثناء المفرغ»","url":""}]},{"id":"s29-98","number":98,"surah":29,"verses":[43],"references":[{"surah":29,"verses":[43]}],"verseLabel":"العنكبوت: 43","question":"ما نكتة قصر عقل الأمثال على أولي العلم دون العكس؟","answer":"كل عالم بحق يعقل حجج الأمثال، وليس كل عاقل قد بلغ رتبة العلم الذي يكشف حكمتها؛ فخص العلماء لفضل رسوخهم ويقينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص448، تحت عنوان «نكتة قصر العقل على أولي العلم دون العكس»","url":""}]},{"id":"s29-42","number":42,"surah":29,"verses":[45],"references":[{"surah":29,"verses":[45]}],"verseLabel":"العنكبوت: 45","question":"ما نكتة إسناد الفعل إلى الصلاة في قوله: ﴿إِنَّ الصَّلَاةَ تَنْهَى﴾؟","answer":"أسند النهي إلى الصلاة لأنها سبب ينشئ في صاحبها الوازع عن الفحشاء والمنكر، فصورت كناصح حي يردعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص459، تحت عنوان «نكتة إسناد الفعل إلى ﴿الصلاة﴾»","url":""}]},{"id":"s29-99","number":99,"surah":29,"verses":[45],"references":[{"surah":29,"verses":[45]}],"verseLabel":"العنكبوت: 45","question":"لماذا عُبر بـ﴿تَنْهَى﴾ دون تمنع؟","answer":"النهي إرشاد وزجر لا قهر؛ فالصلاة تبعث على ترك المنكر، لكنها لا تسلب المصلي اختياره، ولذلك قد يعصي من لا يحققها.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص459–460، تحت عنوان «نكتة التعبير بالفعل ﴿تنهى﴾ دون (تمنع)»","url":""}]},{"id":"s29-43","number":43,"surah":29,"verses":[45],"references":[{"surah":29,"verses":[45]}],"verseLabel":"العنكبوت: 45","question":"ما المجاز المرسل في قوله: ﴿وَلَذِكْرُ اللَّهِ﴾؟","answer":"أطلق ذكر الله وهو جزء الصلاة وأعظم مقاصدها وأريدت الصلاة كلها؛ فعلاقة الجزء بالكل أبرزت روح العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص461، تحت عنوان «المجاز المرسل في ﴿ولذكر الله﴾»","url":""}]},{"id":"s29-100","number":100,"surah":29,"verses":[45],"references":[{"surah":29,"verses":[45]}],"verseLabel":"العنكبوت: 45","question":"ما دلالة أفعل التفضيل في قوله: ﴿وَلَذِكْرُ اللَّهِ أَكْبَرُ﴾؟","answer":"قرر أن ذكر الله أعظم من سائر أعمال الصلاة وأبلغ أثرًا في النهي، أو أن الصلاة الجامعة له أكبر الطاعات؛ فالتفضيل يعظم جوهر العبادة وثمرتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص462، تحت عنوان «دلالة أفعل التفضيل»","url":""}]},{"id":"s29-44","number":44,"surah":29,"verses":[46],"references":[{"surah":29,"verses":[46]}],"verseLabel":"العنكبوت: 46","question":"ما دلالة الاستثناء في قوله: ﴿إِلَّا بِالَّتِي هِيَ أَحْسَنُ﴾؟","answer":"حصر مجادلتهم في الطريقة الأحسن: اللين والحجة الواضحة والدعاء إلى الله، فاستبعد الغلظة والمراء الذي لا يهدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص473، تحت عنوان «دلالة الاستثناء في ﴿إلا بالتي هي أحسن﴾»","url":""}]},{"id":"s29-101","number":101,"surah":29,"verses":[46],"references":[{"surah":29,"verses":[46]}],"verseLabel":"العنكبوت: 46","question":"ما غرض التعبير بالاسم الموصول وصلته في قوله: ﴿إِلَّا الَّذِينَ ظَلَمُوا مِنْهُمْ﴾؟","answer":"عرّف المستثنين بظلمهم ليجعل الوصف علة اختلاف معاملتهم، وشمل كل من ظهر منه الاعتداء والعناد من أهل الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص477–478، تحت عنوان «غرض التعبير بالاسم الموصول وصلته»","url":""}]},{"id":"s29-45","number":45,"surah":29,"verses":[46],"references":[{"surah":29,"verses":[46]}],"verseLabel":"العنكبوت: 46","question":"ما معنى الواو في قوله: ﴿وَإِلَهُنَا وَإِلَهُكُمْ وَاحِدٌ﴾؟","answer":"عطفت وحدة الإله على وحدة مصدر الوحي، فجعل التوحيد الجامع أساس الاتفاق الصحيح مع أهل الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص481، تحت عنوان «معنى الواو في قوله ﴿وإلهنا﴾»","url":""}]},{"id":"s29-46","number":46,"surah":29,"verses":[48],"references":[{"surah":29,"verses":[48]}],"verseLabel":"العنكبوت: 48","question":"ما دلالة قوله: ﴿وَمَا كُنْتَ تَتْلُو مِنْ قَبْلِهِ مِنْ كِتَابٍ﴾؟","answer":"نفى عنه القراءة والكتابة قبل القرآن ليبطل ريبة المبطلين؛ فإتيانه بهذا الكتاب مع أميته دليل أنه وحي لا صناعة بشرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص505–506، تحت عنوان «دلالة قوله ﴿وما كنت تتلو﴾»","url":""}]},{"id":"s29-102","number":102,"surah":29,"verses":[48],"references":[{"surah":29,"verses":[48]}],"verseLabel":"العنكبوت: 48","question":"ما فائدة التقييد باليمين في قوله: ﴿وَلَا تَخُطُّهُ بِيَمِينِكَ﴾؟","answer":"ذكر اليمين لأنها آلة الكتابة المعتادة ولزيادة تصوير نفي مباشرته للخط، فصار الدليل على أميته أوقع في النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص509، تحت عنوان «فائدة التقييد باليمين في قوله ﴿بيمينك﴾»","url":""}]},{"id":"s29-47","number":47,"surah":29,"verses":[49],"references":[{"surah":29,"verses":[49]}],"verseLabel":"العنكبوت: 49","question":"ما نكتة وصف الآيات بأنها ﴿بَيِّنَاتٌ﴾؟","answer":"وصفها بالبينات لوضوحها وكمال دلالتها وسهولة حفظها وفهمها، فهي ليست مما يعجز العقل عن إدراك حجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص521، تحت عنوان «نكتة وصف الآيات بأنها ﴿بينات﴾»","url":""}]},{"id":"s29-103","number":103,"surah":29,"verses":[49],"references":[{"surah":29,"verses":[49]}],"verseLabel":"العنكبوت: 49","question":"ما معنى الظرفية والاستعارة في قوله: ﴿فِي صُدُورِ﴾؟","answer":"استعيرت الصدور أوعية للقرآن لثبوت حفظه في القلوب؛ فدل على رسوخ الآيات في العلماء وصيانتها من التحريف.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص522، تحت عنوان «معنى الظرفية والاستعارة ﴿في صدور﴾»","url":""}]},{"id":"s29-104","number":104,"surah":29,"verses":[49],"references":[{"surah":29,"verses":[49]}],"verseLabel":"العنكبوت: 49","question":"من المراد بـ﴿الَّذِينَ أُوتُوا الْعِلْمَ﴾؟","answer":"هم أهل العلم المؤمنون الذين عرفوا دلالة القرآن وصدق الرسول، فحملوه في صدورهم وتوارثوه، ويشمل الوصف علماء الأمة الراسخين.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص523–524، تحت عنوان «المراد بـ﴿الذين أوتوا العلم﴾»","url":""}]},{"id":"s29-48","number":48,"surah":29,"verses":[50],"references":[{"surah":29,"verses":[50]}],"verseLabel":"العنكبوت: 50","question":"ما نكتة العدول عن ذكر القرآن إلى ﴿آيَاتٌ﴾ في طلبهم؟","answer":"عدلوا إلى آيات مبهمة ليطالبوا بخوارق يختارونها متجاهلين القرآن القائم بينهم، مع أن جنس الآيات كلها من عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص533، تحت عنوان «نكتة العدول عن ذكر القرآن إلى ﴿آيات﴾»","url":""}]},{"id":"s29-105","number":105,"surah":29,"verses":[50],"references":[{"surah":29,"verses":[50]}],"verseLabel":"العنكبوت: 50","question":"ما غرض بناء الفعل ﴿يُتْلَى﴾ للمفعول؟","answer":"ركز البناء للمفعول على القرآن المتلو وإعجازه وانتشار تلاوته، لا على قارئ بعينه؛ فهو آية متجددة في كل زمان ومكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص546–547، تحت عنوان «غرض بناء الفعل ﴿يتلى﴾ للمفعول»","url":""}]},{"id":"s29-49","number":49,"surah":29,"verses":[51],"references":[{"surah":29,"verses":[51]}],"verseLabel":"العنكبوت: 51","question":"ما نوع الاستفهام وغرضه في قوله: ﴿أَوَلَمْ يَكْفِهِمْ﴾؟","answer":"الاستفهام إنكاري توبيخي؛ ينكر طلبهم آيات أخرى مع كفاية القرآن الدائم معجزةً وبرهانًا، ويدعوهم إلى تدبره.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص542، تحت عنوان «نوع الاستفهام وغرضه»","url":""}]},{"id":"s29-50","number":50,"surah":29,"verses":[52],"references":[{"surah":29,"verses":[52]}],"verseLabel":"العنكبوت: 52","question":"ما نكتة تنكير ﴿شَهِيدًا﴾ في قوله: ﴿كَفَى بِاللَّهِ بَيْنِي وَبَيْنَكُمْ شَهِيدًا﴾؟","answer":"عظّم التنكير شأن شهادة الله المطلقة؛ فهو الشهيد الذي أحاط علمه بأقوالهم وأعمالهم، وكفت شهادته وحدها في حسم الخصومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص558، تحت عنوان «نكتة تنكير ﴿شهيدا﴾»","url":""}]},{"id":"s29-106","number":106,"surah":29,"verses":[52],"references":[{"surah":29,"verses":[52]}],"verseLabel":"العنكبوت: 52","question":"ما دلالة التعبير بالمضارع في قوله: ﴿يَعْلَمُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"أفاد المضارع دوام علم الله وتجدد تعلقه بكل موجود وحادث؛ فعلمه محيط بالماضي والحاضر والمستقبل، وهو قيوم على الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص559، تحت عنوان «دلالة التعبير بالمضارع ﴿يعلم﴾»","url":""}]},{"id":"s29-51","number":51,"surah":29,"verses":[54],"references":[{"surah":29,"verses":[54]}],"verseLabel":"العنكبوت: 54","question":"ما دلالة التعبير باسم الفاعل في قوله: ﴿وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌ بِالْكَافِرِينَ﴾؟","answer":"صوّر اسم الفاعل إحاطة جهنم ثابتة متحققة، كأنها واقعة الآن، مع الدلالة على استمرارها في المستقبل؛ فوعيدها محكم لا مهرب منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص579، تحت عنوان «دلالة التعبير بصيغة اسم الفاعل»","url":""}]},{"id":"s29-107","number":107,"surah":29,"verses":[54],"references":[{"surah":29,"verses":[54]}],"verseLabel":"العنكبوت: 54","question":"ما غرض تتابع المؤكدات في قوله: ﴿وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌ بِالْكَافِرِينَ﴾؟","answer":"جاءت الجملة اسمية مؤكدة بإن واللام لتقابل إنكارهم وتزيل الشك في إحاطة جهنم بهم، وتقرر الوعيد تقريرًا قاطعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص579، تحت عنوان «غرض تتابع المؤكدات»","url":""}]},{"id":"s29-52","number":52,"surah":29,"verses":[56],"references":[{"surah":29,"verses":[56]}],"verseLabel":"العنكبوت: 56","question":"ما غرض الإخبار بسعة الأرض في قوله: ﴿إِنَّ أَرْضِي وَاسِعَةٌ﴾؟","answer":"حض المؤمنين على الهجرة، وقطع عذر من يمنعه موطنه من العبادة؛ فأرض الله واسعة، ورزقه ممتد، ولا يصح البقاء حيث يتعذر إقامة الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص594، تحت عنوان «غرض الإخبار بسعة الأرض»","url":""}]},{"id":"s29-108","number":108,"surah":29,"verses":[56],"references":[{"surah":29,"verses":[56]}],"verseLabel":"العنكبوت: 56","question":"ما نكتة تقديم المفعول به في قوله: ﴿فَإِيَّايَ فَاعْبُدُونِ﴾؟","answer":"أفاد تقديم ﴿إياي﴾ اختصاص الله بالعبادة وقصرها عليه، وأكّد وجوب توحيده والمبادرة إلى عبادته ولو استلزم ذلك مفارقة الوطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص595، تحت عنوان «نكتة تقديم المفعول به على الفعل»","url":""}]},{"id":"s29-53","number":53,"surah":29,"verses":[57],"references":[{"surah":29,"verses":[57]}],"verseLabel":"العنكبوت: 57","question":"ما علة فصل قوله: ﴿كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ﴾ عما قبله؟","answer":"فصلت لأنها استئناف يعلل الحث على الهجرة: لا ينبغي الخوف من موت مفارق الوطن، فالموت واقع بكل نفس وفي كل أرض، ثم الرجوع إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص596، تحت عنوان «علة فصل الآية عما سبقها»","url":""}]},{"id":"s29-109","number":109,"surah":29,"verses":[57],"references":[{"surah":29,"verses":[57]}],"verseLabel":"العنكبوت: 57","question":"ما فائدة لازم الخبر في قوله: ﴿كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ﴾؟","answer":"لأن المخاطبين يعلمون حتمية الموت، لم يقصد مجرد الإعلام، بل لازم الخبر: التذكير والوعظ والحث على المبادرة بالطاعة والهجرة قبل حلول الأجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص598، تحت عنوان «فائدة لازم الخبر»","url":""}]},{"id":"s29-54","number":54,"surah":29,"verses":[58],"references":[{"surah":29,"verses":[58]}],"verseLabel":"العنكبوت: 58","question":"ما نكتة استعمال ﴿لَنُبَوِّئَنَّهُمْ﴾ مادةً وصيغةً؟","answer":"اختيرت مادة التبوئة لإفادة إنزال المؤمنين منازل حسنة مستقرة تليق بهم، وجاءت الصيغة مؤكدة بالقسم واللام والنون لضمان الجزاء وتثبيت قلوبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص605، تحت عنوان «نكتة استعمال ﴿لنبوئنهم﴾ مادة وصيغة»","url":""}]},{"id":"s29-55","number":55,"surah":29,"verses":[60],"references":[{"surah":29,"verses":[60]}],"verseLabel":"العنكبوت: 60","question":"ما نوع الواو ودلالتها في قوله: ﴿وَكَأَيِّنْ مِنْ دَابَّةٍ لَا تَحْمِلُ رِزْقَهَا﴾؟","answer":"الواو عاطفة على جملة تذوق الموت، فضمّت ضمان الرزق إلى تهوين الموت لتزيل عذري الخوف على النفس والخوف من الفقر عند الهجرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص615، تحت عنوان «نوع الواو ودلالتها»","url":""}]},{"id":"s29-110","number":110,"surah":29,"verses":[60],"references":[{"surah":29,"verses":[60]}],"verseLabel":"العنكبوت: 60","question":"ما بلاغة الجمع بين الحقيقة والمجاز في قوله: ﴿لَا تَحْمِلُ رِزْقَهَا﴾؟","answer":"احتمل اللفظ الحقيقة في دواب لا تدخر قوتها ولا تطيق حمله، والمجاز في عجزها عن تحصيله وتأمينه؛ فجمع صور الافتقار إلى رزق الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص617، تحت عنوان «بلاغة الجمع بين دلالة الحقيقة والمجاز»","url":""}]},{"id":"s29-111","number":111,"surah":29,"verses":[60],"references":[{"surah":29,"verses":[60]}],"verseLabel":"العنكبوت: 60","question":"ما بلاغة العطف في قوله: ﴿اللَّهُ يَرْزُقُهَا وَإِيَّاكُمْ﴾؟","answer":"عطف رزق المخاطبين على رزق الدواب ليستدل بالمشاهد على الغائب: من تكفل بضعيف الحيوان قادر على رزق المهاجر، وفي تقديم الدواب زيادة طمأنة وإيضاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص619، تحت عنوان «بلاغة العطف وبراعته في تقرير المعاني القياسية»","url":""}]},{"id":"s29-56","number":56,"surah":29,"verses":[61],"references":[{"surah":29,"verses":[61]}],"verseLabel":"العنكبوت: 61","question":"ما غرض الاستفهام في قوله: ﴿وَلَئِنْ سَأَلْتَهُمْ مَنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ﴾؟","answer":"هو سؤال تقريري يلزم المشركين بما يقرون به؛ فإذا اعترفوا بأن الله خالق السماوات والأرض بطل صرف العبادة إلى غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص626، تحت عنوان «غرض الاستفهام وبلاغته»","url":""}]},{"id":"s29-57","number":57,"surah":29,"verses":[62],"references":[{"surah":29,"verses":[62]}],"verseLabel":"العنكبوت: 62","question":"ما نكتة إضافة ﴿عِبَادِهِ﴾ إلى ضمير الجلالة؟","answer":"أشعرت الإضافة بأن الخلق جميعًا عبيد الله في ملكه وكفالته، وأن رزقهم قائم على علمه وحكمته؛ يوسعه لمن يشاء ويقدره بلا جبر ولا إهمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص636، تحت عنوان «نكتة إضافة لفظ العباد إلى الضمير»","url":""}]},{"id":"s29-112","number":112,"surah":29,"verses":[62],"references":[{"surah":29,"verses":[62]}],"verseLabel":"العنكبوت: 62","question":"ما نكتة التذييل بصفة العلم مادةً وصيغةً في قوله: ﴿إِنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ﴾؟","answer":"ذيّل الحكم بإحاطة العلم ليقرر أن بسط الرزق وقبضه يجريان وفق علم كامل بمصالح العباد؛ وأكدت إن والصيغة المشبهة ثبوت هذا العلم ودوامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص639، تحت عنوان «نكتة التذييل بصفة العلم مادة وصيغة»","url":""}]},{"id":"s29-58","number":58,"surah":29,"verses":[63],"references":[{"surah":29,"verses":[63]}],"verseLabel":"العنكبوت: 63","question":"ما غرض الأمر في قوله: ﴿قُلِ الْحَمْدُ لِلَّهِ﴾ ودلالته؟","answer":"أمر بإظهار حمد الله على إلزام المشركين بالحجة واعترافهم بأنه الخالق والمنزل للماء، ودل على أن هذا الإقرار يوجب إفراده بالحمد والعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص648، تحت عنوان «غرض الأمر ودلالته»","url":""}]},{"id":"s29-113","number":113,"surah":29,"verses":[63],"references":[{"surah":29,"verses":[63]}],"verseLabel":"العنكبوت: 63","question":"ما نوع الإضراب وفائدته في قوله: ﴿بَلْ أَكْثَرُهُمْ لَا يَعْقِلُونَ﴾؟","answer":"هو إضراب انتقالي من حمد الله على الحجة إلى ذم أكثرهم؛ لأنهم لم يتبعوا نتائج براهينهم، فنفى عنهم العقل النافع لا مجرد المعرفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص650، تحت عنوان «نوع الإضراب وفائدته»","url":""}]},{"id":"s29-114","number":114,"surah":29,"verses":[63],"references":[{"surah":29,"verses":[63]}],"verseLabel":"العنكبوت: 63","question":"ما دلالة التعبير بالمضارع في قوله: ﴿لَا يَعْقِلُونَ﴾؟","answer":"دل المضارع على تجدد تعطيلهم للعقل واستمراره كلما ظهرت الحجة؛ فهم يكررون اتباع الهوى والإصرار على الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص651، تحت عنوان «دلالة التعبير بمفردة ﴿يعقلون﴾ مادة وصيغة»","url":""}]},{"id":"s29-59","number":59,"surah":29,"verses":[64],"references":[{"surah":29,"verses":[64]}],"verseLabel":"العنكبوت: 64","question":"ما نوع التشبيه وبلاغته في قوله: ﴿وَمَا هَذِهِ الْحَيَاةُ الدُّنْيَا إِلَّا لَهْوٌ وَلَعِبٌ﴾؟","answer":"هو تشبيه بليغ قصر الحياة الدنيا على اللهو واللعب، فصوّر سرعة زوالها وقلة جدواها لمن جعلها غايته، وحذّر من الاغترار بزينتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص661، تحت عنوان «نوع التشبيه وبلاغته في الآية»","url":""}]},{"id":"s29-115","number":115,"surah":29,"verses":[64],"references":[{"surah":29,"verses":[64]}],"verseLabel":"العنكبوت: 64","question":"ما سر التعبير بـ﴿الْحَيَوَانُ﴾ دون الحياة في وصف الدار الآخرة؟","answer":"الحيوان صيغة مبالغة من الحياة تفيد الحركة والامتلاء والدوام؛ فدل على أن الآخرة هي الحياة الحقيقية الكاملة التي لا موت فيها ولا سكون.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص664–665، تحت عنوان «سر التعبير بـ﴿الحيوان﴾ دون الحياة»","url":""}]},{"id":"s29-60","number":60,"surah":29,"verses":[65],"references":[{"surah":29,"verses":[65]}],"verseLabel":"العنكبوت: 65","question":"ما دلالة الحال في قوله: ﴿مُخْلِصِينَ لَهُ الدِّينَ﴾؟","answer":"كشفت الحال أنهم عند إحاطة الخطر يجردون الدعاء لله وحده، فيظهر توحيد الفطرة الذي كانوا يغطونه بالشرك في الرخاء، فتقوم عليهم الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص677–678، تحت عنوان «دلالة التعبير بالحال ﴿مخلصين له الدين﴾»","url":""}]},{"id":"s29-61","number":61,"surah":29,"verses":[67],"references":[{"surah":29,"verses":[67]}],"verseLabel":"العنكبوت: 67","question":"ما بلاغة المقابلة في قوله: ﴿حَرَمًا آمِنًا وَيُتَخَطَّفُ النَّاسُ مِنْ حَوْلِهِمْ﴾؟","answer":"قابل أمن الحرم بخوف ما حوله، فأبرز نعمة الله على أهل مكة وقبح جحودهم؛ أمنهم الله في موضع تضطرب فيه الطرق والقبائل.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص707، تحت عنوان «بلاغة المقابلة»","url":""}]},{"id":"s29-116","number":116,"surah":29,"verses":[67],"references":[{"surah":29,"verses":[67]}],"verseLabel":"العنكبوت: 67","question":"ما بلاغة الاستفهام وغرضه في قوله: ﴿أَفَبِالْبَاطِلِ يُؤْمِنُونَ﴾؟","answer":"الاستفهام إنكاري تعجيبي يوبخهم على قلب الحقائق: يؤمنون بالأصنام الباطلة ويقابلون نعمة الله بالكفر، والفاء فرعت الإنكار على اعترافهم بالنعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص708، تحت عنوان «بلاغة الاستفهام وغرضه في ﴿أفبالباطل﴾»","url":""}]},{"id":"s29-62","number":62,"surah":29,"verses":[69],"references":[{"surah":29,"verses":[69]}],"verseLabel":"العنكبوت: 69","question":"ما نكتة حذف مفعول ﴿جَاهَدُوا﴾ في قوله: ﴿وَالَّذِينَ جَاهَدُوا فِينَا﴾؟","answer":"عمم حذف المفعول كل وجوه المجاهدة في مرضاة الله: جهاد النفس والشيطان والأعداء وتحمل المشاق؛ فصار الوعد شاملًا بحسب حال المجاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص733، تحت عنوان «نكتة حذف المفعول»","url":""}]},{"id":"s29-117","number":117,"surah":29,"verses":[69],"references":[{"surah":29,"verses":[69]}],"verseLabel":"العنكبوت: 69","question":"ما دلالة التعبير بالمضارع في قوله: ﴿لَنَهْدِيَنَّهُمْ﴾؟","answer":"أفاد المضارع تجدد هداية المجاهدين واستمرارها كلما واصلوا المجاهدة، مع توكيد الوعد بالقسم واللام والنون.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص734، تحت عنوان «دلالة التعبير بالفعل المضارع»","url":""}]},{"id":"s29-118","number":118,"surah":29,"verses":[69],"references":[{"surah":29,"verses":[69]}],"verseLabel":"العنكبوت: 69","question":"ما فائدة الجمع والإضافة في قوله: ﴿سُبُلَنَا﴾؟","answer":"دل الجمع على كثرة طرق الخير الموصلة إلى رضا الله، وأفادت إضافتها إليه تشريفها وضمان سلامتها واستقامتها؛ فكلها تنتهي إلى غاية واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص734–735، تحت عنوان «فائدة الجمع والإضافة»","url":""}]},{"id":"s29-119","number":119,"surah":29,"verses":[69],"references":[{"surah":29,"verses":[69]}],"verseLabel":"العنكبوت: 69","question":"ما علة التعبير بالمعية في قوله: ﴿لَمَعَ الْمُحْسِنِينَ﴾؟","answer":"عبّرت المعية عن عناية الله الخاصة بالمحسنين: نصرًا وتسديدًا وحفظًا وثباتًا، وهي معية تقتضي القرب والرعاية لا مجرد العلم العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص737، تحت عنوان «علة التعبير بالمعية في ﴿لمع﴾»","url":""}]},{"id":"s30-1","number":1,"surah":30,"verses":[1],"references":[{"surah":30,"verses":[1]}],"verseLabel":"الروم: 1","question":"ما نكتة فصل قوله: ﴿غُلِبَتِ الرُّومُ﴾ عما قبله؟","answer":"فصلت عن ﴿الم﴾ لانقطاع الصلة الإعرابية وكمال الاستقلال، وجاء الخبر بعد افتتاح يوقظ السمع ليجيب عما أثاره المطلع من ترقب: ما النبأ العظيم الآتي؟","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص755–756، تحت عنوان «نكتة فصل الآية عما قبلها»","url":""}]},{"id":"s30-2","number":2,"surah":30,"verses":[2],"references":[{"surah":30,"verses":[2]}],"verseLabel":"الروم: 2","question":"ما سرّ إسناد ﴿غُلِبَتِ﴾ إلى ﴿الرُّومُ﴾ بالتأنيث؟","answer":"رُوعي في اسم الروم معنى الجماعة، فجاز تأنيث الفعل؛ واختيار التأنيث هنا يصورهم جماعةً أصابها الضعف والهوان المؤديان إلى الهزيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص757، تحت عنوان «علة التأنيث في قوله ﴿غلبت الروم﴾»","url":""}]},{"id":"s30-3","number":3,"surah":30,"verses":[2],"references":[{"surah":30,"verses":[2]}],"verseLabel":"الروم: 2","question":"ما سرّ تعريف ﴿الرُّومُ﴾؟","answer":"للعهد؛ الأمة المعروفة للدولة الرومية التي تابع العرب خبر حربها.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص757، تحت عنوان «معنى التعريف في قوله ﴿غلبت الروم﴾»","url":""}]},{"id":"s30-4","number":4,"surah":30,"verses":[3],"references":[{"surah":30,"verses":[3]}],"verseLabel":"الروم: 3","question":"ما دلالة اسم التفضيل في قوله: ﴿فِي أَدْنَى الْأَرْضِ﴾؟","answer":"دل ﴿أدنى﴾ على أن موضع الغلبة كان أقرب بلاد الروم إلى أرض العرب، وهي ناحية الشام؛ فزاد تحديد المكان الخبر الغيبي دقة ووضوحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص758، تحت عنوان «دلالة التعبير باسم التفضيل»","url":""}]},{"id":"s30-58","number":58,"surah":30,"verses":[3],"references":[{"surah":30,"verses":[3]}],"verseLabel":"الروم: 3","question":"ما معنى التعريف في قوله: ﴿أَدْنَى الْأَرْضِ﴾؟","answer":"عرّف الأرض للعهد؛ أي الأرض المعهودة التي جرت فيها المعركة، أو أقرب أرض الروم إلى المخاطبين، فعيّن موضع الهزيمة بدل إبقائه مبهمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص759، تحت عنوان «معنى التعريف في قوله ﴿أدنى الأرض﴾»","url":""}]},{"id":"s30-5","number":5,"surah":30,"verses":[3,4],"references":[{"surah":30,"verses":[3,4]}],"verseLabel":"الروم: 3-4","question":"ما وجه الإعجاز الغيبي في الإخبار بانتصار الروم بعد هزيمتهم؟","answer":"أخبر القرآن والروم في ضعف شديد أنهم سيغلبون الفرس خلال بضع سنين، فوقع النصر في المدة المحددة؛ فكان خبرًا غيبيًا لا يستند إلى الظاهر وشاهدًا على صدق الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص757–758، تحت عنوان «الإعجاز الغيبي في الآية»","url":""}]},{"id":"s30-59","number":59,"surah":30,"verses":[3,4],"references":[{"surah":30,"verses":[3,4]}],"verseLabel":"الروم: 3-4","question":"ما علة فصل قوله: ﴿فِي بِضْعِ سِنِينَ﴾ عما قبله؟","answer":"جعل الظرف في ابتداء آية مع تعلقه بـ﴿سيغلبون﴾ لإبرازه مقصدًا مستقلًا وتحديد زمن النصر تحديدًا ظاهرًا؛ فصار كل من وقوع الغلبة وموعدها وجهًا قائمًا من وجوه الإعجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص766، تحت عنوان «علة فصل الآية عما قبلها»","url":""}]},{"id":"s30-6","number":6,"surah":30,"verses":[4],"references":[{"surah":30,"verses":[4]}],"verseLabel":"الروم: 4","question":"ما نكتة تقديم المسند في قوله: ﴿لِلَّهِ الْأَمْرُ﴾؟","answer":"قدّم الجار والمجرور لقصر الأمر كله على الله قصرًا حقيقيًا؛ فهو وحده مالك التدبير، وما يقع من غلبة أو هزيمة إنما يجري بمشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص768، تحت عنوان «نكتة تقديم المسند على المسند إليه»","url":""}]},{"id":"s30-60","number":60,"surah":30,"verses":[4],"references":[{"surah":30,"verses":[4]}],"verseLabel":"الروم: 4","question":"ما نكتة حذف المضاف إليه في قوله: ﴿مِنْ قَبْلُ وَمِنْ بَعْدُ﴾؟","answer":"حذف المضاف إليه ليعم كل قبل وكل بعد؛ فالأمر لله في جميع الأزمنة والأحوال، قبل غلبة الروم وبعدها وقبل كل حادث وبعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص769، تحت عنوان «نكتة حذف المضاف إليه»","url":""}]},{"id":"s30-7","number":7,"surah":30,"verses":[4,5],"references":[{"surah":30,"verses":[4,5]}],"verseLabel":"الروم: 4-5","question":"ما دلالة متعلق الفرح والتنوين في قوله: ﴿وَيَوْمَئِذٍ يَفْرَحُ الْمُؤْمِنُونَ﴾؟","answer":"تعلق الفرح باليوم الذي يتحقق فيه نصر الروم، والتنوين في ﴿يومئذ﴾ عوض عن جملة؛ فربط فرح المؤمنين بانتصار أهل الكتاب وما يصاحبه من ظهور صدق القرآن ونصر الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص770، تحت عنوان «دلالة المتعلق، ونوع التنوين فيه»","url":""}]},{"id":"s30-61","number":61,"surah":30,"verses":[4,5],"references":[{"surah":30,"verses":[4,5]}],"verseLabel":"الروم: 4-5","question":"ما نكتة التعبير بالمضارع في قوله: ﴿يَفْرَحُ الْمُؤْمِنُونَ﴾؟","answer":"عبّر بالمضارع لأن الفرح سيقع في المستقبل، ولتصويره متجددًا عند تحقق النصر، حتى يستحضر السامع المشهد الموعود كأنه حاضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص770–771، تحت عنوان «نكتة التعبير بالفعل المضارع»","url":""}]},{"id":"s30-8","number":8,"surah":30,"verses":[6],"references":[{"surah":30,"verses":[6]}],"verseLabel":"الروم: 6","question":"ما دلالة نصب المصدر ﴿وَعْدَ اللَّهِ﴾؟","answer":"نصب المصدر نائبًا عن فعله، فكأن المعنى: وعد الله ذلك وعدًا؛ فقرر الخبر وأكده بعد البشارة بالنصر والفرح.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص779، تحت عنوان «دلالة نصب المصدر ﴿وعد﴾»","url":""}]},{"id":"s30-62","number":62,"surah":30,"verses":[6],"references":[{"surah":30,"verses":[6]}],"verseLabel":"الروم: 6","question":"ما سر العدول عن الضمير إلى اسم الجلالة في قوله: ﴿لَا يُخْلِفُ اللَّهُ وَعْدَهُ﴾؟","answer":"أظهر اسم الجلالة بدل الضمير لتعظيم الله واستحضار هيبته، وتقوية اليقين بأن من صدر عنه الوعد كامل القدرة لا يخلفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص780، تحت عنوان «سر العدول عن الإضمار إلى الإظهار»","url":""}]},{"id":"s30-63","number":63,"surah":30,"verses":[6],"references":[{"surah":30,"verses":[6]}],"verseLabel":"الروم: 6","question":"ما لطيفة إظهار لفظ ﴿الْوَعْدَ﴾ في قوله: ﴿لَا يُخْلِفُ اللَّهُ وَعْدَهُ﴾؟","answer":"كرر لفظ الوعد ولم يكتف بضميره لتفخيم شأنه وتثبيته في النفس، والتنبيه إلى أن وعد الله بنصر الحق سنة ماضية لا تتخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص780، تحت عنوان «لطيفة إظهار الوعد في ﴿لا يخلف الله وعده﴾»","url":""}]},{"id":"s30-9","number":9,"surah":30,"verses":[7],"references":[{"surah":30,"verses":[7]}],"verseLabel":"الروم: 7","question":"ما غرض تنكير ﴿ظَاهِرًا﴾ في قوله: ﴿يَعْلَمُونَ ظَاهِرًا مِنَ الْحَيَاةِ الدُّنْيَا﴾؟","answer":"أفاد التنكير التحقير والتقليل؛ فما يعلمونه جزء ظاهر يسير من الدنيا، لا يبلغ حقائقها ولا ما وراءها، فهو علم قاصر يشبه الجهل.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص787، تحت عنوان «غرض التنكير في قوله ﴿ظاهرا﴾»","url":""}]},{"id":"s30-64","number":64,"surah":30,"verses":[7],"references":[{"surah":30,"verses":[7]}],"verseLabel":"الروم: 7","question":"ما دلالة لفظ ﴿ظَاهِرًا﴾ على قصور علم الناس؟","answer":"قصر علمهم على القشور المحسوسة من شؤون الدنيا ومنافعها، دون بواطنها وعواقبها ودلالتها على الآخرة؛ فمهارتهم في الظاهر لا تمنحهم العلم النافع الكامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص787–788، تحت عنوان «دلالة لفظ ﴿ظاهرا﴾ على قصور علم الناس»","url":""}]},{"id":"s30-10","number":10,"surah":30,"verses":[7],"references":[{"surah":30,"verses":[7]}],"verseLabel":"الروم: 7","question":"ما نكتة إعادة الضمير ﴿هُمْ﴾ في قوله: ﴿وَهُمْ عَنِ الْآخِرَةِ هُمْ غَافِلُونَ﴾؟","answer":"أكد تكرير الضمير الحكم عليهم بالغفلة وثبته، وأفاد قصرًا ادعائيًا يبالغ في اختصاصهم بها؛ فبرز التناقض بين خبرتهم بظاهر الدنيا وغفلتهم عن الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص791–792، تحت عنوان «نكتة إعادة الضمير ﴿هم﴾ في السياق»","url":""}]},{"id":"s30-11","number":11,"surah":30,"verses":[8],"references":[{"surah":30,"verses":[8]}],"verseLabel":"الروم: 8","question":"ما معنى حرف الجر ﴿فِي﴾ في قوله: ﴿أَوَلَمْ يَتَفَكَّرُوا فِي أَنْفُسِهِمْ﴾؟","answer":"يحتمل أن تكون ﴿في﴾ ظرفية حقيقية؛ أي يجعلوا التفكر مستقرًا عميقًا في نفوسهم، أو تتعلق بالتفكر في خلق أنفسهم وما أودع فيها من دلائل القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص13–14، تحت عنوان «معنى حرف الجر في قوله ﴿في أنفسهم﴾»","url":""}]},{"id":"s30-65","number":65,"surah":30,"verses":[8],"references":[{"surah":30,"verses":[8]}],"verseLabel":"الروم: 8","question":"ما نكتة تقييد التفكر بقوله: ﴿فِي أَنْفُسِهِمْ﴾؟","answer":"وجّههم إلى أقرب موضع للدليل وأيسره تناولًا؛ ففي خلقهم وأحوالهم ما يخرجهم من الغفلة ويذكرهم بأن خالقهم قادر على البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص14–15، تحت عنوان «نكتة ذكر القيد ﴿في أنفسهم﴾»","url":""}]},{"id":"s30-66","number":66,"surah":30,"verses":[8],"references":[{"surah":30,"verses":[8]}],"verseLabel":"الروم: 8","question":"ما علة عطف ﴿وَأَجَلٍ مُسَمًّى﴾ على خلق السماوات والأرض بالحق؟","answer":"أضاف العطف انتهاء العالم إلى بيان إحكام خلقه، فكما لم يخلق باطلًا لم يخلق خالدًا؛ بل حد له أجلًا معلومًا ينتهي عنده تمهيدًا للبعث والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص17، تحت عنوان «علة عطف قوله ﴿وأجل مسمى﴾ على ما قبله»","url":""}]},{"id":"s30-12","number":12,"surah":30,"verses":[9],"references":[{"surah":30,"verses":[9]}],"verseLabel":"الروم: 9","question":"ما غرض الاستفهام في قوله: ﴿أَوَلَمْ يَسِيرُوا فِي الْأَرْضِ﴾؟","answer":"الاستفهام توبيخي تقريري؛ ينعى عليهم ترك الاعتبار بمصارع الأمم مع قيام آثارها أمامهم، ويحضهم على السير الذي يوقظ العقل ويكسر الغفلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص24، تحت عنوان «غرض الاستفهام في قوله ﴿أولم يسيروا﴾»","url":""}]},{"id":"s30-67","number":67,"surah":30,"verses":[9],"references":[{"surah":30,"verses":[9]}],"verseLabel":"الروم: 9","question":"ما دلالة النظر في قوله: ﴿فَيَنْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِنْ قَبْلِهِمْ﴾؟","answer":"ليس المراد مجرد رؤية الآثار، بل نظر تأمل واعتبار يصل من مشاهدة الخراب إلى فهم سببه وعاقبة التكذيب، فيدعو إلى التوحيد والإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص28، تحت عنوان «دلالة النظر المراد في جملة ﴿فينظروا﴾»","url":""}]},{"id":"s30-68","number":68,"surah":30,"verses":[9],"references":[{"surah":30,"verses":[9]}],"verseLabel":"الروم: 9","question":"ما نكتة فصل قوله: ﴿كَانُوا أَشَدَّ مِنْهُمْ قُوَّةً﴾ عما قبله؟","answer":"جاءت جملة مستأنفة تجيب عن سؤال تثيره رؤية الآثار: من كانوا؟ فبينت أنهم أقوى وأعمر للأرض، ومع ذلك لم تمنعهم قوتهم من الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص30، تحت عنوان «نكتة فصل ﴿كانوا أشد﴾ عما قبلها»","url":""}]},{"id":"s30-13","number":13,"surah":30,"verses":[10],"references":[{"surah":30,"verses":[10]}],"verseLabel":"الروم: 10","question":"ما توجيه ﴿السُّوأَى﴾ ودلالتها في قوله: ﴿ثُمَّ كَانَ عَاقِبَةَ الَّذِينَ أَسَاءُوا السُّوأَى﴾؟","answer":"السوأى مؤنث الأسوأ، وهي أقبح العاقبة وأشدها؛ أي النار والجزاء السيئ، فجاء اللفظ على غاية المقابلة بين إساءتهم وسوء مصيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص43–44، تحت عنوان «توجيه ﴿السوأى﴾ ودلالتها في السياق»","url":""}]},{"id":"s30-69","number":69,"surah":30,"verses":[10],"references":[{"surah":30,"verses":[10]}],"verseLabel":"الروم: 10","question":"ما بلاغة الجناس الاشتقاقي بين ﴿أَسَاءُوا﴾ و﴿السُّوأَى﴾؟","answer":"ربط الاشتقاق العمل بجزائه ربطًا صوتيًا ومعنويًا؛ فمن اقترف السوء لقي السوأى، فبرزت مناسبة العقوبة للجناية وإحكام الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص44، تحت عنوان «بديع الجناس الاشتقاقي، في السياق المحكم»","url":""}]},{"id":"s30-14","number":14,"surah":30,"verses":[11],"references":[{"surah":30,"verses":[11]}],"verseLabel":"الروم: 11","question":"ما بلاغة الإدماج في قوله: ﴿ثُمَّ يُعِيدُهُ﴾؟","answer":"أدمج إثبات البعث في خبر بدء الخلق؛ فمن سلّم بأن الله أنشأ الخلق أول مرة لزمه أن إعادة الخلق أهون، فاجتمع التقرير والبرهان في عبارة موجزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص52، تحت عنوان «بلاغة الإدماج في قوله ﴿ثم يعيده﴾»","url":""}]},{"id":"s30-15","number":15,"surah":30,"verses":[12],"references":[{"surah":30,"verses":[12]}],"verseLabel":"الروم: 12","question":"ما علة التعبير بالمضارع في قوله: ﴿يُبْلِسُ الْمُجْرِمُونَ﴾؟","answer":"استحضر المضارع حال المجرمين عند قيام الساعة، ودل على تجدد إبلاسهم واستمراره؛ فيلازمهم اليأس والحيرة وانقطاع الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص58–59، تحت عنوان «علة التعبير بالفعل المضارع ﴿يبلس﴾»","url":""}]},{"id":"s30-70","number":70,"surah":30,"verses":[12],"references":[{"surah":30,"verses":[12]}],"verseLabel":"الروم: 12","question":"ما الفرق بين الإبلاس واليأس والقنوط؟","answer":"الإبلاس حزن ويأس مع سكوت وانقطاع حجة، واليأس انقطاع الرجاء، والقنوط يأس شديد يظهر أثره في الذلة والانكسار؛ فالإبلاس أنسب بمشهد المجرمين العاجزين عن الجواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص65، تحت عنوان «الإبلاس واليأس والقنوط»","url":""}]},{"id":"s30-16","number":16,"surah":30,"verses":[14],"references":[{"surah":30,"verses":[14]}],"verseLabel":"الروم: 14","question":"ما دلالة التعبير بـ﴿يَصَّدَّعُونَ﴾ مادةً وصيغةً؟","answer":"أفادت المادة التفرق والانشقاق، وصورت الصيغة تشدد الانقسام يوم القيامة؛ فيتفرق الناس فريقًا في الجنة وفريقًا في السعير تفرقًا ظاهرًا حاسمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص428، تحت عنوان «دلالة التعبير بـ﴿يصدعون﴾؛ مادة وصيغة»","url":""}]},{"id":"s30-17","number":17,"surah":30,"verses":[15],"references":[{"surah":30,"verses":[15]}],"verseLabel":"الروم: 15","question":"ما غرض تنكير ﴿رَوْضَةٍ﴾ في قوله: ﴿فَهُمْ فِي رَوْضَةٍ يُحْبَرُونَ﴾؟","answer":"فخم التنكير شأن الروضة وأبهم سعتها وحسنها بما يجاوز الوصف، فهي جنة غنية بالخضرة والأنهار والنضارة لا روضة معهودة محدودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص74، تحت عنوان «غرض تنكير ﴿روضة﴾»","url":""}]},{"id":"s30-71","number":71,"surah":30,"verses":[15],"references":[{"surah":30,"verses":[15]}],"verseLabel":"الروم: 15","question":"ما سر التعبير بالمضارع في قوله: ﴿يُحْبَرُونَ﴾؟","answer":"دل المضارع على تجدد سرور أهل الجنة واستمراره؛ فهم يتقلبون في ألوان من النعيم لا تنقطع ولا تفنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص74، تحت عنوان «سر التعبير بالمضارع ﴿يحبرون﴾»","url":""}]},{"id":"s30-18","number":18,"surah":30,"verses":[17,18],"references":[{"surah":30,"verses":[17,18]}],"verseLabel":"الروم: 17-18","question":"ما دلالة التعبير بالتسبيح عن الصلاة في قوله: ﴿فَسُبْحَانَ اللَّهِ حِينَ تُمْسُونَ وَحِينَ تُصْبِحُونَ﴾؟","answer":"أطلق التسبيح وأريدت الصلاة لأنها أعظم ما يظهر فيه تنزيه الله وذكره، فدل الجزء الأبرز على العبادة كلها مع بقاء معنى التنزيه العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص93–94، تحت عنوان «دلالة التعبير بالتسبيح عن الصلاة»","url":""}]},{"id":"s30-72","number":72,"surah":30,"verses":[17,18],"references":[{"surah":30,"verses":[17,18]}],"verseLabel":"الروم: 17-18","question":"ما دلالة تقييد التسبيح بأوقات المساء والصباح؟","answer":"ألزم التنزيه والعبادة في طرفي اليوم لتجدد نعم الله وآياته فيهما، ولأن الإنسان أحوج ما يكون إلى افتتاح يومه واختتامه بذكر ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص94، تحت عنوان «دلالة تقييد التسبيح بالأوقات»","url":""}]},{"id":"s30-73","number":73,"surah":30,"verses":[17,18],"references":[{"surah":30,"verses":[17,18]}],"verseLabel":"الروم: 17-18","question":"ما دلالة تفصيل الأزمان في آيتي التسبيح والحمد؟","answer":"وزع الذكر والصلاة على أجزاء اليوم والليلة حتى يشغل اللسان والقلب بالطاعة في الأوقات المتعاقبة، وجمع التسبيح والحمد بما يلائم كل مقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص103، تحت عنوان «دلالة تفصيل الأزمان في الآيتين»","url":""}]},{"id":"s30-19","number":19,"surah":30,"verses":[17],"references":[{"surah":30,"verses":[17]}],"verseLabel":"الروم: 17","question":"ما سرّ تقديم المساء على الصباح في ﴿حِينَ تُمْسُونَ وَحِينَ تُصْبِحُونَ﴾؟","answer":"ذكر المبحث أن المساء متقدم على الصباح في الاعتبار الشرعي واللغوي لابتداء اليوم من الليل، فجاء ترتيب الذكر موافقًا لذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص95، تحت عنوان «دلالة تقديم الإمساء على الإصباح»","url":""}]},{"id":"s30-20","number":20,"surah":30,"verses":[19],"references":[{"surah":30,"verses":[19]}],"verseLabel":"الروم: 19","question":"ما بلاغة الاحتراس في قوله: ﴿وَيُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ﴾؟","answer":"جاء الشق الثاني احتراسًا من توهم اختصاص القدرة بإخراج الحي من الميت؛ فجمع الضدين وأثبت تمام القدرة على التحويل في الاتجاهين.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص111، تحت عنوان «بلاغة الاحتراس في الآية»","url":""}]},{"id":"s30-74","number":74,"surah":30,"verses":[19],"references":[{"surah":30,"verses":[19]}],"verseLabel":"الروم: 19","question":"ما دلالة الواو في قوله: ﴿وَكَذَلِكَ تُخْرَجُونَ﴾؟","answer":"عطفت إخراج الناس للبعث على آيتي إخراج الحي وإحياء الأرض، فصار المشاهد دليلًا على الغائب، وانتقل السياق من البرهان إلى النتيجة الموجهة للمخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص114، تحت عنوان «دلالة (الواو) في ﴿وكذلك تخرجون﴾»","url":""}]},{"id":"s30-21","number":21,"surah":30,"verses":[20],"references":[{"surah":30,"verses":[20]}],"verseLabel":"الروم: 20","question":"ما نكتة الجمع بين التراخي والمفاجأة في قوله: ﴿ثُمَّ إِذَا أَنْتُمْ بَشَرٌ تَنْتَشِرُونَ﴾؟","answer":"جمعت ﴿ثم﴾ تراخي أطوار الخلق الطويلة، و﴿إذا﴾ مفاجأة ظهور البشر وانتشارهم؛ فصوّرت الانتقال العجيب من أصل ترابي ساكن إلى حياة وحركة واسعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص125–126، تحت عنوان «نكتة الجمع بين التراخي والمفاجأة»","url":""}]},{"id":"s30-75","number":75,"surah":30,"verses":[20],"references":[{"surah":30,"verses":[20]}],"verseLabel":"الروم: 20","question":"ما نكتة تنكير لفظ ﴿بَشَرٌ﴾؟","answer":"عظّم التنكير كثرة هذا الجنس المنتشر وتنوع أفراده، وأبرز الانتقال من خلق واحد إلى بشر كثير يملؤون الأرض حركة وعمرانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص126، تحت عنوان «نكتة تنكير لفظ ﴿بشر﴾»","url":""}]},{"id":"s30-23","number":23,"surah":30,"verses":[21],"references":[{"surah":30,"verses":[21]}],"verseLabel":"الروم: 21","question":"ما دلالة المضارع في قوله: ﴿لِتَسْكُنُوا إِلَيْهَا﴾؟","answer":"دل المضارع على تجدد السكون النفسي واستمراره بين الزوجين، فهو طمأنينة متجددة تواكب تغيرات الحياة ولا تقتصر على لحظة الزواج.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص137، تحت عنوان «دلالة المضارعة في الفعل ﴿لتسكنوا﴾»","url":""}]},{"id":"s30-76","number":76,"surah":30,"verses":[21],"references":[{"surah":30,"verses":[21]}],"verseLabel":"الروم: 21","question":"ما سر التعبير بالمودة دون الحب في آية الأزواج؟","answer":"المودة حب يظهر في العمل والمعاملة، فهي أليق بعلاقة زوجية تحتاج تعاطفًا وبذلًا وتضحيات، بخلاف الحب الذي قد يبقى شعورًا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص139، تحت عنوان «سر التعبير بالمودة دون الحب»","url":""}]},{"id":"s30-77","number":77,"surah":30,"verses":[21],"references":[{"surah":30,"verses":[21]}],"verseLabel":"الروم: 21","question":"ما نكتة تقديم المودة على الرحمة؟","answer":"قدمت المودة لأنها أصل الاتصال بين الزوجين في أول الحياة، ثم تأتي الرحمة لتصون الأسرة عند الضعف أو فتور دواعي المودة؛ فوافق الترتيب مسار العلاقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص140، تحت عنوان «نكتة تقديم (المودة) على (الرحمة)»","url":""}]},{"id":"s30-24","number":24,"surah":30,"verses":[22],"references":[{"surah":30,"verses":[22]}],"verseLabel":"الروم: 22","question":"ما بلاغة المجاز في قوله: ﴿وَاخْتِلَافُ أَلْسِنَتِكُمْ﴾؟","answer":"أطلق الألسنة وأريدت اللغات من باب تسمية الشيء بآلته؛ فجمع اللفظ اختلاف اللغات واللهجات والأصوات في صورة حسية موجزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص152–153، تحت عنوان «بلاغة المجاز في ﴿واختلاف ألسنتكم﴾»","url":""}]},{"id":"s30-78","number":78,"surah":30,"verses":[22],"references":[{"surah":30,"verses":[22]}],"verseLabel":"الروم: 22","question":"ما دلالة العطف في قوله: ﴿وَأَلْوَانِكُمْ﴾؟","answer":"عطف اختلاف الألوان على اختلاف الألسنة ليجمع علامتي التمييز الظاهرتين بين البشر؛ تنوع النطق وتنوع الهيئة، مع وحدة الأصل والخالق.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص153، تحت عنوان «دلالة العطف في ﴿وألوانكم﴾»","url":""}]},{"id":"s30-79","number":79,"surah":30,"verses":[22],"references":[{"surah":30,"verses":[22]}],"verseLabel":"الروم: 22","question":"ما دلالة التعبير بالألوان وجمعها؟","answer":"جمع الألوان لاستحضار كثرة درجات البشرة والهيئات واختلافها الذي يميز الأفراد والأجناس، فيظهر بديع القدرة مع استحالة حصر التنوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص154، تحت عنوان «دلالة التعبير بـ(الألوان) وجمعها»","url":""}]},{"id":"s30-25","number":25,"surah":30,"verses":[22],"references":[{"surah":30,"verses":[22]}],"verseLabel":"الروم: 22","question":"من المراد بـ﴿الْعَالِمِينَ﴾ في قوله ﴿إِنَّ فِي ذَلِكَ لَآيَاتٍ لِلْعَالِمِينَ﴾؟","answer":"في قراءة كسر اللام «العالِمين» المراد أهل العلم، لأنهم ينتفعون بهذه الدلائل ويتدبرونها. وذكر المبحث قراءة فتح اللام «العالَمين» بمعنى الخلق عامة؛ فالآيات معروضة للجميع، وأهل العلم أتم انتفاعًا بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص157–158، تحت عنوان «أثر توجيه القراءات في ﴿للعالمين﴾»","url":""}]},{"id":"s30-26","number":26,"surah":30,"verses":[23],"references":[{"surah":30,"verses":[23]}],"verseLabel":"الروم: 23","question":"ما دلالة عطف النهار على الليل في آية المنام وابتغاء الرزق؟","answer":"جمع العطف الزمنين لأن النوم قد يقع في الليل والنهار، كما يمتد طلب الرزق فيهما، وإن كان الأشهر أن الليل للسكون والنهار للمعاش.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص167، تحت عنوان «دلالة عطف (النهار) على (الليل)»","url":""}]},{"id":"s30-27","number":27,"surah":30,"verses":[24],"references":[{"surah":30,"verses":[24]}],"verseLabel":"الروم: 24","question":"ما بلاغة الجمع بين الخوف والطمع عند رؤية البرق؟","answer":"جمع الضدين لأن البرق يوقع الخوف من الصواعق أو خيبة المطر، ويبعث الطمع في الغيث والخير؛ فصوّر تردد النفس بين رهبة ورجاء من آية واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص183، تحت عنوان «بلاغة الجمع في قوله ﴿خوفا وطمعا﴾»","url":""}]},{"id":"s30-80","number":80,"surah":30,"verses":[24],"references":[{"surah":30,"verses":[24]}],"verseLabel":"الروم: 24","question":"ما دلالة حذف متعلق ﴿خَوْفًا وَطَمَعًا﴾؟","answer":"عمم الحذف أسباب الخوف والطمع وصورهما، فلا يحصرهما في معنى واحد؛ فيشمل خوف الضرر وفوات الغيث، وطمع المسافر والمقيم في منافع المطر.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص184، تحت عنوان «دلالة حذف متعلق ﴿خوفا وطمعا﴾»","url":""}]},{"id":"s30-28","number":28,"surah":30,"verses":[25],"references":[{"surah":30,"verses":[25]}],"verseLabel":"الروم: 25","question":"ما دلالة المضارع في قوله: ﴿تَقُومَ السَّمَاءُ وَالْأَرْضُ﴾؟","answer":"دل المضارع على دوام قيام السماء والأرض واستمراره بلا اضطراب، واستحضر تجدد حفظهما بأمر الله لحظة بعد لحظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص200، تحت عنوان «دلالة القيام في المضارع ﴿تقوم﴾»","url":""}]},{"id":"s30-81","number":81,"surah":30,"verses":[25],"references":[{"surah":30,"verses":[25]}],"verseLabel":"الروم: 25","question":"ما دلالة إضافة الأمر إلى ضمير الجلالة في قوله: ﴿بِأَمْرِهِ﴾؟","answer":"أفادت الإضافة أن قيام الكون صادر عن أمر الله التكويني النافذ، وأظهرت كمال نفوذه وقدرته واستغناء تدبيره عن الأسباب والأعوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص202، تحت عنوان «دلالة التعبير بالمضاف إلى الضمير (أمره)»","url":""}]},{"id":"s30-82","number":82,"surah":30,"verses":[25],"references":[{"surah":30,"verses":[25]}],"verseLabel":"الروم: 25","question":"ما دلالة إفراد ﴿دَعْوَةً﴾ وتنكيرها في قوله: ﴿إِذَا دَعَاكُمْ دَعْوَةً مِنَ الْأَرْضِ﴾؟","answer":"أفاد الإفراد والتنكير أن البعث يتم بدعوة واحدة سريعة لا تحتاج تكرارًا ولا انتظارًا؛ فيستجيب لها الخلق جميعًا ويخرجون فورًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص205، تحت عنوان «دلالة إفراد ﴿دعوة﴾، ولطيفة تنكيرها»","url":""}]},{"id":"s30-29","number":29,"surah":30,"verses":[26],"references":[{"surah":30,"verses":[26]}],"verseLabel":"الروم: 26","question":"لماذا قال الله: ﴿كُلٌّ لَهُ قَانِتُونَ﴾ مع أن بعض الناس يعصونه؟","answer":"شمل لفظ ﴿كل﴾ الخلق جميعًا لأن أحدًا لا يخرج عن ملك الله وتدبيره، حتى من خالف أمره الشرعي؛ فالمعصية لا تمنع خضوعه لأمر الله الكوني في حياته وموته ورزقه ومصيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص217، تحت عنوان «دلالة التعبير بلفظ العموم ﴿كل﴾»","url":""}]},{"id":"s30-83","number":83,"surah":30,"verses":[26],"references":[{"surah":30,"verses":[26]}],"verseLabel":"الروم: 26","question":"ما الذي تضيفه كلمة ﴿قَانِتُونَ﴾ إلى مشهد خضوع الخلق لله؟","answer":"تصور الكلمة خضوعًا ثابتًا ممتدًا؛ فالموجودات كلها منقادة لسلطان الله وأمره التكويني، طوعًا أو كرهًا، ولا تملك الإفلات من قضائه وتدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص218–219، تحت عنوان «سر اختيار مادة (القنوت)»","url":""}]},{"id":"s30-30","number":30,"surah":30,"verses":[27],"references":[{"surah":30,"verses":[27]}],"verseLabel":"الروم: 27","question":"كيف تكون الإعادة أهون على الله مع أن البدء والإعادة سواء في قدرته؟","answer":"جاء التعبير على ما يدركه البشر: إعادة الشيء بعد إنشائه أيسر في مألوفهم من ابتدائه، فاحتج عليهم بما يقرون به لإبطال استبعاد البعث. أما قدرة الله فلا يلحقها عسر، والبدء والإعادة عنده سواء.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص226–227، تحت عنوان «دلالة التعبير بلفظ ﴿أهون﴾، بوزن (أفعل)»","url":""}]},{"id":"s30-31","number":31,"surah":30,"verses":[28],"references":[{"surah":30,"verses":[28]}],"verseLabel":"الروم: 28","question":"كيف أبطل القرآن الشرك بمثال الشركاء من المماليك؟","answer":"ألزم المشركين بما يعرفونه من أنفسهم: فهم لا يرضون أن يشاركهم مماليكهم في أموالهم مشاركة مساواة يخافون معها تصرفهم، مع أن الجميع بشر؛ فكيف يجعلون مخلوقات الله شركاء له في ملكه وعبادته؟","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص240، تحت عنوان «بلاغة التمثيل للمشرك بملك اليمين»","url":""}]},{"id":"s30-32","number":32,"surah":30,"verses":[30],"references":[{"surah":30,"verses":[30]}],"verseLabel":"الروم: 30","question":"ما الصورة التي يرسمها قوله: ﴿فَأَقِمْ وَجْهَكَ لِلدِّينِ﴾؟","answer":"يصوّر التوجه إلى الدين كإنسان يقيم وجهه نحو مقصده فلا يلتفت عنه؛ فيدل على الإقبال الكامل والثبات على الحق والاهتمام به دون تردد أو انصراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص282–283، تحت عنوان «بلاغة الاستعارة التمثيلية في ﴿فأقم وجهك﴾»","url":""}]},{"id":"s30-33","number":33,"surah":30,"verses":[30],"references":[{"surah":30,"verses":[30]}],"verseLabel":"الروم: 30","question":"لماذا نُسبت الفطرة إلى الله في قوله: ﴿فِطْرَتَ اللَّهِ﴾؟","answer":"لتعظيم شأنها وبيان أنها الصنعة التي أنشأ الله الناس عليها؛ فهي استعداد أصيل لقبول التوحيد، ومخالفتها انحراف عما يلائم الخِلقة التي أودعها الله في الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص286، تحت عنوان «دلالة الإضافة في ﴿فطرت الله﴾»","url":""}]},{"id":"s30-84","number":84,"surah":30,"verses":[30],"references":[{"surah":30,"verses":[30]}],"verseLabel":"الروم: 30","question":"هل الإسلام طارئ على الإنسان أم هو الأصل في فطرته؟","answer":"الإسلام هو الأصل السابق المودع في خلق الناس، أما الكفر فانحراف حادث عن ذلك الأصل؛ ولذلك يوافق التوحيد سلامة الفطرة، ويحتاج الخروج عنه إلى مؤثر يغيرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص287، تحت عنوان «دلالة الحق في الفعل ﴿فطر﴾»","url":""}]},{"id":"s30-34","number":34,"surah":30,"verses":[31,32],"references":[{"surah":30,"verses":[31,32]}],"verseLabel":"الروم: 31-32","question":"لماذا وصفهم القرآن بأنهم ﴿شِيَعًا﴾؟","answer":"لأنهم صاروا جماعات يتحالف أفراد كل واحدة منها على مذهب يتبعونه ويناصرونه، من غير ميزان ثابت للحق؛ فالكلمة تكشف التعصب والتناصر على الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص316، تحت عنوان «دلالة التعبير بلفظ ﴿شيعا﴾»","url":""}]},{"id":"s30-35","number":35,"surah":30,"verses":[33],"references":[{"surah":30,"verses":[33]}],"verseLabel":"الروم: 33","question":"لماذا عبّر القرآن عن الرحمة بشيء يُذاق في قوله: ﴿إِذَا أَذَاقَهُمْ مِنْهُ رَحْمَةً﴾؟","answer":"لأن الذوق أسرع الحواس اتصالًا بالمطعوم وأقلها إصابة للجسم، فصوّر سرعة شعورهم بأول الرحمة وقلة ما نالوه منها؛ ثم فضح أنهم يبادرون إلى الشرك منذ أول نعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص334، تحت عنوان «بلاغة الاستعارة في مفردة الإذاقة»","url":""}]},{"id":"s30-36","number":36,"surah":30,"verses":[36],"references":[{"surah":30,"verses":[36]}],"verseLabel":"الروم: 36","question":"لماذا ذكر فرح الناس بالرحمة ولم يذكر شكرهم عليها؟","answer":"لأن المقصود كشف حال أكثرهم: يبطرون بالنعمة ويظهرون السرور بها، لكنهم لا يؤدون حق المنعم بالشكر؛ فإذا زالت عنهم الرحمة انتقلوا سريعًا إلى اليأس والقنوط.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص358، تحت عنوان «تخصيص الفرح بالذكر دون الشكر»","url":""}]},{"id":"s30-85","number":85,"surah":30,"verses":[36],"references":[{"surah":30,"verses":[36]}],"verseLabel":"الروم: 36","question":"ماذا يوقظ في النفس قوله: ﴿بِمَا قَدَّمَتْ أَيْدِيهِمْ﴾ عند نزول السيئة؟","answer":"ينبه إلى أن كثيرًا من المصائب ثمرة لأعمال الناس، فيوقظ محاسبة النفس والرجوع عن الذنب بدل القنوط؛ كما يحذر من الاغترار بالأسباب وإغفال حكمة الله وعدله.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص361، تحت عنوان «بلاغة فن الإدماج»","url":""}]},{"id":"s30-37","number":37,"surah":30,"verses":[37],"references":[{"surah":30,"verses":[37]}],"verseLabel":"الروم: 37","question":"كيف يكون تفاوت الرزق آية يراها الناس في حياتهم؟","answer":"لأن الناس قد تتشابه أعمالهم وأسبابهم ثم تتفاوت أرزاقهم، وقد يتغير رزق الشخص مع بقاء سعيه؛ فينكشف أن الأسباب لا تستقل بالعطاء، وأن وراءها تقديرًا يدعو إلى التأمل والتوكل مع الأخذ بالأسباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص362، تحت عنوان «غرض الاستفهام وبلاغته»","url":""}]},{"id":"s30-38","number":38,"surah":30,"verses":[38],"references":[{"surah":30,"verses":[38]}],"verseLabel":"الروم: 38","question":"لماذا جاء الأمر بإعطاء ذي القربى والمسكين بعد الحديث عن بسط الرزق وتقديره؟","answer":"لأن من علم أن الله هو الذي يبسط الرزق ويقدره لم يمنعه خوف النقص من أداء الحقوق؛ فالعطاء شكر عند السعة، ولا يسقط أصل الإحسان عند الضيق بقدر الاستطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص376–377، تحت عنوان «نوع الفاء ودلالتها»","url":""}]},{"id":"s30-86","number":86,"surah":30,"verses":[38],"references":[{"surah":30,"verses":[38]}],"verseLabel":"الروم: 38","question":"لماذا سمّى القرآن ما يُعطى لذي القربى والمسكين ﴿حَقَّهُ﴾؟","answer":"ليخرج العطاء من صورة التفضل المحض إلى معنى الحق الثابت؛ فصلة القريب وإغاثة المحتاج ليستا منة يتعالى بها المعطي، بل واجب أو حق مؤكد يؤديه صاحبه بطيب نفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص378، تحت عنوان «بلاغة التنوع في دلالات مفردة الحق»","url":""}]},{"id":"s30-39","number":39,"surah":30,"verses":[39],"references":[{"surah":30,"verses":[39]}],"verseLabel":"الروم: 39","question":"هل الربا في قوله: ﴿وَمَا آتَيْتُمْ مِنْ رِبًا﴾ مقصور على الربا المحرم؟","answer":"يحتمل اللفظ الربا المحرم، ويحتمل العطية التي يقدمها صاحبها ليأخذ أكثر منها؛ فجمع الحقيقة والمجاز ليبين أن الزيادة المنشودة من أموال الناس، بغير قصد وجه الله، لا تزكو عنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص387–388، تحت عنوان «بلاغة احتمال لفظ الربا للحقيقة والمجاز»","url":""}]},{"id":"s30-87","number":87,"surah":30,"verses":[39],"references":[{"surah":30,"verses":[39]}],"verseLabel":"الروم: 39","question":"لماذا قُيّد نفي نمو الربا بقوله: ﴿عِنْدَ اللَّهِ﴾؟","answer":"لأن المال قد يزداد في حساب الناس ظاهرًا، لكنه لا يورث ثوابًا ولا بركة عند الله إذا قصد به الاستزادة الدنيوية؛ فقلب القيد ميزان الربح من كثرة المال إلى رضوان الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص389، تحت عنوان «بلاغة ذكر قيد العندية»","url":""}]},{"id":"s30-40","number":40,"surah":30,"verses":[39],"references":[{"surah":30,"verses":[39]}],"verseLabel":"الروم: 39","question":"لماذا سمّى القرآن أهل الزكاة ﴿الْمُضْعِفُونَ﴾؟","answer":"لأنهم تسببوا بأعمالهم الصالحة في مضاعفة ثوابهم، فكأنهم هم الذين أحدثوا الإضعاف؛ وفي الاسم ثناء عليهم وتحريض على الإنفاق وثقة بوعد الله بالزيادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص392، تحت عنوان «بلاغة استعمال مفردة ﴿المضعفون﴾»","url":""}]},{"id":"s30-41","number":41,"surah":30,"verses":[40],"references":[{"surah":30,"verses":[40]}],"verseLabel":"الروم: 40","question":"ما الذي يكشفه ترتيب: ﴿خَلَقَكُمْ ثُمَّ رَزَقَكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ﴾؟","answer":"يرسم مراحل وجود الإنسان: الخلق مبدأ حياته، ثم رزقه مدة بقائه، ثم موته عند انقضاء أجله، ثم إحياؤه للبعث؛ فيجعل حياته كلها بين إيجاد الله وإمداده وإعادته، ويقيم بذلك حجة التوحيد والبعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص397، تحت عنوان «نكتة التعبير بحرف التراخي»","url":""}]},{"id":"s30-42","number":42,"surah":30,"verses":[41],"references":[{"surah":30,"verses":[41]}],"verseLabel":"الروم: 41","question":"ما الذي يشمله ظهور الفساد في ﴿الْبَرِّ وَالْبَحْرِ﴾؟","answer":"يشمل اللفظان اليابسة والبحار حقيقة، ويحتملان القرى والأمصار أو الحاضر والبادية مجازًا؛ فتتسع الصورة لكل بيئات الإنسان، وتوحي بأن آثار الفساد لم تعد محصورة في مكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص405–406، تحت عنوان «احتمال لفظ ﴿البر والبحر﴾ الحقيقة والمجاز»","url":""}]},{"id":"s30-43","number":43,"surah":30,"verses":[41],"references":[{"surah":30,"verses":[41]}],"verseLabel":"الروم: 41","question":"لماذا يذيق الله الناس ﴿بَعْضَ﴾ الذي عملوا لا جزاء أعمالهم كله؟","answer":"لأن ما يصيبهم في الدنيا ليس الجزاء الكامل، بل بعض آثار أعمالهم؛ وفي ذلك عفو عن كثير، وإنذار بما هو أشد إن استمروا، وفتح لباب الرجوع قبل الحساب التام في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص409، تحت عنوان «نكتة استعمال لفظ ﴿بعض﴾»","url":""}]},{"id":"s30-44","number":44,"surah":30,"verses":[42],"references":[{"surah":30,"verses":[42]}],"verseLabel":"الروم: 42","question":"لماذا أعاد القرآن الأمر بالسير في الأرض بعد الحديث عن ظهور الفساد؟","answer":"لأن الكلام انتقل من فساد يراه الناس في حاضرهم إلى عواقب أمم سابقة يشاهدون آثارها؛ فالسير يحول الخبر إلى عظة مرئية، ويثبت أن الشرك الذي أفسد أحوالهم انتهى بأصحابه إلى الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص413، تحت عنوان «علة الفصل في الآية»","url":""}]},{"id":"s30-45","number":45,"surah":30,"verses":[43],"references":[{"surah":30,"verses":[43]}],"verseLabel":"الروم: 43","question":"لماذا جاء الأمر بالاستقامة على الدين ﴿مِنْ قَبْلِ أَنْ يَأْتِيَ يَوْمٌ لَا مَرَدَّ لَهُ﴾؟","answer":"لأن الاستقامة مقبولة ما دام زمن العمل ممتدًا، فإذا جاء يوم القيامة انقطع الاختيار ولم تعد التوبة ممكنة؛ فالتعبير يستنهض إلى الثبات الآن ويحذر من تأجيله إلى وقت لا رجوع منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص425، تحت عنوان «دلالة الجار والمجرور ﴿من قبل﴾»","url":""}]},{"id":"s30-88","number":88,"surah":30,"verses":[43],"references":[{"surah":30,"verses":[43]}],"verseLabel":"الروم: 43","question":"ما الصورة التي ترسمها كلمة ﴿يَصَّدَّعُونَ﴾ للناس يوم القيامة؟","answer":"تصورهم كشيء صلب أصابه صدع فتفرق أجزاؤه؛ فينقسم الناس يومئذ فريقين متباعدين: أهل الإيمان وأهل الكفر، ويظهر التمايز الحاسم بينهم بعد اختلاطهم في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص428، تحت عنوان «دلالة التعبير بـ﴿يصدعون﴾؛ مادة وصيغة»","url":""}]},{"id":"s30-46","number":46,"surah":30,"verses":[44],"references":[{"surah":30,"verses":[44]}],"verseLabel":"الروم: 44","question":"ما الصورة في قوله عن العاملين الصالحات: ﴿فَلِأَنْفُسِهِمْ يَمْهَدُونَ﴾؟","answer":"يشبه عملهم بإعداد فراش أو منزل مريح يستقرون فيه؛ فهم لا يقدمون نفعًا لله، بل يهيئون لأنفسهم بأعمالهم مقامًا طيبًا في الجنة، وكأن كل طاعة لبنة في ذلك المهاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص436، تحت عنوان «سر التعبير بـ﴿يمهدون﴾ مادة وصيغة»","url":""}]},{"id":"s30-47","number":47,"surah":30,"verses":[46],"references":[{"surah":30,"verses":[46]}],"verseLabel":"الروم: 46","question":"ما سرّ وصف الرياح بأنها ﴿مُبَشِّرَاتٍ﴾؟","answer":"علاماتها تسبق المطر والرحمة، فكأنها تحمل البشرى قبل وصول العطاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص451–452، تحت عنوان «بلاغة الاستعارة في ﴿الرياح مبشرات﴾»","url":""}]},{"id":"s30-48","number":48,"surah":30,"verses":[47],"references":[{"surah":30,"verses":[47]}],"verseLabel":"الروم: 47","question":"لماذا أضاف القرآن النصر إلى المؤمنين جميعًا في قوله: ﴿نَصْرُ الْمُؤْمِنِينَ﴾؟","answer":"تكريمًا لهم وتشريفًا؛ فالنصر ليس مقصورًا على الرسل، بل للمؤمنين نصيب منه بحسب وعد الله وحكمته، وفي إضافته إليهم إشعار بعنايته بهم وتثبيت لقلوبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص469، تحت عنوان «وجه إضافة النصر إلى المؤمنين»","url":""}]},{"id":"s30-49","number":49,"surah":30,"verses":[48],"references":[{"surah":30,"verses":[48]}],"verseLabel":"الروم: 48","question":"لماذا وصف القرآن السحاب بأنه يُبسط في السماء؟","answer":"لأن السحاب بعد أن تجمعه الرياح ينتشر ويمتد بعضه متصلًا ببعض في صفحة السماء؛ فلفظ البسط يحول المشهد إلى بساط واسع منظور ويستحضر تجدده أمام العين.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص476، تحت عنوان «بلاغة التعبير بالبسط مادة وصيغة»","url":""}]},{"id":"s30-89","number":89,"surah":30,"verses":[48],"references":[{"surah":30,"verses":[48]}],"verseLabel":"الروم: 48","question":"ماذا تضيف كلمة ﴿كِسَفًا﴾ إلى صورة السحاب؟","answer":"تصوره قطعًا متفرقة بعضها فوق بعض، لا كتلة واحدة متصلة؛ فتظهر دقة تشكيل السحاب على هيئات مختلفة تمهد لنزول المطر.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص478، تحت عنوان «سر التعبير بـ﴿كسفا﴾»","url":""}]},{"id":"s30-90","number":90,"surah":30,"verses":[48],"references":[{"surah":30,"verses":[48]}],"verseLabel":"الروم: 48","question":"لماذا قال عن المطر: ﴿يَخْرُجُ مِنْ خِلَالِهِ﴾؟","answer":"لأن الماء يبرز من شقوق السحاب وفجواته كشيء كان كامنًا ثم نفذ إلى الخارج؛ فيجعل التعبير لحظة نزول المطر مشهدًا متجددًا تراه العين.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص479، تحت عنوان «إيثار التعبير بالخروج مادة وصيغة»","url":""}]},{"id":"s30-50","number":50,"surah":30,"verses":[49],"references":[{"surah":30,"verses":[49]}],"verseLabel":"الروم: 49","question":"ما سرّ تكرار ﴿مِنْ قَبْلُ﴾ في وصف إبلاسهم قبل نزول المطر؟","answer":"كرر «قبل» لتأكيد طول عهدهم بالمطر وما رسخ فيهم من الإبلاس قبل نزوله. فاشتداد اليأس وطول الانتظار يبرزان مقدار فرحتهم حين جاء الغيث وظهرت آثار الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص485، تحت عنوان «سر تكرار الظرف (قبل)»","url":""}]},{"id":"s30-51","number":51,"surah":30,"verses":[50],"references":[{"surah":30,"verses":[50]}],"verseLabel":"الروم: 50","question":"لماذا قال: ﴿فَانْظُرْ إِلَى آثَارِ رَحْمَتِ اللَّهِ﴾ ولم يقل: إلى المطر؟","answer":"لأن المقصود لا يقف عند قطرات المطر، بل يمتد إلى ما تتركه الرحمة من حياة الأرض واخضرارها وتنوع النبات والثمر؛ فجمع الآثار يفتح العين على نتائج النعمة الكثيرة، وإضافتها إلى الرحمة تردها إلى المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص487–488، تحت عنوان «بلاغة التعبير بـ﴿آثار﴾»","url":""}]},{"id":"s30-52","number":52,"surah":30,"verses":[52,53],"references":[{"surah":30,"verses":[52,53]}],"verseLabel":"الروم: 52-53","question":"لماذا شبّه القرآن المعرضين عن الحق بالموتى؟","answer":"لأن قلوبهم فقدت الاستجابة لما يحييها من الوحي، فصار سماعهم بلا انتفاع كالميت الذي لا يستجيب للنداء؛ والتشبيه يبين أن العجز معنوي اختاروه بالإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص514، تحت عنوان «بلاغة المجاز في التعبير بـ﴿الموتى﴾»","url":""}]},{"id":"s30-53","number":53,"surah":30,"verses":[54],"references":[{"surah":30,"verses":[54]}],"verseLabel":"الروم: 54","question":"لماذا كرر القرآن كلمة ﴿ضَعْفٍ﴾ في مراحل عمر الإنسان؟","answer":"لأن الضعف الأول ضعف الطفولة، والأخير ضعف الشيخوخة، وبين الأفراد في كل مرحلة درجات متفاوتة؛ فجاء التنكير والتكرار ليصور تنوع الضعف وتجدده، لا حالة واحدة تعود كما هي.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص536، تحت عنوان «نكتة تنكير ﴿ضعف﴾ وتكرارها»","url":""}]},{"id":"s30-91","number":91,"surah":30,"verses":[54],"references":[{"surah":30,"verses":[54]}],"verseLabel":"الروم: 54","question":"ما الذي تكشفه إعادة ﴿ثُمَّ جَعَلَ﴾ بين الضعف والقوة والشيب؟","answer":"تكشف أن الإنسان ينتقل بأمر الله طورًا بعد طور: من ضعف إلى قوة ثم إلى ضعف وشيبة؛ فليست القوة ملكًا ثابتًا له، بل مرحلة عابرة بين ضعفين تشهد بتدبير خالقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص539، تحت عنوان «بلاغة التكرار في ﴿ثم جعل﴾»","url":""}]},{"id":"s30-54","number":54,"surah":30,"verses":[55],"references":[{"surah":30,"verses":[55]}],"verseLabel":"الروم: 55","question":"بماذا يشبه قوله: ﴿كَذَلِكَ كَانُوا يُؤْفَكُونَ﴾ خطأهم في تقدير مدة اللبث؟","answer":"يشبه صرفهم عن تقدير المدة والواقع يوم القيامة بصرفهم في الدنيا عن الحق الواضح؛ فالخلل واحد: مكابرة تقلب الحقيقة في وعيهم حتى إذا ظهرت الآخرة انكشف بطلانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص555، تحت عنوان «بلاغة التشبيه في ﴿كذلك﴾»","url":""}]},{"id":"s30-55","number":55,"surah":30,"verses":[56],"references":[{"surah":30,"verses":[56]}],"verseLabel":"الروم: 56","question":"لماذا قُدّم العلم على الإيمان في وصف من يصححون مدة اللبث؟","answer":"لأن العلم المبني على الدليل يوصل إلى الإيمان الراسخ، ولأن المقام مقام تصحيح لقول الجاهلين وتقرير لحقيقة البعث؛ فناسب إبراز العلم أولًا ثم الإيمان الذي يثمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص564، تحت عنوان «نكتة تقديم ﴿العلم﴾ على ﴿الإيمان﴾»","url":""}]},{"id":"s30-92","number":92,"surah":30,"verses":[56],"references":[{"surah":30,"verses":[56]}],"verseLabel":"الروم: 56","question":"ما دلالة قول أهل العلم: ﴿لَقَدْ لَبِثْتُمْ فِي كِتَابِ اللَّهِ﴾؟","answer":"يردون تقدير المدة إلى علم الله وقضائه المثبت، لا إلى ظن المجرمين المضطرب؛ فـ﴿كتاب الله﴾ يجعل الحقيقة محيطة بهم ومحفوظة لا يغيرها قسمهم ولا شعورهم بقصر الزمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص565، تحت عنوان «نكتة تقييد لبثهم بالجار والمجرور ﴿في كتاب﴾»","url":""}]},{"id":"s30-56","number":56,"surah":30,"verses":[58],"references":[{"surah":30,"verses":[58]}],"verseLabel":"الروم: 58","question":"ماذا يفيد قوله: ﴿مِنْ كُلِّ مَثَلٍ﴾ عن بيان القرآن للناس؟","answer":"يفيد أن القرآن نوّع وجوه البيان والأمثال التي تهدي إلى الإيمان بالبعث والتوحيد، فلم يترك حجة نافعة إلا عرض معناها بأسلوب يقربها؛ فبقاء التكذيب بعد ذلك عناد لا نقص في البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص581، تحت عنوان «دلالة التعبير بلفظ العموم في قوله ﴿كل﴾»","url":""}]},{"id":"s30-57","number":57,"surah":30,"verses":[60],"references":[{"surah":30,"verses":[60]}],"verseLabel":"الروم: 60","question":"ماذا توحي كلمة ﴿يَسْتَخِفَّنَّكَ﴾ في النهي عن التأثر بالمكذبين؟","answer":"تصور محاولتهم أن يزعزعوا ثبات الداعية حتى يطيش أو يستعجل ويترك ما هو عليه؛ فالنهي يدعوه إلى الرسوخ والصبر وألا تجعل سخرية من لا يوقن وزنًا يستخفه عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص599، تحت عنوان «نكتة التعبير بلفظ الاستخفاف»","url":""}]},{"id":"s30-93","number":93,"surah":30,"verses":[60],"references":[{"surah":30,"verses":[60]}],"verseLabel":"الروم: 60","question":"كيف تعود خاتمة سورة الروم إلى بدايتها؟","answer":"افتتحت السورة بوعد غيبي تحقق بنصر الروم وبفرح المؤمنين، وختمت بتثبيت النبي على وعد الله ونهيه أن يتأثر بمن لا يوقنون؛ فجمع الطرفان أن الإيمان بالغيب والثقة بوعد الله قضية السورة الجامعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص601، تحت عنوان «بلاغة رد عجز السورة الكريمة على صدرها»","url":""}]},{"id":"s31-1","number":1,"surah":31,"verses":[1],"references":[{"surah":31,"verses":[1]}],"verseLabel":"لقمان: 1","question":"ما وجه افتتاح سورة لقمان بـ﴿الم﴾؟","answer":"افتتحت بالحروف المقطعة للتنبيه إلى القرآن وإثارة الإصغاء إليه، وفيها إيماء إلى أنه من جنس الحروف التي يتكلم بها المخاطبون، مع استمرار تحديهم بالإتيان بمثله.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص618، تحت عنوان «براعة الإعجاز في استهلال السورة»","url":""}]},{"id":"s31-2","number":2,"surah":31,"verses":[2],"references":[{"surah":31,"verses":[2]}],"verseLabel":"لقمان: 2","question":"ما سرّ وصف آيات الكتاب بـ﴿الْحَكِيمِ﴾؟","answer":"الحكيم يحتمل معنى المحكم الذي لا خلل فيه، وذا الحكمة لاشتماله على الحكم والمواعظ؛ فوصف الكتاب يقرر إحكامه وما ينطق به من حكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص621–622، تحت عنوان «دلالة الوصف مادة وصيغة»","url":""}]},{"id":"s31-3","number":3,"surah":31,"verses":[3],"references":[{"surah":31,"verses":[3]}],"verseLabel":"لقمان: 3","question":"لماذا قُدّم الهدى على الرحمة في وصف القرآن؟","answer":"لأن الهداية هي الطريق إلى الرحمة؛ فمن اهتدى بالوحي بلغ آثار الرحمة في الدنيا والآخرة، فوافق الترتيب تدرج السبب إلى الثمرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص625، تحت عنوان «نكتة تقديم وصف الهدى على الرحمة»","url":""}]},{"id":"s31-37","number":37,"surah":31,"verses":[3],"references":[{"surah":31,"verses":[3]}],"verseLabel":"لقمان: 3","question":"لماذا خُصّ المحسنون بهداية القرآن ورحمته؟","answer":"لأن المحسن بلغ مرتبة يراقب فيها الله ويجود بالعمل، فهو أقدر على الانتفاع بالوحي؛ ووصف الإحسان يجمع الإيمان والطاعة ويشوق إلى بلوغ أعلى مراتب السلوك.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص626، تحت عنوان «علة اختيار وصف الإحسان»","url":""}]},{"id":"s31-4","number":4,"surah":31,"verses":[4],"references":[{"surah":31,"verses":[4]}],"verseLabel":"لقمان: 4","question":"ما سرّ تكرار الضمير في ﴿وَهُمْ بِالْآخِرَةِ هُمْ يُوقِنُونَ﴾؟","answer":"تكرار الضمير مع تقديم الجار والمجرور يؤكد رسوخ يقينهم بالآخرة، ويقصر اليقين الحق عليهم في مقابلة منكريها ومن اختل اعتقادهم فيها؛ فهو اختصاص إضافي يبرز كمال إيمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص633، تحت عنوان «بلاغة الحصر في قوله: ﴿وهم بالآخرة هم يوقنون﴾»","url":""}]},{"id":"s31-5","number":5,"surah":31,"verses":[6],"references":[{"surah":31,"verses":[6]}],"verseLabel":"لقمان: 6","question":"ما سرّ التعبير بـ﴿يَشْتَرِي لَهْوَ الْحَدِيثِ﴾؟","answer":"صور إيثار لهو الحديث على القرآن بصورة شراء المرغوب فيه، فدل على شدة الحرص عليه وسوء الاختيار. وذكر المبحث أيضًا حمل الاشتراء على حقيقته، فيكون كناية عن الحرص على تحصيل اللهو وبذل المال فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص649–650، تحت عنوان «دلالة الاشتراء بين الاستعارة والكناية»","url":""}]},{"id":"s31-6","number":6,"surah":31,"verses":[7],"references":[{"surah":31,"verses":[7]}],"verseLabel":"لقمان: 7","question":"ما التدرج في قوله: ﴿كَأَنْ لَمْ يَسْمَعْهَا كَأَنَّ فِي أُذُنَيْهِ وَقْرًا﴾؟","answer":"تبدأ الصورة بمن سمع الآيات لكنه أعرض كأنه لم يسمع، ثم تشتد إلى من كأن في أذنيه ثقلًا يمنع أصل السماع؛ فتوالي التشبيهين يكشف انتقال الاستكبار من تجاهل متعمد إلى انغلاق راسخ عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص664–665، تحت عنوان «نكتة توالي التشبيهات»","url":""}]},{"id":"s31-7","number":7,"surah":31,"verses":[10],"references":[{"surah":31,"verses":[10]}],"verseLabel":"لقمان: 10","question":"ما أوجه معنى ﴿بِغَيْرِ عَمَدٍ تَرَوْنَهَا﴾؟","answer":"إذا عاد الضمير في ﴿ترونها﴾ إلى العمد، احتمل الكلام عمدًا غير مرئية، أو نفي العمد أصلًا فلا توجد حتى ترى. وإذا عاد إلى السماوات كان المعنى: ترون السماوات قائمة بغير عمد؛ وفي هذه الأوجه إبراز القدرة في خلقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص688، تحت عنوان «دلالة التعبير بقوله: ﴿ترونها﴾»","url":""}]},{"id":"s31-8","number":8,"surah":31,"verses":[10],"references":[{"surah":31,"verses":[10]}],"verseLabel":"لقمان: 10","question":"ما سر التعبير بخلق السماوات بغير عمد قبل ذكر إلقاء الرواسي في الأرض؟","answer":"بدأ بالسماوات لأن آياتها أعظم وأظهر في الدلالة على الربوبية، ومن ذلك علوها وثباتها بغير عمد مرئية؛ ثم أتبعها بآيات الأرض الأقرب إلى المخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص687، تحت عنوان «نكتة تقديم خلق ﴿السماوات﴾ على إلقائه في ﴿الأرض﴾»","url":""}]},{"id":"s31-9","number":9,"surah":31,"verses":[11],"references":[{"surah":31,"verses":[11]}],"verseLabel":"لقمان: 11","question":"لماذا قال: ﴿هَذَا خَلْقُ اللَّهِ﴾ باسم الإشارة؟","answer":"ليوجّه النظر إلى المخلوقات المشاهدة كأنها حاضرة يشار إليها: السماوات والأرض والجبال والدواب؛ فالحجة ليست فكرة بعيدة، بل آثار عظمة الله تحيط بالإنسان وتدعوه إلى الشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص699، تحت عنوان «دلالة التعبير باسم الإشارة»","url":""}]},{"id":"s31-38","number":38,"surah":31,"verses":[11],"references":[{"surah":31,"verses":[11]}],"verseLabel":"لقمان: 11","question":"ما سر التحدي في قوله: ﴿فَأَرُونِي مَاذَا خَلَقَ الَّذِينَ مِنْ دُونِهِ﴾؟","answer":"ليس طلبًا لجواب ممكن، بل إلزام للمشركين أن يبرزوا دليلًا لا يملكونه؛ فحين يعجزون عن إظهار مخلوق لشركائهم تسقط دعوى استحقاقهم للعبادة من أصلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص700–701، تحت عنوان «دلالة الأمر»","url":""}]},{"id":"s31-10","number":10,"surah":31,"verses":[12],"references":[{"surah":31,"verses":[12]}],"verseLabel":"لقمان: 12","question":"لماذا لُخّصت حكمة لقمان في الأمر: ﴿أَنِ اشْكُرْ لِلَّهِ﴾؟","answer":"لأن الشكر يجمع معرفة المنعم وإقرار القلب بنعمته والثناء عليه واستعمال النعمة في طاعته؛ فهو ثمرة الحكمة العملية، وبدايته تربية الإنسان على رد الفضل إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص710، تحت عنوان «بلاغة الإيجاز في ﴿أن اشكر لله﴾»","url":""}]},{"id":"s31-11","number":11,"surah":31,"verses":[12],"references":[{"surah":31,"verses":[12]}],"verseLabel":"لقمان: 12","question":"من المستفيد من شكر الإنسان في قوله: ﴿فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ﴾؟","answer":"العبد نفسه؛ فثمرة الشكر تعود عليه بزيادة النعمة وثباتها ونماء الإيمان، أما الله فغني عن شكر العالمين، ولا يزيد ملكه بطاعة ولا ينقص بجحود.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص712، تحت عنوان «بلاغة القصر في قوله: ﴿فإنما يشكر لنفسه﴾»","url":""}]},{"id":"s31-12","number":12,"surah":31,"verses":[13],"references":[{"surah":31,"verses":[13]}],"verseLabel":"لقمان: 13","question":"ما سرّ افتتاح وصية لقمان بنداء ﴿يَا بُنَيَّ﴾؟","answer":"التصغير للتحبيب والشفقة، فيدخل أعظم تحذير من باب القرب لا القسوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص724، تحت عنوان «نكتة التعبير بلفظ البنوة وإضافته»","url":""}]},{"id":"s31-13","number":13,"surah":31,"verses":[13],"references":[{"surah":31,"verses":[13]}],"verseLabel":"لقمان: 13","question":"لماذا اجتمعت المؤكدات في قوله: ﴿إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ﴾؟","answer":"لتثبيت شناعة الشرك في النفس بأقوى بيان؛ فقد اجتمع في الجملة إن واللام والبناء الاسمي ووصف الظلم بالعظمة، حتى يظهر أن التحذير منه أصل لا يحتمل التهوين أو التردد.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص727، تحت عنوان «بلاغة توالي المؤكدات»","url":""}]},{"id":"s31-39","number":39,"surah":31,"verses":[13],"references":[{"surah":31,"verses":[13]}],"verseLabel":"لقمان: 13","question":"لماذا نُكّر الظلم في قوله: ﴿لَظُلْمٌ عَظِيمٌ﴾؟","answer":"للتعظيم والتهويل؛ فالشرك ليس ظلمًا عابرًا، بل ظلم بالغ متعدد الوجوه، وأشنعها أن يُسوَّى المخلوق بالخالق في العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص728، تحت عنوان «نكتة تنكير لفظ الظلم»","url":""}]},{"id":"s31-14","number":14,"surah":31,"verses":[14],"references":[{"surah":31,"verses":[14]}],"verseLabel":"لقمان: 14","question":"لماذا قيل: ﴿وَهْنًا عَلَى وَهْنٍ﴾، لا وهنًا بعد وهن؟","answer":"لأن ﴿على﴾ تصور الضعف متراكبًا بعضه فوق بعض؛ فكلما مضت مدة الحمل ازداد ثقل الأم ووهنها، حتى تبدو المشقة طبقات متتابعة لا مرحلة تنقضي ثم تنفصل عنها أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص736، تحت عنوان «نكتة التعبير بحرف الاستعلاء ﴿على﴾»","url":""}]},{"id":"s31-15","number":15,"surah":31,"verses":[15],"references":[{"surah":31,"verses":[15]}],"verseLabel":"لقمان: 15","question":"كيف يجتمع قوله: ﴿فَلَا تُطِعْهُمَا﴾ مع قوله: ﴿وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا﴾؟","answer":"يفصل القرآن بين رفض الباطل وبر الوالدين: فلا طاعة لهما في الشرك، لكن يبقى حقهما في الصحبة الحسنة والرفق والقيام بما يحتاجان إليه؛ فالخلاف في العقيدة لا يبيح العقوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص746–747، تحت عنوان «دلالة العطف في قوله: ﴿وصاحبهما﴾»","url":""}]},{"id":"s31-16","number":16,"surah":31,"verses":[16],"references":[{"surah":31,"verses":[16]}],"verseLabel":"لقمان: 16","question":"لماذا افترضت الآية أن تكون حبة الخردل ﴿فِي صَخْرَةٍ﴾؟","answer":"لتجمع غاية الصغر مع غاية الخفاء والحجب؛ فحتى لو استقرت الحبة الدقيقة داخل صخرة صماء شديدة التحصين، لم يمنع ذلك إحاطة علم الله بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص761، تحت عنوان «دلالة الظرفية في قوله: ﴿في صخرة﴾»","url":""}]},{"id":"s31-40","number":40,"surah":31,"verses":[16],"references":[{"surah":31,"verses":[16]}],"verseLabel":"لقمان: 16","question":"ما الذي تصوره عبارة ﴿يَأْتِ بِهَا اللَّهُ﴾ بعد خفاء حبة الخردل؟","answer":"تصور كمال العلم والقدرة معًا: فالله لا يعلم العمل الخفي فحسب، بل يستخرجه ويحضره للحساب مهما دق أو بَعُد مكانه؛ وفي ذلك وعد للمحسن ووعيد للمسيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص764، تحت عنوان «بلاغة الكناية في قوله: ﴿يأت بها الله﴾»","url":""}]},{"id":"s31-17","number":17,"surah":31,"verses":[16],"references":[{"surah":31,"verses":[16]}],"verseLabel":"لقمان: 16","question":"ما سرّ ختم الآية بـ﴿إِنَّ اللَّهَ لَطِيفٌ خَبِيرٌ﴾؟","answer":"اللطيف يصل علمه وتدبيره إلى الدقائق، والخبير يعلم باطنها وحقيقتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص765–766، تحت عنوان «نكتة تذييل الآية بالاسمين الجليلين»","url":""}]},{"id":"s31-18","number":18,"surah":31,"verses":[17],"references":[{"surah":31,"verses":[17]}],"verseLabel":"لقمان: 17","question":"لماذا عطف لقمان الأمر بالمعروف والنهي عن المنكر على إقامة الصلاة؟","answer":"لأن الصلاة تصلح الإنسان في نفسه، ثم ينتقل أثر صلاحه إلى غيره بالدعوة إلى الخير ومنع الشر؛ فجمع التوجيه بين بناء النفس والإسهام في إصلاح المجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص769–770، تحت عنوان «غرض العطف على إقامة الصلاة»","url":""}]},{"id":"s31-41","number":41,"surah":31,"verses":[17],"references":[{"surah":31,"verses":[17]}],"verseLabel":"لقمان: 17","question":"لماذا جاء الصبر بعد الأمر بالمعروف والنهي عن المنكر؟","answer":"لأن من يدعو إلى المعروف وينهى عن المنكر قد يلقى أذى وعداوة؛ فجاء الصبر ليحفظه من الانقطاع، وليبين أن تبعات الإصلاح جزء من الطريق لا سبب لتركه.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص771، تحت عنوان «غرض عطف الصبر»","url":""}]},{"id":"s31-19","number":19,"surah":31,"verses":[18],"references":[{"surah":31,"verses":[18]}],"verseLabel":"لقمان: 18","question":"ما الصورة التي يرسمها قوله: ﴿وَلَا تُصَعِّرْ خَدَّكَ لِلنَّاسِ﴾؟","answer":"يرسم المتكبر وهو يميل بخده ويصرف وجهه عن الناس احتقارًا لهم؛ فجاءت الكناية بصورة جسدية مستقبحة تجعل الكبر مرئيًا، وتدعو إلى الإقبال على الناس بتواضع وبشاشة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص779، تحت عنوان «بلاغة الكناية في تصعير الخد»","url":""}]},{"id":"s31-21","number":21,"surah":31,"verses":[19],"references":[{"surah":31,"verses":[19]}],"verseLabel":"لقمان: 19","question":"ماذا يعني الأمر: ﴿وَاقْصِدْ فِي مَشْيِكَ﴾؟","answer":"يعني التوسط والاعتدال في المشي، بعيدًا عن خيلاء المتكبر وتهافت المستعجل وتماوت المتصنع؛ فالقصد هيئة متزنة تظهر فيها سكينة الإنسان بلا إفراط ولا تفريط.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص787، تحت عنوان «دلالة تقييد القصد بالمشي»","url":""}]},{"id":"s31-42","number":42,"surah":31,"verses":[19],"references":[{"surah":31,"verses":[19]}],"verseLabel":"لقمان: 19","question":"لماذا جُمع بين الاعتدال في المشي وخفض الصوت؟","answer":"لأن أدب الإنسان الظاهر يُرى في حركته ويُسمع في صوته؛ فجمع التوجيه بين السمت الهادئ والكلام المعتدل حتى ينسجم ظاهر السلوك مع تهذيب الباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص788، تحت عنوان «دلالة عطف الصوت على قصد المشي»","url":""}]},{"id":"s31-22","number":22,"surah":31,"verses":[19],"references":[{"surah":31,"verses":[19]}],"verseLabel":"لقمان: 19","question":"لماذا شُبّه الصوت المنكر بصوت الحمير؟","answer":"لأن نهيق الحمار يجمع شدة الارتفاع وقبح الوقع من غير حاجة؛ فضرب به المثل ينفر من رفع الصوت المزعج، ويجعل قبحه حاضرًا في السمع والخيال.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص789، تحت عنوان «علة فصل قوله: ﴿إن أنكر الأصوات لصوت الحمير﴾»","url":""}]},{"id":"s31-23","number":23,"surah":31,"verses":[20],"references":[{"surah":31,"verses":[20]}],"verseLabel":"لقمان: 20","question":"ما الصورة التي ترسمها كلمة ﴿أَسْبَغَ﴾ لنعم الله؟","answer":"تصور النعم كالثوب السابغ الذي يحيط بالإنسان ويغمره من كل جانب؛ فليست نعمًا متفرقة قليلة، بل عطايا وافرة تامة تشمل قيام حياته وهدايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص801–802، تحت عنوان «دلالة التعبير بـ﴿وأسبغ﴾ مادة وصيغة»","url":""}]},{"id":"s31-43","number":43,"surah":31,"verses":[20],"references":[{"surah":31,"verses":[20]}],"verseLabel":"لقمان: 20","question":"لماذا وُصفت النعم بأنها ﴿ظَاهِرَةً وَبَاطِنَةً﴾؟","answer":"ليحيط الوصف بكل ما يدركه الإنسان من النعم وما يخفى عليه؛ فالطباق بين الظاهر والباطن يفيد الاستغراق، ويوقظ إلى أن ألطاف الله أوسع من أن تُحصى بما نراه وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص805، تحت عنوان «بلاغة الطباق في قوله: ﴿ظاهرة وباطنة﴾»","url":""}]},{"id":"s31-24","number":24,"surah":31,"verses":[20],"references":[{"surah":31,"verses":[20]}],"verseLabel":"لقمان: 20","question":"ما دلالة نفي العلم والهدى والكتاب المنير عن جدالهم في الله؟","answer":"نُفيت عنه أصول الاحتجاج: علم محقق، وهدى يرشد إلى الحق، وكتاب منير يحتج به؛ فبقي جدالًا مجردًا من مستند.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص813، تحت عنوان «بلاغة أسلوب التقسيم في الآية»","url":""}]},{"id":"s31-25","number":25,"surah":31,"verses":[21],"references":[{"surah":31,"verses":[21]}],"verseLabel":"لقمان: 21","question":"ماذا تكشف ﴿بَلْ﴾ في جوابهم: ﴿بَلْ نَتَّبِعُ مَا وَجَدْنَا عَلَيْهِ آبَاءَنَا﴾؟","answer":"تكشف أنهم أعرضوا عن دعوة الوحي بلا حجة، وانتقلوا إلى التمسك بالموروث لمجرد أنه موروث؛ فـ﴿بل﴾ تفضح أن التقليد حل عندهم محل النظر في الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص15، تحت عنوان «معنى ﴿بل﴾ ودلالتها»","url":""}]},{"id":"s31-44","number":44,"surah":31,"verses":[21],"references":[{"surah":31,"verses":[21]}],"verseLabel":"لقمان: 21","question":"لماذا عبّروا عن موروثهم بقولهم: ﴿مَا وَجَدْنَا عَلَيْهِ آبَاءَنَا﴾؟","answer":"لأن ذكر الآباء يستدعي سلطان الموروث القديم وهيبته في النفس؛ فبدل أن يزنوا القول بالحجة جعلوا قدمه وانتسابه إلى الآباء كافيًا لقبوله، وفي ذلك تصوير لتعطيل النظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص17–18، تحت عنوان «نكتة التعبير عن اتباعهم موروثاتهم بـ﴿آباءنا﴾»","url":""}]},{"id":"s31-45","number":45,"surah":31,"verses":[21],"references":[{"surah":31,"verses":[21]}],"verseLabel":"لقمان: 21","question":"ما الذي يفضحه الاستفهام: ﴿أَوَلَوْ كَانَ الشَّيْطَانُ يَدْعُوهُمْ إِلَى عَذَابِ السَّعِيرِ﴾؟","answer":"يفضح أن تقليدهم أعمى إلى حد أنهم يتبعون الآباء ولو كان الطريق يقودهم إلى العذاب؛ فالاستفهام يهدم عذر الموروث، ويطالبهم بمعرفة حقيقة من يدعوهم وغاية دعوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص18، تحت عنوان «علة الاستفهام في قوله: ﴿أولو كان﴾»","url":""}]},{"id":"s31-26","number":26,"surah":31,"verses":[22],"references":[{"surah":31,"verses":[22]}],"verseLabel":"لقمان: 22","question":"ما سرّ التعبير بـ﴿فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقَى﴾؟","answer":"شبّه الإسلام والإخلاص لله بعروة وثيقة يمسك بها المستسلم المحسن فلا تنفصم.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص31–32، تحت عنوان «بلاغة الاستعارة التمثيلية»","url":""}]},{"id":"s31-27","number":27,"surah":31,"verses":[27],"references":[{"surah":31,"verses":[27]}],"verseLabel":"لقمان: 27","question":"لماذا عبّر بالماضي ﴿نَفِدَتْ﴾ في صورة افتراضية لم تقع؟","answer":"لإبراز النتيجة في صورة الأمر المحقق: ستنفد الأقلام والبحار حتمًا، بينما لا تنفد كلمات الله؛ فصيغة الماضي تثبت اليقين قبل وقوع الفرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص71، تحت عنوان «دلالة التعبير بـ﴿نفدت﴾ مادة وصيغة»","url":""}]},{"id":"s31-28","number":28,"surah":31,"verses":[27],"references":[{"surah":31,"verses":[27]}],"verseLabel":"لقمان: 27","question":"ما سرّ التعبير بالعدد ﴿سَبْعَةُ أَبْحُرٍ﴾؟","answer":"صرح المبحث بأن السبعة مستعملة كناية عن الكثرة، فلا يتوقف المعنى على حصر البحار في سبعة؛ والغرض تصوير أن الإمداد مهما كثر لا يستوعب كلمات الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص70، تحت عنوان «غرض التعبير بالعدد: ﴿سبعة﴾»","url":""}]},{"id":"s31-29","number":29,"surah":31,"verses":[28],"references":[{"surah":31,"verses":[28]}],"verseLabel":"لقمان: 28","question":"ما سرّ التعبير بـ﴿مَا خَلْقُكُمْ وَلَا بَعْثُكُمْ إِلَّا كَنَفْسٍ وَاحِدَةٍ﴾؟","answer":"الكثرة لا تثقل القدرة؛ إيجاد الجميع وإعادتهم كإيجاد فرد واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص78، تحت عنوان «معنى الكاف في قوله: ﴿كنفس﴾ وبلاغة التشبيه»","url":""}]},{"id":"s31-31","number":31,"surah":31,"verses":[30],"references":[{"surah":31,"verses":[30]}],"verseLabel":"لقمان: 30","question":"إلى ماذا يشير قوله: ﴿ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ﴾؟","answer":"يشير إلى الآيات المشاهدة المذكورة قبلها من تسخير الكون وتدبيره، ثم يجعلها دليلًا حاضرًا على أن الله هو الحق؛ فالإشارة تنقل القارئ من مشاهدة الأثر إلى اليقين بربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص96، تحت عنوان «دلالة الجملة المصدرة بالإشارة»","url":""}]},{"id":"s31-46","number":46,"surah":31,"verses":[30],"references":[{"surah":31,"verses":[30]}],"verseLabel":"لقمان: 30","question":"لماذا صرحت الآية بأن ما يُدعى من دون الله هو الباطل، ولم تكتف بأن الله هو الحق؟","answer":"لإغلاق الباب من جهتيه: إثبات استحقاق الله وحده للعبادة، وإبطال استحقاق كل ما سواه؛ فمجرد تقرير الحق قد يترك في نفس المشرك شبهة مشاركة غيره، فجاء التصريح ليزيلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص99، تحت عنوان «نكتة تقرير البطلان دون الاكتفاء بالأحقية»","url":""}]},{"id":"s31-32","number":32,"surah":31,"verses":[31],"references":[{"surah":31,"verses":[31]}],"verseLabel":"لقمان: 31","question":"ما سرّ تشبيه الموج بـ﴿الظُّلَلِ﴾؟","answer":"الموج العالي يظل من تحته كالسحاب أو الجبال، فيغمر الإنسان بالخوف من فوقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص120، تحت عنوان «بلاغة التشبيه المرسل ﴿موج كالظلل﴾»","url":""}]},{"id":"s31-33","number":33,"surah":31,"verses":[32],"references":[{"surah":31,"verses":[32]}],"verseLabel":"لقمان: 32","question":"ما سرّ الجمع بين وصفي ﴿خَتَّارٍ كَفُورٍ﴾؟","answer":"الختار شديد الغدر؛ جمع نقض عهد الضر وجحود نعمة النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص129، تحت عنوان «غرض صيغة المبالغة: ﴿ختار كفور﴾»","url":""}]},{"id":"s31-34","number":34,"surah":31,"verses":[33],"references":[{"surah":31,"verses":[33]}],"verseLabel":"لقمان: 33","question":"لماذا بدأ التحذير يوم القيامة بالوالد قبل الولد؟","answer":"لأن الوالد أسبق وجودًا، وهو أشد شفقة وأعمق تعلقًا بولده؛ فإذا عجز مع قوة رحمته عن نفعه يوم القيامة، كان عجز غيره أولى وأظهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص138، تحت عنوان «علة البدء بالوالد قبل الولد»","url":""}]},{"id":"s31-47","number":47,"surah":31,"verses":[33],"references":[{"surah":31,"verses":[33]}],"verseLabel":"لقمان: 33","question":"لماذا عُدل من ﴿وَلَد﴾ إلى ﴿مَوْلُودٌ﴾ في قوله: ﴿وَلَا مَوْلُودٌ هُوَ جَازٍ عَنْ وَالِدِهِ شَيْئًا﴾؟","answer":"لأن ﴿مولود﴾ يستحضر رابطة الولادة نفسها، وهي أوثق أسباب القرب؛ فإذا انقطعت منفعتها يوم القيامة مع شدتها، انقطع ما هو دونها من الروابط من باب أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص141، تحت عنوان «نكتة العدول عن (ولد) إلى ﴿مولود﴾»","url":""}]},{"id":"s31-35","number":35,"surah":31,"verses":[33],"references":[{"surah":31,"verses":[33]}],"verseLabel":"لقمان: 33","question":"كيف نُسب التغرير إلى ﴿الْحَيَاةُ الدُّنْيَا﴾ وهي لا تتكلم ولا تخدع؟","answer":"نُسب إليها مجازًا لأنها ظرف الفتن والشهوات التي يستعملها أهل الباطل في الإغراء؛ أما الفاعل المباشر للتغرير فهو الشيطان ومن يزينون للناس، فجاء الأسلوب ليحذر من البيئة المغرية ومن صانع الغرور معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص144، تحت عنوان «بلاغة المجاز العقلي في تغرير الحياة»","url":""}]},{"id":"s31-48","number":48,"surah":31,"verses":[33],"references":[{"surah":31,"verses":[33]}],"verseLabel":"لقمان: 33","question":"كيف يكون الإنسان مغرورًا ﴿بِاللَّهِ﴾؟","answer":"حين يخدعه الشيطان بسعة رحمة الله وكرمه، فيحوّل الرجاء إلى جرأة على المعصية وتسويف للتوبة؛ فالآية تمنع أن يُتخذ حلم الله وفضله ذريعة للأمن من الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص145، تحت عنوان «معنى الباء في شبه الجملة ﴿بالله﴾»","url":""}]},{"id":"s31-36","number":36,"surah":31,"verses":[34],"references":[{"surah":31,"verses":[34]}],"verseLabel":"لقمان: 34","question":"لماذا جاءت مفاتح الغيب بعد قوله: ﴿إِنَّ وَعْدَ اللَّهِ حَقٌّ﴾؟","answer":"لأن تقرير الوعد يثير في الذهن سؤالًا عن موعد الساعة؛ فجاء الجواب بأن علمها عند الله وحده، مثبتًا قرب الوعد ويقينه من غير أن يجعل للإنسان سبيلًا إلى تعيين زمنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص149، تحت عنوان «نكتة فصل الآية عن سابقتها»","url":""}]},{"id":"s31-49","number":49,"surah":31,"verses":[34],"references":[{"surah":31,"verses":[34]}],"verseLabel":"لقمان: 34","question":"ما الحكمة من جمع هذه الغيوب الخمسة في ختام سورة لقمان؟","answer":"جُعل انفراد الله بعلم الساعة هو المقصد الأساس، وأُدمجت معه أمثلة من الغيب تمس المطر والأرحام وكسب الغد ومكان الموت؛ لتربي الإنسان على العمل والافتقار إلى الله، لا على ادعاء التحكم بالمستقبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص150، تحت عنوان «بلاغة الإدماج بين جمل الآية»","url":""}]},{"id":"s31-50","number":50,"surah":31,"verses":[34],"references":[{"surah":31,"verses":[34]}],"verseLabel":"لقمان: 34","question":"لماذا أثبتت الآية العلم لله في أول الغيوب، ثم نفت العلم عن النفس في الأخيرين؟","answer":"لأن الغيوب الأولى أعظم وأظهر في اختصاص الله بها، فجيء فيها بالإثبات له، أما كسب الغد ومكان الموت فهما ألصق بتخطيط الإنسان، فنُفي علمه بهما ليظهر عجزه؛ ثم خُتم بـ﴿عليم خبير﴾ لإثبات العلم الكامل لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص160–161، تحت عنوان «نكتة إسناد الغيوب بين الإثبات والنفي»","url":""}]},{"id":"s32-1","number":1,"surah":32,"verses":[1],"references":[{"surah":32,"verses":[1]}],"verseLabel":"السجدة: 1","question":"ما وجه افتتاح سورة السجدة بـ﴿الم﴾؟","answer":"افتتحت بالحروف المقطعة تنبيهًا إلى شأن القرآن وتحديه، ثم أعقبها تقرير تنزيل الكتاب من رب العالمين؛ ولا يجزم في تعيين معنى الحروف بوجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص177–178، تحت عنوان «سر الاستهلال بالحروف المقطعة ودلالاتها»","url":""}]},{"id":"s32-2","number":2,"surah":32,"verses":[2],"references":[{"surah":32,"verses":[2]}],"verseLabel":"السجدة: 2","question":"لماذا افتتحت سورة السجدة بقولها: ﴿تَنْزِيلُ الْكِتَابِ﴾؟","answer":"لتضع حقيقة المصدر في الواجهة: القرآن منزل من علو، متدرج بحسب الحكمة، وليس كلامًا صنعه محمد ﷺ؛ فلفظ ﴿تنزيل﴾ يلائم مقام الرد على المكذبين ويعظم شأن الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص178–179، تحت عنوان «نكتة الابتداء بالتنزيل مادة وصيغة»","url":""}]},{"id":"s32-32","number":32,"surah":32,"verses":[2],"references":[{"surah":32,"verses":[2]}],"verseLabel":"السجدة: 2","question":"كيف قال القرآن: ﴿لَا رَيْبَ فِيهِ﴾ مع وجود المرتابين فيه؟","answer":"المنفي ليس وقوع الشك في نفوس بعض الناس، بل أن يكون في الكتاب نفسه ما يوجب شكًا معتبرًا؛ فدلائله واضحة، ومن ارتاب فعلة ريبه من موقفه لا من نقص في القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص183، تحت عنوان «نكتة نفي الريب مع وجود المرتابين»","url":""}]},{"id":"s32-33","number":33,"surah":32,"verses":[2],"references":[{"surah":32,"verses":[2]}],"verseLabel":"السجدة: 2","question":"لماذا قيل إن تنزيل الكتاب ﴿مِنْ رَبِّ الْعَالَمِينَ﴾؟","answer":"لفظ الرب يستحضر التربية والرعاية، وإضافته إلى العالمين تبين عموم سلطانه ورحمته؛ فنزول الكتاب صورة من ربوبيته التي تهدي الخلق وتربيهم، لا خطابًا منعزلًا عن مصالحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص184–185، تحت عنوان «نكتة التعبير بلفظ ﴿رب﴾، وإضافته»","url":""}]},{"id":"s32-3","number":3,"surah":32,"verses":[3],"references":[{"surah":32,"verses":[3]}],"verseLabel":"السجدة: 3","question":"ما سرّ الانتقال من حكاية قولهم ﴿افْتَرَاهُ﴾ إلى تقرير ﴿بَلْ هُوَ الْحَقُّ﴾؟","answer":"لم يكتف القرآن برد تهمة الافتراء، بل أبطلها إبطالًا حاسمًا وأثبت نقيضها؛ فالقرآن هو الحق الثابت الذي لا يتطرق إليه باطل، وبذلك انتقل الكلام من إسقاط دعواهم إلى تقرير الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص191–192، تحت عنوان «معنى ﴿بل﴾، وغرض التعبير بها»","url":""}]},{"id":"s32-34","number":34,"surah":32,"verses":[3],"references":[{"surah":32,"verses":[3]}],"verseLabel":"السجدة: 3","question":"لماذا قيل عن القرآن: ﴿الْحَقُّ مِنْ رَبِّكَ﴾؟","answer":"لأن ﴿من﴾ تبين ابتداء هذا الحق ومصدره، ولفظ ﴿ربك﴾ يستحضر عناية الله بنبيه وتربيته وتأييده؛ فالوحي آت من ربه الذي يتولى أمره، لا من اختلاق بشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص193، تحت عنوان «دلالة ﴿من﴾ في قوله: ﴿من ربك﴾»","url":""}]},{"id":"s32-4","number":4,"surah":32,"verses":[4],"references":[{"surah":32,"verses":[4]}],"verseLabel":"السجدة: 4","question":"لماذا فُصل قوله: ﴿مَا لَكُمْ مِنْ دُونِهِ مِنْ وَلِيٍّ وَلَا شَفِيعٍ﴾ عما قبله؟","answer":"جاءت الجملة استئنافًا يجيب عما يثيره تمام خلق الله وتدبيره: إذا كان الخالق المدبر واحدًا، فلا ولي يستقل بنصرتكم ولا شفيع يعمل بغير إذنه؛ فالفصل يقرر انفراد الله بالملك ويهدم توهم الشركاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص211، تحت عنوان «نكتة فصل قوله: ﴿ما لكم من دونه من ولي ولا شفيع﴾»","url":""}]},{"id":"s32-5","number":5,"surah":32,"verses":[5],"references":[{"surah":32,"verses":[5]}],"verseLabel":"السجدة: 5","question":"لماذا كان يوم العروج هنا ﴿أَلْفَ سَنَةٍ﴾، وفي المعارج ﴿خَمْسِينَ أَلْفَ سَنَةٍ﴾؟","answer":"لأن السياقين يصوران مقامين مختلفين: آية السجدة في تدبير الأمر وعروجه خلال زمن مقداره ألف سنة، أما آية المعارج ففي يوم القيامة وشدته وطول مسافته؛ فاختلف المقدار باختلاف المقام المصوَّر.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص229–230، تحت عنوان «بلاغة المتشابه اللفظي»","url":""}]},{"id":"s32-6","number":6,"surah":32,"verses":[6],"references":[{"surah":32,"verses":[6]}],"verseLabel":"السجدة: 6","question":"ما سر ترتيب الصفات: ﴿عَالِمُ الْغَيْبِ وَالشَّهَادَةِ الْعَزِيزُ الرَّحِيمُ﴾؟","answer":"بدأ بالعلم المحيط لأنه أصل الحكم والتدبير، ثم بالعزة التي لا يعجز معها تنفيذ الإرادة، وختم بالرحمة التي هي أصل الإحسان الآتي في خلق الإنسان؛ فترسم الصفات علمًا كاملًا وقدرة نافذة ورحمة واسعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص240، تحت عنوان «نكتة ترتيب ﴿عالم﴾، ﴿العزيز﴾، ﴿الرحيم﴾»","url":""}]},{"id":"s32-7","number":7,"surah":32,"verses":[7],"references":[{"surah":32,"verses":[7]}],"verseLabel":"السجدة: 7","question":"كيف يشمل الإحسان ﴿كُلَّ شَيْءٍ﴾ مع أن بعض المخلوقات يبدو قبيحًا أو ضارًا؟","answer":"لأن كل مخلوق أُعطي الهيئة التي تلائم غايته ومنفعته في نظام الخلق؛ فما يبدو قبحًا أو ضررًا من زاوية محدودة لا ينفي ما وراءه من حكمة وصلاح، فلفظة ﴿كل﴾ تقرر شمول الإتقان الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص243، تحت عنوان «حكمة التعبير بلفظة ﴿كل﴾»","url":""}]},{"id":"s32-8","number":8,"surah":32,"verses":[7,8,9],"references":[{"surah":32,"verses":[7,8,9]}],"verseLabel":"السجدة: 7-9","question":"لماذا ذُكر أن بدء خلق الإنسان كان ﴿مِنْ طِينٍ﴾؟","answer":"ليجمع بين إظهار قدرة الله وتذكير الإنسان بأصله المتواضع؛ فقد أخرج من مادة أرضية مهينة هذا المخلوق الحي العاقل، وفي ذلك ما يهدم الكبر ويبعث على تعظيم الخالق.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص245، تحت عنوان «دلالات التعبير بقوله: ﴿من طين﴾»","url":""}]},{"id":"s32-35","number":35,"surah":32,"verses":[7,8,9],"references":[{"surah":32,"verses":[7,8,9]}],"verseLabel":"السجدة: 7-9","question":"ما دلالة قوله: ﴿جَعَلَ نَسْلَهُ مِنْ سُلَالَةٍ مِنْ مَاءٍ مَهِينٍ﴾؟","answer":"يصور امتداد الذرية من خلاصة تُستخرج وتنفصل من أصلها، مع التذكير بضعف مادتها؛ فاجتمع في ﴿سلالة﴾ معنى الاستخراج والامتداد، وفي ﴿ماء مهين﴾ بيان أن عظمة الإنسان لاحقة بصنع الله لا بأصل مادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص246–247، تحت عنوان «نكتة التعبير بالجعل مع النسل»","url":""}]},{"id":"s32-9","number":9,"surah":32,"verses":[9],"references":[{"surah":32,"verses":[9]}],"verseLabel":"السجدة: 9","question":"لماذا أعقب تعداد النعم بقوله: ﴿قَلِيلًا مَا تَشْكُرُونَ﴾؟","answer":"ليتحول السياق من عرض المنن إلى توبيخ من عطلها عن غايتها؛ فبعد السمع والبصر والفؤاد تظهر قلة الشكر أشد قبحًا، وجاءت الجملة مستقلة لتقرر حال الكافرين وتلفت إلى جسامة تقصيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص255، تحت عنوان «نكتة فصل قوله: ﴿قليلا ما تشكرون﴾»","url":""}]},{"id":"s32-10","number":10,"surah":32,"verses":[10],"references":[{"surah":32,"verses":[10]}],"verseLabel":"السجدة: 10","question":"لماذا عبّر المنكرون عن تفرق أجسادهم بقولهم: ﴿ضَلَلْنَا فِي الْأَرْضِ﴾؟","answer":"لأن الضلال يصور الذهاب والخفاء؛ فكأن أجزاءهم حين تختلط بالتراب تضيع معالمها وتغيب فيه، فجاء اللفظ بصورة محسوسة لما توهموه مانعًا من الإعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص264، تحت عنوان «بلاغة التعبير بالضلال»","url":""}]},{"id":"s32-11","number":11,"surah":32,"verses":[11],"references":[{"surah":32,"verses":[11]}],"verseLabel":"السجدة: 11","question":"ما الذي يصوره التعبير عن الموت بقوله: ﴿يَتَوَفَّاكُمْ﴾؟","answer":"يصور الموت استيفاءً كاملًا للإنسان لا ضياعًا له؛ فملك الموت يقبض النفس التي استكملت أجلها، وفي ذلك رد على توهمهم أن تفرق الأجساد يمنع الرجوع إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص272–273، تحت عنوان «نكتة التعبير بجملة ﴿يتوفاكم﴾»","url":""}]},{"id":"s32-36","number":36,"surah":32,"verses":[11],"references":[{"surah":32,"verses":[11]}],"verseLabel":"السجدة: 11","question":"لماذا وُصف ملك الموت بأنه ﴿الَّذِي وُكِّلَ بِكُمْ﴾؟","answer":"ليبين أن قبض الأرواح يجري بتكليف وتدبير لا بفوضى؛ فهو موكل بكل من انتهى أجله، وإلصاق الباء في ﴿بكم﴾ يشعر بشدة الملازمة وأن أحدًا لا يفلت من مهمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص275، تحت عنوان «دلالة الاسم الموصول وصلته»","url":""}]},{"id":"s32-12","number":12,"surah":32,"verses":[12],"references":[{"surah":32,"verses":[12]}],"verseLabel":"السجدة: 12","question":"ما الصورة التي يرسمها قوله: ﴿نَاكِسُوا رُءُوسِهِمْ﴾؟","answer":"يرسم المجرمين وقد خفضوا رؤوسهم ذلًا وخزيًا بعد استكبارهم في الدنيا؛ وجاء اسم الفاعل ليثبت الهيئة ويصورها ممتدة، كأن الناظر يراها قائمة أمامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص285، تحت عنوان «نكتة التعبير بـ﴿ناكسوا﴾ مادة وصيغة»","url":""}]},{"id":"s32-37","number":37,"surah":32,"verses":[12],"references":[{"surah":32,"verses":[12]}],"verseLabel":"السجدة: 12","question":"ماذا يضيف قوله: ﴿عِنْدَ رَبِّهِمْ﴾ إلى مشهد المجرمين ناكسي الرؤوس؟","answer":"يضعهم في مقام القهر والتمكن، حيث لا مهرب من حكم ربهم، ويذكرهم بأن من أعرضوا عنه هو ربهم الحقيقي الذي أحاطهم بالتربية والنعم؛ فزاد التعبير المشهد ذلًا وحسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص286، تحت عنوان «فائدة التعبير بالعندية: ﴿عند ربهم﴾»","url":""}]},{"id":"s32-13","number":13,"surah":32,"verses":[12],"references":[{"surah":32,"verses":[12]}],"verseLabel":"السجدة: 12","question":"ما سرّ تقديم الإبصار على السمع في قولهم ﴿رَبَّنَا أَبْصَرْنَا وَسَمِعْنَا﴾؟","answer":"قُدّم الإبصار لأن مقام القيامة مقام مشاهدة لما كانوا يسمعون خبره وينكرونه؛ فصار المرئي يومئذ أسبق في اعترافهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص289، تحت عنوان «نكتة تقديم الإبصار على السمع»","url":""}]},{"id":"s32-14","number":14,"surah":32,"verses":[13],"references":[{"surah":32,"verses":[13]}],"verseLabel":"السجدة: 13","question":"لماذا قيل: ﴿لَآتَيْنَا كُلَّ نَفْسٍ هُدَاهَا﴾، ولم يقل: لهديناها؟","answer":"لأن الإيتاء يصور الهداية عطية ميسرة من الله تحمل معنى التفضل والتمكين، ويؤكد أن جمع النفوس كلها على الهدى لو شاءه الله أمر هيّن لا يعجزه.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص302، تحت عنوان «سر التعبير بالإيتاء في قوله: ﴿لآتينا﴾»","url":""}]},{"id":"s32-15","number":15,"surah":32,"verses":[14],"references":[{"surah":32,"verses":[14]}],"verseLabel":"السجدة: 14","question":"لماذا أُضيف اللقاء إلى اليوم في قوله: ﴿لِقَاءَ يَوْمِكُمْ هَذَا﴾؟","answer":"لتشخيص اليوم كأنه قادم يلقى الناس ولا مهرب منه، مع تهويل ما يقع فيه؛ وإضافته إليهم في ﴿يومكم﴾ تجعله موعدهم الخاص الذي حُذروا منه طويلًا ثم صار حاضرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص314، تحت عنوان «إضافة اللقاء إلى اليوم»","url":""}]},{"id":"s32-16","number":16,"surah":32,"verses":[15],"references":[{"surah":32,"verses":[15]}],"verseLabel":"السجدة: 15","question":"ما سرّ تصوير استجابتهم للآيات بقوله ﴿خَرُّوا سُجَّدًا﴾؟","answer":"جاء السجود استجابة فورية تهوي فيها الأجساد حين ترتفع الحقيقة في القلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص327، تحت عنوان «دلالة التعبير بـ﴿خروا﴾ مادة وصيغة»","url":""}]},{"id":"s32-17","number":17,"surah":32,"verses":[16],"references":[{"surah":32,"verses":[16]}],"verseLabel":"السجدة: 16","question":"ما الصورة التي ترسمها كناية ﴿تَتَجَافَى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ﴾؟","answer":"تصور الأجساد كأنها تنفر من الفراش وتبتعد عنه؛ فرغبتهم في مناجاة الله أقوى من جاذبية الراحة، وفي إسناد التجافي إلى الجنوب تجسيد لمجاهدة النفس وكثرة القيام.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص336، تحت عنوان «بلاغة الكناية في مجافاة الجنوب عن المضاجع»","url":""}]},{"id":"s32-18","number":18,"surah":32,"verses":[16],"references":[{"surah":32,"verses":[16]}],"verseLabel":"السجدة: 16","question":"لماذا عُطف الإنفاق على الدعاء في قوله: ﴿يَدْعُونَ رَبَّهُمْ خَوْفًا وَطَمَعًا وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَ﴾؟","answer":"ليجمع وصفهم بين عبادة القلب والبدن في الدعاء، والإحسان إلى الغير بالمال؛ فصلاح النفس لا ينفصل عن البذل، كما جمعت الآية بين خيري الدنيا والآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص340، تحت عنوان «دلالة العطف في قوله: ﴿ومما رزقناهم ينفقون﴾»","url":""}]},{"id":"s32-19","number":19,"surah":32,"verses":[17],"references":[{"surah":32,"verses":[17]}],"verseLabel":"السجدة: 17","question":"لماذا عبّر عن جزاء المؤمنين بقوله: ﴿مَا أُخْفِيَ لَهُمْ﴾؟","answer":"لتعظيم الجزاء الذي تجاوز علم النفوس وتصورها، ولمناسبة ما أخفاه المؤمنون من صلاة الليل والطاعات؛ فكان الجزاء الخفي للعمل الخفي، وكأن المفاجأة نفسها جزء من النعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص346، تحت عنوان «نكتة توظيف الفعل ﴿أخفي﴾»","url":""}]},{"id":"s32-38","number":38,"surah":32,"verses":[17],"references":[{"surah":32,"verses":[17]}],"verseLabel":"السجدة: 17","question":"لماذا قيل: ﴿قُرَّةِ أَعْيُنٍ﴾ بالجمع والتنكير، لا «قرة عيون»؟","answer":"لأن ﴿أعين﴾ جمع قلة يناسب جماعة المؤمنين إذا قورنت بغيرهم، وتنكيرها للتعظيم والخصوص؛ فلكل مؤمن من النعيم ما تقر به عينه، وجاء اللفظ على الأسلوب القرآني المألوف في هذا المعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص348، تحت عنوان «سر التعبير بـ﴿أعين﴾ منكرة دون (عيون)»","url":""}]},{"id":"s32-20","number":20,"surah":32,"verses":[18],"references":[{"surah":32,"verses":[18]}],"verseLabel":"السجدة: 18","question":"لماذا جاءت المفاضلة في صورة السؤال: ﴿أَفَمَنْ كَانَ مُؤْمِنًا كَمَنْ كَانَ فَاسِقًا﴾، ولم تأت خبرًا مباشرًا؟","answer":"لإلجاء المنكر إلى الاعتراف بالحكم بنفسه؛ فالتفاوت بين المؤمن والفاسق ظاهر لا يحتمل التسوية، والاستفهام الإنكاري أبلغ من الخبر لأنه يجعل الخصم ينطق بالنتيجة قبل تفصيل الجزاءين.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص355، تحت عنوان «نكتة بناء الآية على الاستفهام لا الخبرية»","url":""}]},{"id":"s32-21","number":21,"surah":32,"verses":[20],"references":[{"surah":32,"verses":[20]}],"verseLabel":"السجدة: 20","question":"ماذا تفيد ﴿كُلَّمَا﴾ في قوله: ﴿كُلَّمَا أَرَادُوا أَنْ يَخْرُجُوا مِنْهَا أُعِيدُوا فِيهَا﴾؟","answer":"تفيد أن محاولة الخروج تتكرر مرة بعد مرة، ويتكرر معها ردهم إلى النار؛ فتجدد الحركة أملًا عابرًا ثم تكسره الإعادة، وبذلك يتجدد العذاب النفسي مع العذاب الحسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص369، تحت عنوان «بلاغة التعبير بـ﴿كلما﴾ في الآية»","url":""}]},{"id":"s32-22","number":22,"surah":32,"verses":[20],"references":[{"surah":32,"verses":[20]}],"verseLabel":"السجدة: 20","question":"ما سرّ تذكير الموصول في ﴿عَذَابَ النَّارِ الَّذِي كُنْتُمْ بِهِ تُكَذِّبُونَ﴾؟","answer":"جاء الموصول المذكر ﴿الذي﴾ وصفًا لـ﴿عذاب﴾، فعاد إليه الضمير في ﴿به﴾ أيضًا. وذكر المبحث أن سياق السورة اعتنى بالعذاب ووصفه بالأدنى والأكبر، فناسب أن يكون هو محور الصلة والتكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص375، تحت عنوان «ومن المتشابه اللفظي أيضا»","url":""}]},{"id":"s32-23","number":23,"surah":32,"verses":[21],"references":[{"surah":32,"verses":[21]}],"verseLabel":"السجدة: 21","question":"لماذا وُصف عذاب الدنيا بـ﴿الْأَدْنَى﴾ وعذاب الآخرة بـ﴿الْأَكْبَرِ﴾؟","answer":"عذاب الدنيا أدنى لقربه وأخف من عذاب الآخرة، أما عذاب الآخرة فأكبر لشدة هوله ودوامه؛ وجاء الوصفان بما يهز النفوس، لعل العذاب القريب يوقظهم فيرجعوا قبل الأكبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص381، تحت عنوان «دلالة وصف ﴿العذاب﴾ بـ﴿الأدنى﴾ و﴿الأكبر﴾»","url":""}]},{"id":"s32-24","number":24,"surah":32,"verses":[22],"references":[{"surah":32,"verses":[22]}],"verseLabel":"السجدة: 22","question":"ما دلالة ﴿ثُمَّ﴾ في قوله: ﴿ثُمَّ أَعْرَضَ عَنْهَا﴾ بعد التذكير بآيات الله؟","answer":"تبرز بُعد الإعراض عن مقتضى العقل بعد وضوح الآيات؛ فالمتوقع أن يقود التذكير إلى الاتعاظ، فإذا به يعرض، فجاءت ﴿ثم﴾ لتصور التفاوت الشديد بين ما عُرض عليه وما اختاره.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص391، تحت عنوان «بلاغة استعمال حرف التراخي»","url":""}]},{"id":"s32-25","number":25,"surah":32,"verses":[23],"references":[{"surah":32,"verses":[23]}],"verseLabel":"السجدة: 23","question":"كيف يكون «اللقاء» تعبيرًا عن إصابة الإنسان بما أصاب غيره؟","answer":"لأن البلاء يستقبل الإنسان ويصادفه كما يلقى شخصٌ شخصًا؛ وعلى هذا الوجه يكون المعنى: لا تشك في أن يصيبك من تكذيب قومك وأذاهم مثل ما أصاب موسى، وفيه تسلية للنبي ﷺ وتثبيت له.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص402، تحت عنوان «براعة المجاز في التعبير عن الإصابة باللقاء»","url":""}]},{"id":"s32-26","number":26,"surah":32,"verses":[24],"references":[{"surah":32,"verses":[24]}],"verseLabel":"السجدة: 24","question":"لماذا اقترن الصبر باليقين في صفات الأئمة الهادين؟","answer":"لأن قيادة الناس في الدين تحتاج صبرًا يحمل صاحبه على الثبات أمام المشقة، ويقينًا يمنع التردد في الحق؛ فإذا نقص أحدهما ضعفت الاستقامة أو البصيرة، وبهما تُحمل أعباء الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص412، تحت عنوان «علة اقتران الصبر باليقين»","url":""}]},{"id":"s32-27","number":27,"surah":32,"verses":[26],"references":[{"surah":32,"verses":[26]}],"verseLabel":"السجدة: 26","question":"ماذا يحقق الاستفهام في قوله: ﴿أَوَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا مِنْ قَبْلِهِمْ﴾؟","answer":"يقرر أن مصائر الأمم الماضية دليل ظاهر كان ينبغي أن يهديهم؛ فهم يمشون في مساكن الهالكين ويسمعون أخبارهم، فالاستفهام يوبخهم على غفلة لا تنقصها الشواهد بل ينقصها الاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص427، تحت عنوان «بلاغة الاستفهام وغرضه»","url":""}]},{"id":"s32-28","number":28,"surah":32,"verses":[27],"references":[{"surah":32,"verses":[27]}],"verseLabel":"السجدة: 27","question":"لماذا صُوِّر إيصال الماء إلى الأرض الجرز بقوله: ﴿نَسُوقُ الْمَاءَ﴾؟","answer":"لأن الماء يصل إليها محمولًا بالسحب التي تدفعها الرياح كما يُساق الشيء إلى غايته؛ والمضارع يصور استمرار التدبير، فيجعل إحياء الأرض اليابسة مشهدًا حاضرًا يدل على قدرة الله على البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص432–433، تحت عنوان «دلالة استعمال مفردة ﴿نسوق﴾ مادة وصيغة»","url":""}]},{"id":"s32-29","number":29,"surah":32,"verses":[28],"references":[{"surah":32,"verses":[28]}],"verseLabel":"السجدة: 28","question":"ماذا يكشف تعليق سؤالهم بقولهم: ﴿إِنْ كُنْتُمْ صَادِقِينَ﴾؟","answer":"يكشف أن سؤالهم عن الفتح لم يكن طلبًا للعلم، بل تحديًا ساخرًا يطعن في صدق المؤمنين؛ فقد علقوا وقوعه على شرط يوحي عندهم باستبعاده، فجاءت العبارة محملة بالتكذيب والاستهزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص443، تحت عنوان «غرض الإتيان بالجملة الشرطية»","url":""}]},{"id":"s32-30","number":30,"surah":32,"verses":[29],"references":[{"surah":32,"verses":[29]}],"verseLabel":"السجدة: 29","question":"لماذا لم يُجبهم القرآن عن موعد ﴿يَوْمِ الْفَتْحِ﴾، وأخبرهم بما سيقع فيه؟","answer":"لأن سؤالهم كان استهزاءً واستعجالًا، فصُرفوا بالأسلوب الحكيم من معرفة الموعد إلى ما ينفعهم: عند مجيء الفصل لا ينفع المكذب إيمان متأخر ولا يُمهل؛ فالأولى الاستعداد لا الجدل في الزمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص446–447، تحت عنوان «بلاغة الأسلوب الحكيم»","url":""}]},{"id":"s32-31","number":31,"surah":32,"verses":[30],"references":[{"surah":32,"verses":[30]}],"verseLabel":"السجدة: 30","question":"لماذا خُتمت السورة بالأمرين: ﴿فَأَعْرِضْ عَنْهُمْ وَانْتَظِرْ﴾؟","answer":"ليترك النبي ﷺ جدال من استحكم عناده، ثم ينتظر وعد الله بالنصر والحكم؛ فالإعراض ليس يأسًا من الدعوة، بل مفارقة للمراء بعد إقامة الحجة، والانتظار ثقة بالعاقبة وتهديد للمكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص448–449، تحت عنوان «بلاغة فعل الأمر وغرضه»","url":""}]},{"id":"s32-39","number":39,"surah":32,"verses":[30],"references":[{"surah":32,"verses":[30]}],"verseLabel":"السجدة: 30","question":"ما سر التقابل بين ﴿وَانْتَظِرْ﴾ و﴿إِنَّهُمْ مُنْتَظِرُونَ﴾؟","answer":"تشابه اللفظ واختلف المنتظر: النبي ﷺ ينتظر النصر الموعود، وهم ينتظرون به وبالمؤمنين السوء؛ فالجناس يكشف المفارقة بين الفريقين، ويجعل خاتمة السورة وعيدًا ساخرًا بأن العاقبة ستأتي على خلاف انتظارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص450، تحت عنوان «بلاغة الجناس المستوفى في المقابلة اللفظية»","url":""}]},{"id":"s33-1","number":1,"surah":33,"verses":[1],"references":[{"surah":33,"verses":[1]}],"verseLabel":"الأحزاب: 1","question":"لماذا افتتحت السورة بنداء الرسول ﷺ بوصف ﴿النَّبِيُّ﴾؟","answer":"للتشريف والتنبيه إلى أن ما يأتي متعلق بمقام الرسالة؛ فالنداء يوقظ السامعين إلى أهمية التوجيه، ويذكر النبي ﷺ بمهمته، ويعلم الأمة أدب خطابه بما يليق بمنزلته.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص468–469، تحت عنوان «أغراض النداء بوصف النبوة»","url":""}]},{"id":"s33-65","number":65,"surah":33,"verses":[1],"references":[{"surah":33,"verses":[1]}],"verseLabel":"الأحزاب: 1","question":"كيف يؤمر النبي ﷺ بقوله: ﴿اتَّقِ اللَّهَ﴾ وهو أتقى الناس؟","answer":"الأمر ليس اتهامًا بتقصير، بل تثبيت على التقوى وطلب للدوام والازدياد في كمالها، وفي توجيهه إلى النبي ﷺ تأكيد للأمة أن مقام النبوة لا يستغني عن ملازمة أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص470–471، تحت عنوان «دلالة الأمر ﴿اتق الله﴾»","url":""}]},{"id":"s33-2","number":2,"surah":33,"verses":[1],"references":[{"surah":33,"verses":[1]}],"verseLabel":"الأحزاب: 1","question":"ما سرّ الجمع بين النهي عن طاعة الكافرين والمنافقين؟","answer":"جمع الكافرين والمنافقين لاتفاقهم في إرادة إضرار النبي والمؤمنين، مع اختلاف ظاهر حالهم: أولئك يجاهرون بالكفر، وهؤلاء يظهرون الإسلام ويضمرون خلافه. فالنهي يحذر من طاعة الفريقين فيما يعارض الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص473، تحت عنوان «نكتة عطف ﴿والمنافقين﴾ على ﴿الكافرين﴾»","url":""}]},{"id":"s33-3","number":3,"surah":33,"verses":[2],"references":[{"surah":33,"verses":[2]}],"verseLabel":"الأحزاب: 2","question":"لماذا عُطف الأمر ﴿وَاتَّبِعْ مَا يُوحَى إِلَيْكَ﴾ مباشرة على النهي عن طاعة الكافرين والمنافقين؟","answer":"لأن ترك ضغط أهل الباطل لا يترك فراغًا؛ فالطريق المقابل المحدد هو اتباع الوحي. وبذلك يقوي العطف اليقين بأن النجاة ليست في مساومتهم، بل في التزام ما أنزله الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص477، تحت عنوان «فائدة العطف بالواو ﴿واتبع﴾»","url":""}]},{"id":"s33-4","number":4,"surah":33,"verses":[3],"references":[{"surah":33,"verses":[3]}],"verseLabel":"الأحزاب: 3","question":"ما الذي يجمعه التعبير: ﴿وَكَفَى بِاللَّهِ وَكِيلًا﴾؟","answer":"يجمع معنى التوكل على الله ومعنى الاكتفاء به؛ فكأن الآية تقول: فوض أمرك إليه واكتف بكفايته، فهو المتكفل الذي لا يعجزه ما وُكل إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص485، تحت عنوان «بلاغة التضمين في قوله ﴿وكفى بالله وكيلًا﴾»","url":""}]},{"id":"s33-5","number":5,"surah":33,"verses":[4],"references":[{"surah":33,"verses":[4]}],"verseLabel":"الأحزاب: 4","question":"لماذا بدأ إبطال الظهار والتبني بحقيقة: ﴿مَا جَعَلَ اللَّهُ لِرَجُلٍ مِنْ قَلْبَيْنِ فِي جَوْفِهِ﴾؟","answer":"ليقرر أولًا حقيقة بدهيّة لا تقبل الجدل: كما يستحيل أن يجتمع قلبان مستقلان في جوف واحد، لا تجعل الألفاظ المتناقضة الزوجة أمًا ولا الدعي ابنًا؛ فالكلام لا يبدل الحقائق.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص497، تحت عنوان «فائدة الجملة الخبرية»","url":""}]},{"id":"s33-6","number":6,"surah":33,"verses":[4],"references":[{"surah":33,"verses":[4]}],"verseLabel":"الأحزاب: 4","question":"لماذا زيد قوله: ﴿فِي جَوْفِهِ﴾ مع أن القلب لا يكون إلا في الجوف؟","answer":"لزيادة تصوير الاستحالة في موضعها المحسوس؛ فذكر الجوف يستحضر مكان القلب أمام الذهن ويؤكد أن اجتماع قلبين مستقلين فيه ممتنع، تمهيدًا لإبطال دعاوى تخالف الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص496–497، تحت عنوان «فائدة الظرفية ﴿في جوفه﴾»","url":""}]},{"id":"s33-7","number":7,"surah":33,"verses":[4],"references":[{"surah":33,"verses":[4]}],"verseLabel":"الأحزاب: 4","question":"ماذا تكشف تسمية المتبنَّين بـ﴿أَدْعِيَاءَكُمْ﴾؟","answer":"تكشف أن بنوتهم مجرد دعوى بالقول لا نسبًا حقيقيًا؛ فاللفظة نفسها تفصل بين المسمى الذي صنعته العادة وبين الحقيقة التي لا يغيرها التبني.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص502–503، تحت عنوان «دلالة التعبير بلفظة الأدعياء»","url":""}]},{"id":"s33-8","number":8,"surah":33,"verses":[5],"references":[{"surah":33,"verses":[5]}],"verseLabel":"الأحزاب: 5","question":"لماذا كان ردُّ الناس إلى أنساب آبائهم ﴿أَقْسَطُ عِنْدَ اللَّهِ﴾؟","answer":"لأنه أعدل وأصدق في حفظ الأنساب والحقوق؛ فيُنسب الابن إلى أبيه الحقيقي، ولا تترتب أحكام البنوة على دعوى، مع بقاء رابطة الأخوة والموالاة لمن جُهل أبوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص516، تحت عنوان «دلالة التعبير بمادة القسط»","url":""}]},{"id":"s33-9","number":9,"surah":33,"verses":[5],"references":[{"surah":33,"verses":[5]}],"verseLabel":"الأحزاب: 5","question":"ما سر المقابلة بين ﴿أَخْطَأْتُمْ بِهِ﴾ و﴿مَا تَعَمَّدَتْ قُلُوبُكُمْ﴾؟","answer":"لتفصل بين سبق اللسان الذي لم يقصده القلب وبين المخالفة التي استقرت فيها النية؛ فالمؤاخذة تتجه إلى التعمد بعد البيان، لا إلى الخطأ العارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص524، تحت عنوان «بلاغة المقابلة بين ﴿أخطأتم﴾ و﴿تعمدت قلوبكم﴾»","url":""}]},{"id":"s33-10","number":10,"surah":33,"verses":[6],"references":[{"surah":33,"verses":[6]}],"verseLabel":"الأحزاب: 6","question":"ما دلالة كون النبي ﷺ ﴿أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ﴾؟","answer":"أي أن ولايته وتوجيهه أحق بالتقديم من رغباتهم؛ لأنه أشفق عليهم وأعلم بما يصلحهم، فطاعته ليست تغليبًا لمصلحة خاصة بل تقديمًا لما فيه نجاتهم في الدين والدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص533، تحت عنوان «دلالة التعبير بصيغة المفاضلة ﴿أولى﴾»","url":""}]},{"id":"s33-11","number":11,"surah":33,"verses":[6],"references":[{"surah":33,"verses":[6]}],"verseLabel":"الأحزاب: 6","question":"ما سرّ وصف أزواج النبي ﷺ بأنهن ﴿أُمَّهَاتُهُمْ﴾؟","answer":"شُبهن بالأمهات في وجوب التعظيم والتوقير وحرمة الزواج بهن، لا في جميع أحكام النسب؛ فلا يستلزم هذا الوصف إباحة الخلوة أو الإرث بهن.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص536، تحت عنوان «بلاغة التشبيه في الآية»","url":""}]},{"id":"s33-12","number":12,"surah":33,"verses":[7],"references":[{"surah":33,"verses":[7]}],"verseLabel":"الأحزاب: 7","question":"لماذا قُدِّم النبي ﷺ على نوح هنا، مع أن نوحًا أسبق زمنًا؟","answer":"لأن النبي ﷺ هو المقصود الأول بالخطاب، فقدم تشريفًا وعناية بمقامه، ثم عُطف عليه نوح وبقية أولي العزم تعظيمًا للميثاق الجامع بينهم؛ فالترتيب هنا ترتيب عناية لا ترتيب زمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص555، تحت عنوان «نكتة عطف الأنبياء المذكورين على ﴿النبيين﴾»","url":""}]},{"id":"s33-13","number":13,"surah":33,"verses":[9],"references":[{"surah":33,"verses":[9]}],"verseLabel":"الأحزاب: 9","question":"ما الذي تكشفه المقابلة بين جنود الأحزاب وجنود الله؟","answer":"تكشف أن الحرب في حقيقتها لم تكن بين قوتين بشريتين متكافئتين؛ فحشد الأحزاب المرئي قابله الله بريح وجنود لا تُرى، ليظهر أن النصر بتدبيره وأسباب لا يملكها حساب القوة الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص579، تحت عنوان «بلاغة المقابلة بين جنودهم وجنود الله»","url":""}]},{"id":"s33-14","number":14,"surah":33,"verses":[10],"references":[{"surah":33,"verses":[10]}],"verseLabel":"الأحزاب: 10","question":"ما الصورة التي يرسمها قوله: ﴿زَاغَتِ الْأَبْصَارُ﴾؟","answer":"يرسم العيون وقد مالت عن استقامة النظر من شدة الدهشة والرعب؛ فلا يثبت البصر على وجهته، وكأن الخوف نفسه دفعه إلى الانحراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص590، تحت عنوان «بلاغة المجاز في قوله: ﴿زاغت الأبصار﴾»","url":""}]},{"id":"s33-66","number":66,"surah":33,"verses":[10],"references":[{"surah":33,"verses":[10]}],"verseLabel":"الأحزاب: 10","question":"ما الصورة التي يرسمها قوله: ﴿وَبَلَغَتِ الْقُلُوبُ الْحَنَاجِرَ﴾؟","answer":"يصور اضطراب القلوب من الفزع حتى كأنها ارتفعت من الصدور وبلغت الحلق، وهي مبالغة حسية تجعل ضيقهم وهلعهم مشهدًا يكاد يُرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص590، تحت عنوان «بلاغة المجاز: ﴿وبلغت القلوب الحناجر﴾»","url":""}]},{"id":"s33-15","number":15,"surah":33,"verses":[10],"references":[{"surah":33,"verses":[10]}],"verseLabel":"الأحزاب: 10","question":"لماذا جُمعت الظنون في قوله: ﴿وَتَظُنُّونَ بِاللَّهِ الظُّنُونَا﴾؟","answer":"لأن الخواطر في ساعة الشدة تعددت واختلفت: المؤمن يتقلب بين الخوف والرجاء وهو واثق بوعد الله، والمنافق يسيء الظن ويستبعد النجاة؛ فالجمع يستوعب أنواع الظنون ويهول اضطراب الموقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص593، تحت عنوان «بلاغة (أل) في ﴿الظنونا﴾»","url":""}]},{"id":"s33-16","number":16,"surah":33,"verses":[11],"references":[{"surah":33,"verses":[11]}],"verseLabel":"الأحزاب: 11","question":"لماذا أُشير إلى موقف الابتلاء بقوله: ﴿هُنَالِكَ﴾؟","answer":"لأن اسم الإشارة البعيد يستحضر لحظة الخطر كأنها موضع بعيد في هولها وشدتها؛ فيفصلها عن الأحوال العادية ويجعلها نقطة الاختبار التي ظهر فيها صدق المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص594، تحت عنوان «نكتة الإشارة باسم الإشارة البعيد ﴿هنالك﴾»","url":""}]},{"id":"s33-67","number":67,"surah":33,"verses":[11],"references":[{"surah":33,"verses":[11]}],"verseLabel":"الأحزاب: 11","question":"ما الصورة التي ترسمها كلمة ﴿زُلْزِلُوا﴾ للمؤمنين؟","answer":"تشبه اضطراب نفوسهم باضطراب الأرض في الزلزال؛ فالشدة هزتهم هزًا عنيفًا واختبرت ثباتهم، لكنها لم تقتلع إيمانهم بل أظهرت قوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص596، تحت عنوان «بلاغة الاستعارة: ﴿وزلزلوا﴾»","url":""}]},{"id":"s33-17","number":17,"surah":33,"verses":[12],"references":[{"surah":33,"verses":[12]}],"verseLabel":"الأحزاب: 12","question":"ماذا يكشف وصف المنافقين وعد الله ورسوله بأنه ﴿غُرُورًا﴾؟","answer":"يكشف مرض قلوبهم؛ فقد قلبوا وعد النصر الصادق إلى وهم وخديعة، لا لخفاء الدليل بل لسوء ظنهم، وأرادوا بهذا القول إدخال الشك في قلوب المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص605، تحت عنوان «دلالة التعبير بلفظ الغرور»","url":""}]},{"id":"s33-18","number":18,"surah":33,"verses":[13],"references":[{"surah":33,"verses":[13]}],"verseLabel":"الأحزاب: 13","question":"لماذا نادى المنافقون قومهم بـ﴿يَا أَهْلَ يَثْرِبَ﴾، ولم يقولوا: يا أهل المدينة؟","answer":"لاستثارة رابطة الموطن القديمة وصرفهم إلى بيوتهم، ولأن ترك الاسم الذي سماها به النبي ﷺ يحمل إظهارًا لعداوتهم ودعوة إلى التخلي عن الدين والعودة إلى العصبية المكانية.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص614، تحت عنوان «نكتة ذكرهم ﴿يثرب﴾ دون المدينة»","url":""}]},{"id":"s33-19","number":19,"surah":33,"verses":[13],"references":[{"surah":33,"verses":[13]}],"verseLabel":"الأحزاب: 13","question":"ما الذي يكشفه القصر في قوله: ﴿إِنْ يُرِيدُونَ إِلَّا فِرَارًا﴾؟","answer":"يسقط عذرهم بأن البيوت مكشوفة، ويحصر دافعهم الحقيقي في الهرب؛ فبعد نفي الخطر الخارجي كشف القرآن الإرادة الداخلية التي حاولوا سترها.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص621، تحت عنوان «بلاغة القصر في قوله: ﴿إن يريدون إلا فرارًا﴾»","url":""}]},{"id":"s33-20","number":20,"surah":33,"verses":[15],"references":[{"surah":33,"verses":[15]}],"verseLabel":"الأحزاب: 15","question":"كيف يكون العهد ﴿مَسْئُولًا﴾؟","answer":"هو كناية عن أن صاحبه سيُسأل عن وفائه به ويحاسب عليه؛ فكأن العهد نفسه حاضر يطالب بحقه، وبذلك يتحول الفرار من ضعف عابر إلى نقض مسؤول لوعد قُطع لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص640، تحت عنوان «بلاغة الكناية في قوله: ﴿مسؤولًا﴾»","url":""}]},{"id":"s33-21","number":21,"surah":33,"verses":[16],"references":[{"surah":33,"verses":[16]}],"verseLabel":"الأحزاب: 16","question":"لماذا جُمع بين ﴿الْمَوْتِ﴾ و﴿الْقَتْلِ﴾ في نفي فائدة الفرار؟","answer":"لاستيعاب الطريقين اللذين يخشاهما الفار: انتهاء الأجل بلا قتال أو القتل في المعركة؛ فالفرار لا يدفع الموت المقدر، ولا يضمن النجاة من القتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص648–649، تحت عنوان «دلالة تعريف لفظي الموت والقتل»","url":""}]},{"id":"s33-22","number":22,"surah":33,"verses":[18],"references":[{"surah":33,"verses":[18]}],"verseLabel":"الأحزاب: 18","question":"هل تفيد ﴿قَدْ﴾ في قوله: ﴿قَدْ يَعْلَمُ اللَّهُ الْمُعَوِّقِينَ﴾ احتمال العلم؟","answer":"لا؛ فهي هنا للتحقيق والتوكيد، أي إن الله يعلمهم علمًا ثابتًا محيطًا بخفاياهم، وفي اختيارها تهديد وتحذير لا تردد ولا احتمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص671–672، تحت عنوان «دلالة دخول ﴿قد﴾ على الفعل المضارع»","url":""}]},{"id":"s33-68","number":68,"surah":33,"verses":[18],"references":[{"surah":33,"verses":[18]}],"verseLabel":"الأحزاب: 18","question":"ماذا تكشف تسميتهم بـ﴿الْمُعَوِّقِينَ﴾؟","answer":"تكشف أنهم لم يكتفوا بالتخلف عن النصرة، بل كانوا يثبطون غيرهم ويصرفونهم عن الجهاد؛ فاللفظة تصور نفوسًا ملتوية تجعل من قعودها حاجزًا أمام الآخرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص674، تحت عنوان «بلاغة استعمال مفردة ﴿المعوقين﴾»","url":""}]},{"id":"s33-23","number":23,"surah":33,"verses":[19],"references":[{"surah":33,"verses":[19]}],"verseLabel":"الأحزاب: 19","question":"ما الذي يصوره تشبيه أعين المنافقين بأعين المغشي عليه من الموت؟","answer":"يصور خوفًا يبلغ حد الاحتضار؛ تدور أعينهم مضطربة ولا تثبت على جهة، كأن الموت قد غشيهم، فيفضح التشبيه جبنهم وفراغ قلوبهم حين يحضر الخطر.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص693، تحت عنوان «بلاغة التشبيه»","url":""}]},{"id":"s33-24","number":24,"surah":33,"verses":[20],"references":[{"surah":33,"verses":[20]}],"verseLabel":"الأحزاب: 20","question":"ماذا يكشف قوله عن المنافقين بعد انصراف الأحزاب: ﴿يَحْسَبُونَ الْأَحْزَابَ لَمْ يَذْهَبُوا﴾؟","answer":"يكشف أن الرعب استقر في نفوسهم حتى صار الوهم أقوى من المشاهدة؛ فالجيش رحل، لكن عقولهم ظلت تعيد الخطر وتحسبه حاضرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص715–716، تحت عنوان «نكتة استعمال مفردة ﴿يحسبون﴾»","url":""}]},{"id":"s33-25","number":25,"surah":33,"verses":[21],"references":[{"surah":33,"verses":[21]}],"verseLabel":"الأحزاب: 21","question":"لماذا جاءت آية القدوة: ﴿لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ﴾ في سياق الخوف من الأحزاب؟","answer":"لأن ثبات الرسول ﷺ ومباشرته الشدة كانا جوابًا عمليًا على أعذار المتخلفين؛ فالقدوة هنا ليست موعظة مجردة، بل موقفًا مشهودًا يبين كيف يواجه المؤمن البلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص730، تحت عنوان «علة فصل الآية عما قبلها»","url":""}]},{"id":"s33-26","number":26,"surah":33,"verses":[22],"references":[{"surah":33,"verses":[22]}],"verseLabel":"الأحزاب: 22","question":"لماذا قيل: ﴿وَلَمَّا رَأَى الْمُؤْمِنُونَ الْأَحْزَابَ﴾، لا: لما جاء الأحزاب؟","answer":"لأن مجرد رؤيتهم كانت كافية لاستحضار وعد الله واليقين به؛ فلم ينتظر المؤمنون انقضاء المعركة حتى يصدقوا، بل بادروا عند المشاهدة إلى إعلان الثقة والتسليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص744، تحت عنوان «بلاغة التعبير برؤية الأحزاب لا مجيئهم»","url":""}]},{"id":"s33-27","number":27,"surah":33,"verses":[23],"references":[{"surah":33,"verses":[23]}],"verseLabel":"الأحزاب: 23","question":"ماذا يضيف وصف المؤمنين بأنهم ﴿صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ﴾؟","answer":"يجعل الصدق مطابقةً بين القول والواقع؛ فلم يبق عهدهم وعدًا باللسان، بل صدقته مواقفهم وثباتهم وما بذلوه في الجهاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص757، تحت عنوان «دلالة الوصف بالصدق»","url":""}]},{"id":"s33-69","number":69,"surah":33,"verses":[23],"references":[{"surah":33,"verses":[23]}],"verseLabel":"الأحزاب: 23","question":"ما دلالة قول الله عن بعض المؤمنين: ﴿فَمِنْهُمْ مَنْ قَضَى نَحْبَهُ﴾؟","answer":"النحب هو العهد الذي التزموه، ويُطلق أيضًا على الموت؛ فالتعبير يصور من وفّى بعهد الله حتى استُشهد أو مات ثابتًا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص762، تحت عنوان «دلالة التعبير بـ﴿نحبه﴾»","url":""}]},{"id":"s33-70","number":70,"surah":33,"verses":[23],"references":[{"surah":33,"verses":[23]}],"verseLabel":"الأحزاب: 23","question":"لماذا وُصف بقية المؤمنين بأن منهم ﴿مَنْ يَنْتَظِرُ﴾؟","answer":"لأنهم ظلوا ثابتين على العهد يترقبون تمام الوفاء به: إما الشهادة وإما مواصلة الجهاد والعمل الصالح، من غير تبديل ولا تراجع.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص764، تحت عنوان «دلالة التعبير بالانتظار»","url":""}]},{"id":"s33-28","number":28,"surah":33,"verses":[25],"references":[{"surah":33,"verses":[25]}],"verseLabel":"الأحزاب: 25","question":"ما الذي يصوره قوله: ﴿وَرَدَّ اللَّهُ الَّذِينَ كَفَرُوا بِغَيْظِهِمْ﴾؟","answer":"تصور الباء الغيظ مصاحبًا لهم في رجوعهم؛ عادوا خائبين يحملون غضبهم كما هو، بعدما بذلوا أموالهم وجهدهم ولم يحققوا مرادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص788، تحت عنوان «دلالة الباء في قوله: ﴿بغيظهم﴾»","url":""}]},{"id":"s33-71","number":71,"surah":33,"verses":[25],"references":[{"surah":33,"verses":[25]}],"verseLabel":"الأحزاب: 25","question":"لماذا نُكِّر ﴿خَيْرًا﴾ في قوله: ﴿لَمْ يَنَالُوا خَيْرًا﴾؟","answer":"لإفادة العموم: لم يصيبوا أي نفع يُعتد به، لا نصرًا ولا غنيمة ولا مكسبًا من أمر الدين أو الدنيا، فكان رجوعهم خيبة خالصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص790، تحت عنوان «بلاغة التنكير في: ﴿خيرًا﴾»","url":""}]},{"id":"s33-29","number":29,"surah":33,"verses":[25],"references":[{"surah":33,"verses":[25]}],"verseLabel":"الأحزاب: 25","question":"ما سر التعبير بـ﴿وَكَفَى اللَّهُ الْمُؤْمِنِينَ الْقِتَالَ﴾؟","answer":"لأن الله أغناهم عن مباشرة القتال العام بما أرسل على الأحزاب من الريح والجنود؛ فنُسبت الكفاية إليه وحده ليظهر أن النصر كان بتدبيره لا بكثرة المؤمنين وقوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص791، تحت عنوان «سر التعبير بالكفاية في الآية»","url":""}]},{"id":"s33-30","number":30,"surah":33,"verses":[26],"references":[{"surah":33,"verses":[26]}],"verseLabel":"الأحزاب: 26","question":"لماذا قيل: ﴿وَقَذَفَ فِي قُلُوبِهِمُ الرُّعْبَ﴾ بدل: ألقى؟","answer":"لأن القذف يوحي بقوة الإلقاء وشدته وسرعته؛ فيصور رعبًا داهم قلوبهم وتمكن منها حتى كأنه شيء صُب فيها صبًا عنيفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص14، تحت عنوان «سر التعبير بالقذف بدل الإلقاء»","url":""}]},{"id":"s33-72","number":72,"surah":33,"verses":[26],"references":[{"surah":33,"verses":[26]}],"verseLabel":"الأحزاب: 26","question":"لماذا قُدِّم قذف الرعب في قلوبهم على إنزالهم من حصونهم؟","answer":"لأن الرعب كان السبب في نزولهم، لكن قُدِّم الأهم للمؤمنين والأشد أثرًا: تسليط الله الخوف على عدوهم؛ ثم ذُكر ما ترتب عليه من إخراجهم من حصونهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص15، تحت عنوان «نكتة تقديم المسبب على السبب»","url":""}]},{"id":"s33-31","number":31,"surah":33,"verses":[28],"references":[{"surah":33,"verses":[28]}],"verseLabel":"الأحزاب: 28","question":"لماذا خيّر النبي ﷺ أزواجه بين متاع الدنيا وبين الله ورسوله والدار الآخرة؟","answer":"لأنهن طلبن التوسع في النفقة بعد الفتح، فأُمر أن يكشف لهن طبيعة بيت النبوة: من اختارت المقام معه تختار رسالته وما يلزمها من الزهد والصبر، وقد اخترن الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص31، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s33-73","number":73,"surah":33,"verses":[28],"references":[{"surah":33,"verses":[28]}],"verseLabel":"الأحزاب: 28","question":"لماذا قُدّم خيار الدنيا في تخيير أزواج النبي ﷺ وجُرّد من الوعيد؟","answer":"ليكون التخيير حقيقيًا وتظهر إرادتهن من غير إكراه أو تخويف؛ عُرض لهن مفارقة البيت بإحسان إن أردن الدنيا، فبان فضل اختيارهن الله ورسوله والآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص51، تحت عنوان «سر تقديم الجملة الشرطية الأولى وتجريدها من الوعيد»","url":""}]},{"id":"s33-32","number":32,"surah":33,"verses":[30,31],"references":[{"surah":33,"verses":[30,31]}],"verseLabel":"الأحزاب: 30-31","question":"لماذا يُضاعف العذاب لمن تأتي بفاحشة من أزواج النبي ﷺ؟","answer":"لأن قربهن من الوحي وعلو منزلتهن وكثرة ما بلغهن من العلم يجعل المعصية منهن أشد قبحًا وأعظم أثرًا في الاقتداء؛ فكما تضاعف الشرف تضاعف المسؤولية.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص59–60، تحت عنوان «دلالة التعبير بالمضاعفة في الآية»","url":""}]},{"id":"s33-74","number":74,"surah":33,"verses":[30,31],"references":[{"surah":33,"verses":[30,31]}],"verseLabel":"الأحزاب: 30-31","question":"ما سر قوله لأزواج النبي ﷺ: ﴿نُؤْتِهَا أَجْرَهَا مَرَّتَيْنِ﴾؟","answer":"ليس المراد إعطاء الأجر نفسه في وقتين، بل تضعيفه؛ فلها مثل أجر غيرها على الطاعة ومثله زيادةً لشرف مقامها وثباتها على تكاليف بيت النبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص76، تحت عنوان «سر إيثار لفظ المرة في قوله: ﴿مرتين﴾»","url":""}]},{"id":"s33-33","number":33,"surah":33,"verses":[31],"references":[{"surah":33,"verses":[31]}],"verseLabel":"الأحزاب: 31","question":"ما دلالة مراعاة لفظ ﴿من﴾ ومعناها في قوله ﴿ومن يقنت منكن﴾ و﴿وتعمل صالحًا﴾؟","answer":"رُوعي لفظ ﴿من﴾ في التذكير والإفراد في ﴿يقنت﴾، ورُوعي معناها الدال على النساء في قراءة ﴿وتعمل﴾ بالتاء. وقرئت ﴿ويعمل﴾ بالياء حملًا على لفظ ﴿من﴾ أيضًا؛ فاختلاف الصيغة راجع إلى مراعاة اللفظ أو المعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص72، تحت عنوان «توجيه القراءات في ﴿وتعمل﴾»","url":""}]},{"id":"s33-34","number":34,"surah":33,"verses":[32],"references":[{"surah":33,"verses":[32]}],"verseLabel":"الأحزاب: 32","question":"ما دلالة قوله لأمهات المؤمنين: ﴿لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ﴾؟","answer":"ينفي مماثلتهن لغيرهن في الفضل والمسؤولية؛ فقربهن من النبي ﷺ واطلاعهن على شؤونه جعلا لهن منزلة خاصة تقتضي قيامًا يليق بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص90، تحت عنوان «بلاغة نفي التشبيه»","url":""}]},{"id":"s33-75","number":75,"surah":33,"verses":[32],"references":[{"surah":33,"verses":[32]}],"verseLabel":"الأحزاب: 32","question":"لماذا قُيّد تميز أمهات المؤمنين بقوله: ﴿إِنِ اتَّقَيْتُنَّ﴾؟","answer":"ليبين أن شرف الصلة بالنبي ﷺ لا يغني وحده؛ إنما يثبت هذا الفضل باستمرار التقوى والطاعة، وفي الشرط حث لهن على دوام الازدياد منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص91–92، تحت عنوان «بلاغة التقييد بقوله ﴿إن اتقيتن﴾»","url":""}]},{"id":"s33-35","number":35,"surah":33,"verses":[32],"references":[{"surah":33,"verses":[32]}],"verseLabel":"الأحزاب: 32","question":"لماذا نُهيت أمهات المؤمنين عن الخضوع بالقول لا عن أصل الكلام؟","answer":"لأن الممنوع هو تليين الصوت وترقيقه على هيئة تثير طمع صاحب القلب المريض، لا الكلام الحسن نفسه؛ فالنهي يصون الخطاب من الإغراء مع بقاء الحاجة إلى التخاطب.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص94–95، تحت عنوان «دلالة النهي عن الخضوع في القول»","url":""}]},{"id":"s33-76","number":76,"surah":33,"verses":[32],"references":[{"surah":33,"verses":[32]}],"verseLabel":"الأحزاب: 32","question":"لماذا أعقب النهي عن الخضوع بالقول الأمر بقوله: ﴿وَقُلْنَ قَوْلًا مَعْرُوفًا﴾؟","answer":"احتراسًا من أن يُفهم النهي دعوةً إلى الصمت أو الجفاء؛ فالمطلوب كلام معروف حسن عند الحاجة، واضح وجاد وخال من التليين المريب.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص100، تحت عنوان «بلاغة الاحتراس في عطف جملة الفاصلة»","url":""}]},{"id":"s33-36","number":36,"surah":33,"verses":[32],"references":[{"surah":33,"verses":[32]}],"verseLabel":"الأحزاب: 32","question":"ما سرّ استعمال ﴿أَحَدٍ﴾ في ﴿لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ﴾؟","answer":"لفظ ﴿أحد﴾ في سياق النفي يفيد العموم، فيصح للمذكر والمؤنث والواحد والجماعة؛ لذلك كان أوسع دلالة في نفي المماثلة من لفظ ﴿واحد﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص91، تحت عنوان «سر نفي لفظ (أحد) دون (واحد)»","url":""}]},{"id":"s33-37","number":37,"surah":33,"verses":[33],"references":[{"surah":33,"verses":[33]}],"verseLabel":"الأحزاب: 33","question":"ما الذي يقتضيه الأمر لأمهات المؤمنين: ﴿وَقَرْنَ فِي بُيُوتِكُنَّ﴾؟","answer":"يقتضي ملازمة البيوت على جهة القرار والوقار، مع جواز الخروج لحاجة مشروعة؛ فليس المقصود حبسًا مطلقًا، بل جعل البيت أصلًا يصون مكانتهن ويوافق مسؤولية بيت النبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص108، تحت عنوان «دلالة الأمر في ﴿وقرن﴾»","url":""}]},{"id":"s33-38","number":38,"surah":33,"verses":[33],"references":[{"surah":33,"verses":[33]}],"verseLabel":"الأحزاب: 33","question":"لماذا انتقل الخطاب في آية التطهير من ضمائر النساء إلى ضمير الجمع المذكر؟","answer":"لأن الخطاب اتسع فدخل فيه النبي ﷺ مع أهل بيته، ولأن لفظ ﴿أهل﴾ يراعى فيه التذكير، كما يصح تغليب المذكر عند اجتماع الرجال والنساء؛ فلا يدل الانتقال وحده على إخراج الزوجات من السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص131–132، تحت عنوان «عود ضميري الخطاب في ﴿عنكم﴾ و﴿ويطهركم﴾»","url":""}]},{"id":"s33-39","number":39,"surah":33,"verses":[35],"references":[{"surah":33,"verses":[35]}],"verseLabel":"الأحزاب: 35","question":"لماذا صُرّح بالرجال والنساء في أوصاف آية: ﴿إِنَّ الْمُسْلِمِينَ وَالْمُسْلِمَاتِ﴾؟","answer":"لإزالة أي توهم بأن الفضل والوعد خاصان بالرجال؛ فالتصريح يقرر اشتراك الجنسين في التكليف وفي المغفرة والأجر، ويؤكد أن طريق القرب مفتوح لهما بالأعمال نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص156، تحت عنوان «بلاغة التسوية في ذكر الأوصاف»","url":""}]},{"id":"s33-40","number":40,"surah":33,"verses":[36],"references":[{"surah":33,"verses":[36]}],"verseLabel":"الأحزاب: 36","question":"لماذا صُرّح بـ﴿مُؤْمِنَةٍ﴾ بعد ﴿مُؤْمِنٍ﴾ في قوله: ﴿وَمَا كَانَ لِمُؤْمِنٍ وَلَا مُؤْمِنَةٍ﴾؟","answer":"ليدخل الرجال والنساء في الحكم دخولًا صريحًا، ولا يُتوهم أن الخطاب بالتغليب خاص بالرجال؛ فليس لأحد منهما اختيار يعارض قضاء الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص178، تحت عنوان «نكتة عطف لفظ ﴿مؤمنة﴾ على ﴿لمؤمن﴾»","url":""}]},{"id":"s33-77","number":77,"surah":33,"verses":[36],"references":[{"surah":33,"verses":[36]}],"verseLabel":"الأحزاب: 36","question":"لماذا عبّر عن الاختيار المخالف لقضاء الله ورسوله بلفظ ﴿الْخِيَرَةُ﴾؟","answer":"لأن الخيرة اسم لمصدر الاختيار، فنفى أن يبقى للمؤمن بعد حكم الله ورسوله مجال ينتقي فيه رأيًا آخر؛ وهذا أبلغ من مجرد النهي، إذ يقرر أن المخالفة ليست خيارًا مشروعًا أصلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص182، تحت عنوان «دلالة إيثار لفظ ﴿الخيرة﴾ على المعصية»","url":""}]},{"id":"s33-41","number":41,"surah":33,"verses":[37],"references":[{"surah":33,"verses":[37]}],"verseLabel":"الأحزاب: 37","question":"ما الذي كان النبي ﷺ يخفيه في نفسه في قوله: ﴿وَتُخْفِي فِي نَفْسِكَ﴾؟","answer":"كان يخفي ما أعلمه الله به من أنه سيتزوج زينب بعد زيد، لا ميلًا محرمًا؛ وأبرز قيد ﴿في نفسك﴾ شدة كتمان هذا الأمر الحساس حتى لم يطلع عليه أحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص201، تحت عنوان «دلالة قيد ﴿في نفسك﴾»","url":""}]},{"id":"s33-78","number":78,"surah":33,"verses":[37],"references":[{"surah":33,"verses":[37]}],"verseLabel":"الأحزاب: 37","question":"لماذا قيل عما أخفاه النبي ﷺ: ﴿مَا اللَّهُ مُبْدِيهِ﴾؟","answer":"لأن الله سيُظهر هذا الزواج إظهارًا بيّنًا ليبطل حكم التبني عمليًا؛ وصيغة ﴿مبديه﴾ تؤكد أن إعلانه واقع لا محالة، وإن كره المنافقون.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص202، تحت عنوان «دلالة اختيار لفظ ﴿مبديه﴾ مادة وصيغة»","url":""}]},{"id":"s33-79","number":79,"surah":33,"verses":[37],"references":[{"surah":33,"verses":[37]}],"verseLabel":"الأحزاب: 37","question":"ما دلالة وصف موقف النبي ﷺ من كلام الناس بلفظ ﴿الخشية﴾؟","answer":"الخشية خوف تصحبه معرفة وتعظيم للعاقبة؛ فكان ﷺ يكره ما سيثيره المنافقون من طعن وتشكيك، لا أنه جبن عن تنفيذ أمر الله، فجاء العتاب ليقدّم بيان الشرع على مقالة الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص202–203، تحت عنوان «توجيه استعمال لفظ (الخشية) مادة وصيغة»","url":""}]},{"id":"s33-42","number":42,"surah":33,"verses":[37],"references":[{"surah":33,"verses":[37]}],"verseLabel":"الأحزاب: 37","question":"لماذا أسند الله تزويج زينب للنبي ﷺ إلى نفسه في قوله: ﴿زَوَّجْنَاكَهَا﴾؟","answer":"لتعظيم هذا الزواج وبيان أنه وقع بأمر الله المباشر لتحقيق غاية تشريعية، لا باختيار شخصي مجرد؛ وفي الإسناد تشريف وإبطال لما بقي من آثار التبني.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص207، تحت عنوان «نكتة إسناد فعل التزويج إلى ضمير التعظيم»","url":""}]},{"id":"s33-80","number":80,"surah":33,"verses":[37],"references":[{"surah":33,"verses":[37]}],"verseLabel":"الأحزاب: 37","question":"ما الغاية التي يكشفها التعليل بـ﴿لِكَيْ لَا يَكُونَ عَلَى الْمُؤْمِنِينَ حَرَجٌ﴾؟","answer":"يكشف أن الزواج كان تشريعًا عمليًا يرفع الحرج عن المؤمنين في الزواج بمطلقات أدعيائهم بعد انتهاء العلاقة الزوجية، فينهدم بذلك حكم التبني الجاهلي.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص208–209، تحت عنوان «بلاغة التعليل في ﴿لكي﴾»","url":""}]},{"id":"s33-43","number":43,"surah":33,"verses":[40],"references":[{"surah":33,"verses":[40]}],"verseLabel":"الأحزاب: 40","question":"لماذا قيل: ﴿مَا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ﴾ ولم يقل: والد أحد؟","answer":"لأن الأبوة أوسع من الولادة؛ فقد تكون حقيقية أو مجازية بالتبني والرعاية. فنفى لفظ ﴿أبا﴾ كل أبوة تترتب عليها أحكام البنوة، وبذلك دخل زيد وغيره في النفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص237–238، تحت عنوان «نكتة إيثار لفظ ﴿أبا﴾ على والد»","url":""}]},{"id":"s33-81","number":81,"surah":33,"verses":[40],"references":[{"surah":33,"verses":[40]}],"verseLabel":"الأحزاب: 40","question":"لماذا استُدرك بعد نفي أبوة النبي ﷺ بقوله: ﴿وَلَكِنْ رَسُولَ اللَّهِ﴾؟","answer":"لئلا يُفهم نفي الأبوة انتقاصًا لمكانته أو قطعًا لصلته بالأمة؛ فنفى الأبوة التي توجب أحكام النسب، ثم أثبت الرسالة التي توجب الطاعة والتوقير والرحمة والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص239–240، تحت عنوان «دلالة الاستدراك وفائدته»","url":""}]},{"id":"s33-44","number":44,"surah":33,"verses":[40],"references":[{"surah":33,"verses":[40]}],"verseLabel":"الأحزاب: 40","question":"ما الذي تضيفه كلمة ﴿خَاتَمَ﴾ في وصف النبي ﷺ؟","answer":"تفيد أنه آخر الأنبياء وأن سلسلة النبوة خُتمت به، كما يختم الخاتم الشيء ويتممه؛ فلا نبي بعده، وقد اكتمل به بناء الرسالات.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص241–242، تحت عنوان «نكتة اختيار مفردة ﴿خاتم﴾»","url":""}]},{"id":"s33-82","number":82,"surah":33,"verses":[40],"references":[{"surah":33,"verses":[40]}],"verseLabel":"الأحزاب: 40","question":"لماذا قيل: ﴿خَاتَمَ النَّبِيِّينَ﴾ لا: خاتم المرسلين؟","answer":"لأن نفي النبوة بعده أعم وأحسم؛ فكل رسول نبي، فإذا انتفى مجيء نبي بعده انتفى من باب أولى مجيء رسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص242، تحت عنوان «اختيار لفظ ﴿النبيين﴾»","url":""}]},{"id":"s33-45","number":45,"surah":33,"verses":[41,42],"references":[{"surah":33,"verses":[41,42]}],"verseLabel":"الأحزاب: 41-42","question":"لماذا وُصف الذكر في قوله: ﴿اذْكُرُوا اللَّهَ ذِكْرًا كَثِيرًا﴾ بالكثرة؟","answer":"ليستغرق الذكر أوقات المؤمن وأحواله، فيبقى القلب حاضرًا مع الله ولا يكون الذكر كلمة عابرة باللسان؛ فالكثرة علامة دوام وإخلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص251، تحت عنوان «فائدة وصف الذكر بالكثرة»","url":""}]},{"id":"s33-83","number":83,"surah":33,"verses":[41,42],"references":[{"surah":33,"verses":[41,42]}],"verseLabel":"الأحزاب: 41-42","question":"لماذا أُمر بالتسبيح بعد الأمر العام بذكر الله؟","answer":"لأن التسبيح من أجلّ أنواع الذكر، فخُص بعد العموم تنبيهًا إلى فضله وعنايةً بتنزيه الله عن كل نقص، ولا سيما عما يقوله أهل النفاق والافتراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص251–252، تحت عنوان «دلالة الأمر بالتسبيح بعد الأمر بالذكر»","url":""}]},{"id":"s33-46","number":46,"surah":33,"verses":[43],"references":[{"surah":33,"verses":[43]}],"verseLabel":"الأحزاب: 43","question":"كيف تُنسب الصلاة إلى الله وملائكته مع اختلاف معناها؟","answer":"صلاة الله رحمته وعنايته بالمؤمنين، وصلاة الملائكة دعاؤهم واستغفارهم لهم؛ جمعهما لفظ واحد لاشتراكهما في إيصال الخير والعناية إلى المؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص258، تحت عنوان «بلاغة استعمال المشترك اللفظي»","url":""}]},{"id":"s33-47","number":47,"surah":33,"verses":[45,46],"references":[{"surah":33,"verses":[45,46]}],"verseLabel":"الأحزاب: 45-46","question":"لماذا اقتُصر في الآية على خمسة أوصاف للنبي ﷺ؟","answer":"لأنها تجمع أصول مهمته الرسالية: الشهادة والتبشير والإنذار والدعوة والبيان المنير؛ فما سواها من أوصافه يرجع إلى هذه المجامع أو يخدمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص293، تحت عنوان «نكتة الاقتصار على الأوصاف الخمسة»","url":""}]},{"id":"s33-48","number":48,"surah":33,"verses":[46],"references":[{"surah":33,"verses":[46]}],"verseLabel":"الأحزاب: 46","question":"ما الصورة التي يرسمها وصف النبي ﷺ بأنه ﴿سِرَاجًا﴾؟","answer":"يشبهه بالسراج الذي يكشف الظلمة؛ فما جاء به من الوحي يبدد ظلمات الجهل والضلال ويهدي الحائرين إلى طريق الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص291، تحت عنوان «بلاغة التشبيه بالسراج»","url":""}]},{"id":"s33-84","number":84,"surah":33,"verses":[46],"references":[{"surah":33,"verses":[46]}],"verseLabel":"الأحزاب: 46","question":"ماذا يضيف وصف السراج بأنه ﴿مُنِيرًا﴾؟","answer":"يؤكد ظهور أثر هدايته وانتشار نوره، ويدفع ما قد يتوهم في السراج الحسي من احتراق أو أذى؛ فهو نور هداية ينتفع به الناس ولا يضرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص292، تحت عنوان «فائدة الوصف بالمنير»","url":""}]},{"id":"s33-49","number":49,"surah":33,"verses":[49],"references":[{"surah":33,"verses":[49]}],"verseLabel":"الأحزاب: 49","question":"ماذا يفيد التعبير الاسمي في قوله: ﴿فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا﴾؟","answer":"يفيد ثبات انتفاء العدة عن المطلقة قبل المساس؛ فليس الحكم حالة عارضة، بل نفي محكم لا يملك الزوج بعده أن يطالبها بعدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص321، تحت عنوان «سر التعبير بالجملة الاسمية»","url":""}]},{"id":"s33-50","number":50,"surah":33,"verses":[49],"references":[{"surah":33,"verses":[49]}],"verseLabel":"الأحزاب: 49","question":"لماذا أُمر بمتاع المطلقة قبل الدخول في قوله: ﴿فَمَتِّعُوهُنَّ﴾؟","answer":"لجبر خاطرها وتعويضها عن ألم الفراق، ولا سيما أنها تفارق قبل اكتمال الحياة الزوجية؛ فالمتعة إحسان مادي ومعنوي يحفظ الكرامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص325، تحت عنوان «دلالة الأمر ﴿فمتعوهن﴾»","url":""}]},{"id":"s33-85","number":85,"surah":33,"verses":[49],"references":[{"surah":33,"verses":[49]}],"verseLabel":"الأحزاب: 49","question":"لماذا عُطف على المتعة قوله: ﴿وَسَرِّحُوهُنَّ سَرَاحًا جَمِيلًا﴾؟","answer":"ليجمع الانفصال بين العطاء وحسن المعاملة؛ فليس المقصود دفع مال ثم الإضرار، بل إنهاء العلاقة بلا انتقام ولا أذى، مع بقاء المعروف والكرامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص326، تحت عنوان «فائدة عطف الأمر بالتسريح»","url":""}]},{"id":"s33-51","number":51,"surah":33,"verses":[53],"references":[{"surah":33,"verses":[53]}],"verseLabel":"الأحزاب: 53","question":"لماذا نُهي ضيوف بيت النبي ﷺ عن انتظار نضج الطعام في بيته؟","answer":"لأن التبكير قبل إعداد الطعام يطيل المكث ويثقل على أهل البيت؛ فجمع القيد بين أدب الإذن وأدب الوقت وأدب الدعوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص396، تحت عنوان «سر التقييد بالحال ﴿غير ناظرين إناه﴾»","url":""}]},{"id":"s33-86","number":86,"surah":33,"verses":[53],"references":[{"surah":33,"verses":[53]}],"verseLabel":"الأحزاب: 53","question":"ماذا يفيد الأمر ﴿فَانْتَشِرُوا﴾ بعد الفراغ من الطعام؟","answer":"يفيد الانصراف من غير إبطاء أو جلسة طويلة؛ فالانتشار خروج سريع متفرق يرفع الحرج عن النبي ﷺ وأهل بيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص399، تحت عنوان «معنى (الفاء) ودلالتها في: ﴿فانتشروا﴾»","url":""}]},{"id":"s33-87","number":87,"surah":33,"verses":[53],"references":[{"surah":33,"verses":[53]}],"verseLabel":"الأحزاب: 53","question":"لماذا قُيّد سؤال أزواج النبي ﷺ بقوله: ﴿مِنْ وَرَاءِ حِجَابٍ﴾؟","answer":"لتوفير الاحترام لبيت النبوة وصيانة أمهات المؤمنين، مع إبقاء السؤال والحاجة ممكنين؛ فالحجاب ينظم التواصل ولا يقطعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص408، تحت عنوان «سر تقييد: ﴿فسئلوهن﴾ بـ ﴿من وراء حجاب﴾»","url":""}]},{"id":"s33-88","number":88,"surah":33,"verses":[53],"references":[{"surah":33,"verses":[53]}],"verseLabel":"الأحزاب: 53","question":"لماذا وُصف سؤال أزواج النبي ﷺ من وراء حجاب بأنه ﴿أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ﴾؟","answer":"لأن الحجاب يسد ذرائع الفتنة ويصون خواطر الطرفين، فيزيد القلوب طهارة ويحفظ حرمة بيت النبي ﷺ وكرامة أزواجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص409، تحت عنوان «دلالة التعبير بالطهر في الخبر ﴿أطهر﴾»","url":""}]},{"id":"s33-52","number":52,"surah":33,"verses":[53],"references":[{"surah":33,"verses":[53]}],"verseLabel":"الأحزاب: 53","question":"كيف نُسب الاستحياء إلى الله في قوله: ﴿وَاللَّهُ لَا يَسْتَحْيِي مِنَ الْحَقِّ﴾؟","answer":"جاء اللفظ مشاكلةً لحياء النبي ﷺ المذكور قبله، لكن استحياء الله ليس كحياء البشر؛ والمعنى أنه سبحانه لا يترك بيان الحق ولا يمنعه مانع من إظهاره.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص404، تحت عنوان «بلاغة المشاكلة في الآية»","url":""}]},{"id":"s33-53","number":53,"surah":33,"verses":[56],"references":[{"surah":33,"verses":[56]}],"verseLabel":"الأحزاب: 56","question":"لماذا أُمر المؤمنون بالصلاة على النبي ﷺ بعد ذكر صلاة الله وملائكته عليه؟","answer":"ليس لحاجته إلى صلاتهم بعد كرامة الله وملائكته، بل ليظهروا تعظيمه ويؤدوا حقه عليهم، وليكرمهم الله بالمشاركة في هذا الذكر الشريف.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص452، تحت عنوان «نكتة أمر المؤمنين بالصلاة على النبي»","url":""}]},{"id":"s33-89","number":89,"surah":33,"verses":[56],"references":[{"surah":33,"verses":[56]}],"verseLabel":"الأحزاب: 56","question":"لماذا جُمع للمؤمنين بين الصلاة على النبي ﷺ والتسليم عليه؟","answer":"لأن كمال توقيره يجمع الدعاء له بالرفعة والخير مع السلام الذي يتضمن الأمان والتحية والانقياد؛ فلا يكتفى بأحد جانبي التعظيم دون الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص453، تحت عنوان «معنى الواو في قوله: ﴿وسلموا﴾»","url":""}]},{"id":"s33-54","number":54,"surah":33,"verses":[57],"references":[{"surah":33,"verses":[57]}],"verseLabel":"الأحزاب: 57","question":"كيف يُنسب الأذى إلى الله في قوله: ﴿إِنَّ الَّذِينَ يُؤْذُونَ اللَّهَ﴾؟","answer":"لا يلحق الله ضرر، وإنما الأذى فعل ما يكرهه من الكفر وإنكار رسله ومخالفة شرعه؛ فنُسب إليه تشنيعًا للفعل وتعظيمًا لحرمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص459–460، تحت عنوان «بلاغة إيقاع الإيذاء على الله»","url":""}]},{"id":"s33-90","number":90,"surah":33,"verses":[57],"references":[{"surah":33,"verses":[57]}],"verseLabel":"الأحزاب: 57","question":"ماذا تضيف نسبة الرسول إلى الله في قوله: ﴿يُؤْذُونَ اللَّهَ وَرَسُولَهُ﴾؟","answer":"تزيد أذى الرسول ﷺ قبحًا؛ فهو رسول الله المضاف إليه تشريفًا، ومن آذاه فقد تعرض لحرمة الرسالة واستحق الوعيد والانتقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص460، تحت عنوان «بلاغة الإضافة في ﴿ورسوله﴾»","url":""}]},{"id":"s33-55","number":55,"surah":33,"verses":[58],"references":[{"surah":33,"verses":[58]}],"verseLabel":"الأحزاب: 58","question":"لماذا نُكِّر ﴿بُهْتَانًا﴾ في وصف أذى المؤمنين؟","answer":"للتفخيم والتهويل؛ فما يحملونه افتراء عظيم يبهت لشدته، وفي التنكير تخويف من فداحة الكذب على بريء.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص469، تحت عنوان «غرض تنكير ﴿بهتانًا﴾»","url":""}]},{"id":"s33-91","number":91,"surah":33,"verses":[58],"references":[{"surah":33,"verses":[58]}],"verseLabel":"الأحزاب: 58","question":"لماذا جُمع بين ﴿بُهْتَانًا﴾ و﴿إِثْمًا﴾ في أذى المؤمنين؟","answer":"لأن البهتان يصف الأذى القولي القائم على الافتراء، والإثم يعم الجرم المحرم وآثاره؛ فاجتمع وصف الكذب ووصف المعصية ليشمل قبح الاعتداء كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص469، تحت عنوان «نكتة عطف الإثم على البهتان»","url":""}]},{"id":"s33-92","number":92,"surah":33,"verses":[58],"references":[{"surah":33,"verses":[58]}],"verseLabel":"الأحزاب: 58","question":"ماذا يضيف وصف الإثم بأنه ﴿مُبِينًا﴾؟","answer":"يؤكد أن جرمه ظاهر لا شبهة فيه، حتى كأنه يكشف نفسه بنفسه؛ فلا عذر لمن يتهم بريئًا أو يؤذيه بغير ما اكتسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص469، تحت عنوان «نكتة وصف الإثم بـ﴿مبينًا﴾»","url":""}]},{"id":"s33-56","number":56,"surah":33,"verses":[59],"references":[{"surah":33,"verses":[59]}],"verseLabel":"الأحزاب: 59","question":"ماذا يفيد قوله: ﴿ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ﴾؟","answer":"يفيد أن إدناء الجلابيب أقرب وسيلة إلى حصول المعرفة المقصودة والوقاية من الأذى، لا أنه سبب حتمي مستقل؛ فلفظ ﴿أدنى﴾ يدل على الأقربية.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص479، تحت عنوان «دلالة التعبير بالدنو»","url":""}]},{"id":"s33-93","number":93,"surah":33,"verses":[59],"references":[{"surah":33,"verses":[59]}],"verseLabel":"الأحزاب: 59","question":"ما المقصود بقوله في سياقه التاريخي: ﴿أَنْ يُعْرَفْنَ فَلَا يُؤْذَيْنَ﴾؟","answer":"أن تُعرف المرأة بسمت العفة والصيانة، وفسر المبحث ذلك في مجتمع النزول بتمييز الحرائر من الإماء؛ فتكون المعرفة مانعة لأهل السوء من التعرض لهن.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص479، تحت عنوان «نكتة التعبير بقوله: ﴿يعرفن﴾»","url":""}]},{"id":"s33-57","number":57,"surah":33,"verses":[60],"references":[{"surah":33,"verses":[60]}],"verseLabel":"الأحزاب: 60","question":"هل المنافقون والذين في قلوبهم مرض والمرجفون جماعات مختلفة؟","answer":"يحتمل أن تكون أوصافًا لجماعة واحدة تعددت آفاتها، ويحتمل أن تكون أصنافًا مختلفة اجتمعت على الإفساد؛ فالعطف يستوعب الوجهين ويشمل مصادر الفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص489، تحت عنوان «نكتة عطف ﴿والذين في قلوبهم مرض والمرجفون﴾»","url":""}]},{"id":"s33-94","number":94,"surah":33,"verses":[60],"references":[{"surah":33,"verses":[60]}],"verseLabel":"الأحزاب: 60","question":"ماذا تكشف تسمية ناشري الأخبار الكاذبة بـ﴿الْمُرْجِفُونَ﴾؟","answer":"تصورهم مثيرين للرجفة والاضطراب في المجتمع بما يبثونه من أخبار مخيفة أو مسيئة؛ وصيغة الاسم تدل على أن الإرجاف صار لهم عادة راسخة.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص491، تحت عنوان «بلاغة التعبير بالإرجاف»","url":""}]},{"id":"s33-58","number":58,"surah":33,"verses":[63],"references":[{"surah":33,"verses":[63]}],"verseLabel":"الأحزاب: 63","question":"ما سرّ تذكير ﴿قَرِيبًا﴾ في قوله ﴿لَعَلَّ السَّاعَةَ تَكُونُ قَرِيبًا﴾؟","answer":"جاء ﴿قريبًا﴾ صفة لموصوف محذوف: لعل زمان قيام الساعة قريب، أو لعل الساعة تكون شيئًا قريبًا. فالتذكير يراعي هذا المحذوف، ويشير إلى أن المسؤول عنه وقت الساعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص512، تحت عنوان «سر الإشارة إلى القرب وتذكيره»","url":""}]},{"id":"s33-59","number":59,"surah":33,"verses":[66],"references":[{"surah":33,"verses":[66]}],"verseLabel":"الأحزاب: 66","question":"ما الذي تصوره صيغة ﴿تُقَلَّبُ﴾ في عذاب أهل النار؟","answer":"تصور تكرر التقليب وشدته وانتقال وجوههم من جهة إلى جهة في النار، كحال اللحم الذي تتناوبه النار حتى ينضج؛ فتضاعف رهبة المشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص524، تحت عنوان «دلالة التعبير بفعل التقليب مادة وصيغة»","url":""}]},{"id":"s33-95","number":95,"surah":33,"verses":[66],"references":[{"surah":33,"verses":[66]}],"verseLabel":"الأحزاب: 66","question":"لماذا خُصت الوجوه بالذكر في قوله: ﴿تُقَلَّبُ وُجُوهُهُمْ فِي النَّارِ﴾؟","answer":"لأن الوجه أكرم ما في الإنسان وأشرفه، فتخصيصه بالتقليب والإحراق أبلغ في الإهانة والتعذيب، مع أن النار تصيب سائر الجسد.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص524، تحت عنوان «براعة اختصاص الوجوه بالتقلب»","url":""}]},{"id":"s33-60","number":60,"surah":33,"verses":[67],"references":[{"surah":33,"verses":[67]}],"verseLabel":"الأحزاب: 67","question":"ماذا يكشف اعتراف أهل النار: ﴿إِنَّا أَطَعْنَا سَادَتَنَا وَكُبَرَاءَنَا﴾؟","answer":"يكشف أنهم سلّموا قيادهم لزعمائهم واتبعوهم في غير الحق، فصرفوهم عن سبيل الله؛ وهو اعتراف بأن الطاعة العمياء كانت سبب ضلالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص531، تحت عنوان «دلالة التعبير بلفظة الطاعة»","url":""}]},{"id":"s33-96","number":96,"surah":33,"verses":[67],"references":[{"surah":33,"verses":[67]}],"verseLabel":"الأحزاب: 67","question":"لماذا جُمع بين ﴿سَادَتَنَا﴾ و﴿كُبَرَاءَنَا﴾؟","answer":"لأن السادة أهل القيادة والتدبير، والكبراء أصحاب المنزلة والسن أو الشرف؛ فالجمع يستوعب وجوه النفوذ التي خضعوا لها ويقطع عذرهم بالتقليد.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص532، تحت عنوان «دلالة عطف الكبراء على السادة»","url":""}]},{"id":"s33-61","number":61,"surah":33,"verses":[69],"references":[{"surah":33,"verses":[69]}],"verseLabel":"الأحزاب: 69","question":"لماذا شُبّه إيذاء النبي ﷺ بإيذاء بني إسرائيل لموسى؟","answer":"لتقبيح الأذى باستحضار فعل أمة سابقة مع نبيها، وتحذير المؤمنين من أن يشابهوا المسيئين الذين كذبوا وآذوا موسى رغم وضوح براءته.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص542، تحت عنوان «غرض التشبيه ووجه بلاغته»","url":""}]},{"id":"s33-97","number":97,"surah":33,"verses":[69],"references":[{"surah":33,"verses":[69]}],"verseLabel":"الأحزاب: 69","question":"ماذا يفيد إسناد تبرئة موسى إلى الله في قوله: ﴿فَبَرَّأَهُ اللَّهُ﴾؟","answer":"يفيد أن الله تولى إظهار براءته بنفسه، وفيه عناية بنبيه وقوة للحجة؛ فما يفتريه الناس لا يثبت أمام تبرئة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص543، تحت عنوان «لطيفة إسناد التبرئة إلى اسم الجلالة»","url":""}]},{"id":"s33-98","number":98,"surah":33,"verses":[69],"references":[{"surah":33,"verses":[69]}],"verseLabel":"الأحزاب: 69","question":"لماذا قُيدت وجاهة موسى بقوله: ﴿عِنْدَ اللَّهِ﴾؟","answer":"لبيان أن شرفه ثابت في أعلى مقام، لا متوقف على رأي الناس؛ ومن كان وجيهًا عند الله كانت منزلته أرفع وحجته أصدق.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص545، تحت عنوان «نكتة تقييد الوجاهة بالقيد ﴿عند الله﴾»","url":""}]},{"id":"s33-62","number":62,"surah":33,"verses":[70,71],"references":[{"surah":33,"verses":[70,71]}],"verseLabel":"الأحزاب: 70-71","question":"ما الذي يضيفه وصف القول بأنه ﴿سَدِيدًا﴾؟","answer":"يصور القول مستقيمًا مصيبًا للحق كالسهم الذي يسدد إلى هدفه؛ فيشمل الصدق والنصح والكلمة النافعة البعيدة عن الانحراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص551، تحت عنوان «لطيفة وصف القول بالسداد»","url":""}]},{"id":"s33-99","number":99,"surah":33,"verses":[70,71],"references":[{"surah":33,"verses":[70,71]}],"verseLabel":"الأحزاب: 70-71","question":"لماذا قُدم الأمر بتقوى الله على الأمر بالقول السديد؟","answer":"لأن التقوى أصل صلاح الأقوال والأعمال؛ فإذا راقب الإنسان ربه قاده ذلك إلى وزن كلامه وقول الحق، فالتقوى معيار القول السديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص552، تحت عنوان «الغرض من تقديم الأمر بالتقوى»","url":""}]},{"id":"s33-63","number":63,"surah":33,"verses":[72],"references":[{"surah":33,"verses":[72]}],"verseLabel":"الأحزاب: 72","question":"ما الصورة التي يرسمها عرض الأمانة على السماوات والأرض والجبال؟","answer":"هو تمثيل لعظم التكليف وثقله: صُورت الأجرام الهائلة كأنها مدركة عُرضت عليها الأمانة فأشفقت منها، ليشعر الإنسان بضخامة ما قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص565–566، تحت عنوان «بلاغة الاستعارة في عرض الأمانة»","url":""}]},{"id":"s33-100","number":100,"surah":33,"verses":[72],"references":[{"surah":33,"verses":[72]}],"verseLabel":"الأحزاب: 72","question":"لماذا ذُكرت الجبال خصوصًا بعد السماوات والأرض في عرض الأمانة؟","answer":"لأن الجبال أعظم ما يقع عليه البصر قوة وثباتًا، فذكر امتناعها وإشفاقها يجعل ثقل الأمانة أشد حضورًا في الحس ويبلغ التعظيم غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص568، تحت عنوان «لطيفة ذكر الجبال خصوصًا»","url":""}]},{"id":"s33-101","number":101,"surah":33,"verses":[72],"references":[{"surah":33,"verses":[72]}],"verseLabel":"الأحزاب: 72","question":"لماذا وُصف الإنسان بعد حمل الأمانة بأنه ﴿ظَلُومًا جَهُولًا﴾؟","answer":"لأن من خان الأمانة يظلم نفسه وغيره ويجهل عاقبة ما حمل؛ وغُلّبت الصفتان لظهورهما في أكثر البشر، لا للحكم بهما على كل إنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص574، تحت عنوان «بلاغة تغليب صفتي الظلم والجهل دون غيرهما»","url":""}]},{"id":"s33-64","number":64,"surah":33,"verses":[73],"references":[{"surah":33,"verses":[73]}],"verseLabel":"الأحزاب: 73","question":"لماذا أُخر ذكر المؤمنين بعد المنافقين والمشركين في ختام سورة الأحزاب؟","answer":"ليُختم السياق بباب التوبة والرجاء بعد الوعيد، ويظهر أن حفظ الأمانة يرفع المؤمنين بينما خيانتها توقع أهل النفاق والشرك في العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص578–579، تحت عنوان «براعة تأخير ذكر أهل الإيمان عن أهل الشرك والنفاق»","url":""}]},{"id":"s33-102","number":102,"surah":33,"verses":[73],"references":[{"surah":33,"verses":[73]}],"verseLabel":"الأحزاب: 73","question":"ما مناسبة الجمع بين المغفرة والرحمة في ختام سورة الأحزاب؟","answer":"المغفرة تستر الذنوب وتمحو آثارها، والرحمة تجلب الفضل والإحسان بعد ذلك؛ فجمعهما يطمئن المؤمن إلى دفع الضرر ونيل الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص580، تحت عنوان «وجه مناسبة الرحمة للمغفرة»","url":""}]},{"id":"s34-1","number":1,"surah":34,"verses":[1],"references":[{"surah":34,"verses":[1]}],"verseLabel":"سبأ: 1","question":"ما براعة افتتاح سورة سبأ بالحمد لله وملكه للسماوات والأرض؟","answer":"افتتح بالحمد ثم بعموم الملك ليقرر من أول السورة أن المستحق للحمد وحده هو الخالق المدبر المالك لكل شيء، وفيه تعريض بمن يحمدون ما لا يملك لهم نفعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص595، تحت عنوان «براعة الاستهلال في افتتاح السورة»","url":""}]},{"id":"s34-2","number":2,"surah":34,"verses":[1],"references":[{"surah":34,"verses":[1]}],"verseLabel":"سبأ: 1","question":"لماذا خُصت الآخرة بقوله: ﴿وَلَهُ الْحَمْدُ فِي الْآخِرَةِ﴾ مع أن الحمد لله في الدارين؟","answer":"لأن حمد الآخرة أكمل وأدوم؛ تنكشف فيها الحقائق وتتم النعم ويزول ادعاء الشركاء، فلا يبقى الحمد ظاهرًا وباطنًا إلا لله، مع ثبوت حمده في الدنيا أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص606–607، تحت عنوان «أسرار المغايرة بتكرار الحمد»","url":""}]},{"id":"s34-3","number":3,"surah":34,"verses":[2],"references":[{"surah":34,"verses":[2]},{"surah":57,"verses":[4]}],"verseLabel":"سبأ: 2؛ الحديد: 4","question":"لماذا اختلف ختام آية الولوج والخروج في سبأ عن نظيرتها في الحديد؟","answer":"في سبأ جاء ﴿وهو الرحيم الغفور﴾ لأن ما يلج ويخرج وينزل ويعرج يشمل أعمال العباد المحتاجة إلى الرحمة والمغفرة؛ وفي الحديد جاء ﴿والله بما تعملون بصير﴾ بعد بيان الخلق والملك والمعية، فناسب مراقبة الأعمال. اتفقت الآيتان في إحاطة العلم واختلف الختام بحسب السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص630، تحت عنوان «بلاغة الاتفاق والاختلاف مع الآية (2) من سورة سبأ»","url":""}]},{"id":"s34-4","number":4,"surah":34,"verses":[2],"references":[{"surah":34,"verses":[2]}],"verseLabel":"سبأ: 2","question":"ما سرّ تقديم ﴿الرَّحِيمُ﴾ على ﴿الْغَفُورُ﴾ في ختام الآية 2؟","answer":"من وجوه التقديم أن السياق يعم المخلوقات، فناسب البدء بالرحمة العامة ثم المغفرة المتعلقة بالمكلفين. كما أن العلم بأعمال العباد قد يثير الخشية، فبُدئ بما يؤنسهم من الرحمة؛ ومن لطائف الترتيب أن الرحمة تقدم المصالح، والمغفرة تدفع المفاسد.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص626–627، تحت عنوان «لطائف تقديم ﴿الرحيم﴾ على ﴿الغفور﴾»","url":""}]},{"id":"s34-5","number":5,"surah":34,"verses":[3],"references":[{"surah":34,"verses":[3]}],"verseLabel":"سبأ: 3","question":"ماذا تفيد ﴿بَلَى﴾ في الرد على قولهم: ﴿لَا تَأْتِينَا السَّاعَةُ﴾؟","answer":"تبطل نفيهم وتثبت وقوع الساعة إثباتًا حاسمًا؛ فهي الجواب المخصص لنقض النفي، فتنقل الكلام من إنكارهم إلى الحقيقة المؤكدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص638، تحت عنوان «دلالة التعبير بحرف ﴿بلى﴾»","url":""}]},{"id":"s34-47","number":47,"surah":34,"verses":[3],"references":[{"surah":34,"verses":[3]}],"verseLabel":"سبأ: 3","question":"لماذا توالت المؤكدات في قوله: ﴿بَلَى وَرَبِّي لَتَأْتِيَنَّكُمْ﴾؟","answer":"لأن المخاطبين بالغوا في إنكار الساعة، فقوبل إنكارهم بالقسم واللام ونون التوكيد حتى يثبت الخبر من كل وجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص641، تحت عنوان «دلالة توالي المؤكدات في الجملة»","url":""}]},{"id":"s34-48","number":48,"surah":34,"verses":[3],"references":[{"surah":34,"verses":[3]}],"verseLabel":"سبأ: 3","question":"لماذا وُصف الله بعد القسم بأنه ﴿عَالِمِ الْغَيْبِ﴾؟","answer":"ليؤكد أن الخبر عن الساعة صادر عن علم محيط بما غاب، فيزداد القسم ثبوتًا؛ فما أخبر به عالم الغيب أحق باليقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص641، تحت عنوان «دلالة الوصف بعلم الغيب بعد القسم»","url":""}]},{"id":"s34-7","number":7,"surah":34,"verses":[5],"references":[{"surah":34,"verses":[5]}],"verseLabel":"سبأ: 5","question":"ما الصورة التي ترسمها كلمة ﴿مُعَاجِزِينَ﴾ لمن يسعون في آيات الله؟","answer":"تصورهم كأنهم يحاولون سباق الله وإفلات آياته أو إبطالها، وهو محال؛ فتكشف غرورهم وجهدهم العقيم في محاربة الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص675، تحت عنوان «بلاغة الاستعارة في التعبير بالمعاجزة»","url":""}]},{"id":"s34-49","number":49,"surah":34,"verses":[5],"references":[{"surah":34,"verses":[5]}],"verseLabel":"سبأ: 5","question":"ماذا يفيد تنكير ﴿رِجْزٍ﴾ في قوله: ﴿لَهُمْ عَذَابٌ مِنْ رِجْزٍ﴾؟","answer":"يفيد نوعًا مهولًا غير معهود من العذاب الشديد، فيترك التنكير النفس تتصور فظاعته من غير حد.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص677، تحت عنوان «دلالة التعبير بـ﴿رجز﴾ منكرًا»","url":""}]},{"id":"s34-50","number":50,"surah":34,"verses":[5],"references":[{"surah":34,"verses":[5]}],"verseLabel":"سبأ: 5","question":"ماذا يضيف وصف الرجز بأنه ﴿أَلِيمٌ﴾؟","answer":"يزيد الوعيد بإبراز أثر العذاب في نفوسهم؛ فهو شديد في ذاته وموجع لمن يصيبه، فيجتمع التهويل والترهيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص678، تحت عنوان «نكتة وصف الرجز بـ﴿أليم﴾»","url":""}]},{"id":"s34-8","number":8,"surah":34,"verses":[6],"references":[{"surah":34,"verses":[6]}],"verseLabel":"سبأ: 6","question":"لماذا عبّر عن علم أهل العلم بالقرآن بقوله: ﴿وَيَرَى الَّذِينَ أُوتُوا الْعِلْمَ﴾؟","answer":"لأن يقينهم بالوحي بلغ من الوضوح منزلة المشاهدة؛ فاختيرت الرؤية لتصوير علم حاضر مستمر لا تزلزله شبه المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص685، تحت عنوان «دلالة التعبير بالرؤية»","url":""}]},{"id":"s34-51","number":51,"surah":34,"verses":[6],"references":[{"surah":34,"verses":[6]}],"verseLabel":"سبأ: 6","question":"لماذا خُص ﴿الَّذِينَ أُوتُوا الْعِلْمَ﴾ بتمييز حقية القرآن؟","answer":"لأن العلم يرفع منزلتهم ويهيئهم لرؤية دلائل الوحي، وفي التعبير بالإيتاء إيماء إلى أن هذا العلم فضل من الله لا مجرد دعوى بشرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص687، تحت عنوان «سر تخصيص ﴿أوتوا العلم﴾ بالذكر»","url":""}]},{"id":"s34-9","number":9,"surah":34,"verses":[7],"references":[{"surah":34,"verses":[7]}],"verseLabel":"سبأ: 7","question":"ما التهكم في قول الكافرين: ﴿هَلْ نَدُلُّكُمْ عَلَى رَجُلٍ﴾؟","answer":"تظاهروا بأنهم يرشدون الناس إلى رجل مجهول مع أنهم يعرفون النبي ﷺ، ليستخفوا به ويصرفوا السامعين عنه في صورة نصح كاذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص701، تحت عنوان «سر التعبير بالدلالة»","url":""}]},{"id":"s34-52","number":52,"surah":34,"verses":[7],"references":[{"surah":34,"verses":[7]}],"verseLabel":"سبأ: 7","question":"لماذا نكّروا ﴿رَجُلٍ﴾ في قولهم: ﴿هَلْ نَدُلُّكُمْ عَلَى رَجُلٍ﴾؟","answer":"ليتجاهلوا شأن النبي ﷺ ويجعلوه كأي رجل غير معروف، زيادة في السخرية والتحقير مع أنهم أعرف الناس به.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص702، تحت عنوان «دلالة التعبير بـ﴿رجل﴾ نكرة»","url":""}]},{"id":"s34-53","number":53,"surah":34,"verses":[7],"references":[{"surah":34,"verses":[7]}],"verseLabel":"سبأ: 7","question":"لماذا اختير ﴿يُنَبِّئُكُمْ﴾ في حكاية قولهم عن البعث؟","answer":"لأن الإنباء يكون عن خبر عظيم، وخبر الخلق الجديد بعد التمزق من أعظم الأخبار؛ فجاءت اللفظة ملائمة لعظم ما يستنكرونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص703، تحت عنوان «دلالة التعبير بالتنبئة»","url":""}]},{"id":"s34-10","number":10,"surah":34,"verses":[8],"references":[{"surah":34,"verses":[8]}],"verseLabel":"سبأ: 8","question":"ما أثر ﴿بَلْ﴾ في الرد على اتهامهم النبي ﷺ بالكذب أو الجنون؟","answer":"تضرب عن احتمالَيهم كليهما وترد الوصف إليهم؛ فليس الرسول كاذبًا ولا مجنونًا، بل هم الذين لا يؤمنون بالآخرة في العذاب والضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص722، تحت عنوان «معنى ﴿بل﴾ في قوله: ﴿بل الذين لا يؤمنون﴾»","url":""}]},{"id":"s34-11","number":11,"surah":34,"verses":[9],"references":[{"surah":34,"verses":[9]}],"verseLabel":"سبأ: 9","question":"لماذا حُصر التهديد في الخسف من تحتهم أو إسقاط كسف من فوقهم؟","answer":"لأن السماء والأرض محيطتان بهم ولا مهرب من جهتيهما؛ يستطيع الإنسان التحرك أمامًا وخلفًا، لكنه لا يملك الفرار إذا جاءه العذاب من فوقه أو تحته.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص748، تحت عنوان «دلالة حصر العذاب في (الفوق) و(التحت)»","url":""}]},{"id":"s34-12","number":12,"surah":34,"verses":[10],"references":[{"surah":34,"verses":[10]}],"verseLabel":"سبأ: 10","question":"لماذا خوطبت الجبال في قوله: ﴿يَا جِبَالُ أَوِّبِي مَعَهُ﴾ كأنها تعقل؟","answer":"لإظهار كمال انقيادها لأمر الله؛ صُورت الجبال الراسية كأنها تسمع النداء وتجيب، فتشارك داود التسبيح في مشهد كوني مهيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص763–764، تحت عنوان «دلالة مخاطبة الجبال وتنزيلها منزلة العقلاء»","url":""}]},{"id":"s34-54","number":54,"surah":34,"verses":[10],"references":[{"surah":34,"verses":[10]}],"verseLabel":"سبأ: 10","question":"لماذا قيل للجبال ﴿أَوِّبِي﴾ ولم يقل: رددي أو رجعي؟","answer":"التأويب يدل على الرجوع المتكرر؛ فيصور عود التسبيح مرة بعد مرة مع داود، لا مجرد ترديد صوت عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص764، تحت عنوان «دلالة التعبير بـ (التأويب) دون (الترديد) و(الترجيع)»","url":""}]},{"id":"s34-13","number":13,"surah":34,"verses":[10],"references":[{"surah":34,"verses":[10]}],"verseLabel":"سبأ: 10","question":"ماذا يفيد إسناد إلانة الحديد إلى ضمير العظمة في قوله: ﴿وَأَلَنَّا لَهُ الْحَدِيدَ﴾؟","answer":"يبرز أن تحول الحديد الصلب إلى مادة لينة وقع بقدرة الله مباشرة ومن غير معالجة بشرية معتادة، فكان فضلًا ومعجزة لداود.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص768، تحت عنوان «لطيفة إسناد الفعل ﴿وألنا﴾ إلى ضمير العظمة»","url":""}]},{"id":"s34-55","number":55,"surah":34,"verses":[10],"references":[{"surah":34,"verses":[10]}],"verseLabel":"سبأ: 10","question":"لماذا اختير لداود صنع الدروع دون غيرها من وسائل الحرب؟","answer":"لأن الدرع وقاية تحفظ النفس من القتل، فكان تعليمه صناعة تحمي الإنسان أنسب بفضل الله من صناعة أداة هجوم وسفك.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص771، تحت عنوان «سر اختيار صنعة الدروع دون غيرها من وسائل الحرب»","url":""}]},{"id":"s34-14","number":14,"surah":34,"verses":[11],"references":[{"surah":34,"verses":[11]}],"verseLabel":"سبأ: 11","question":"لماذا قيل: ﴿وَقَدِّرْ فِي السَّرْدِ﴾ ولم يقل: أحكمه؟","answer":"لأن التقدير يضيف إلى الإحكام معنى ضبط المقادير والتناسب: حلق الدرع ومساميرها لا تصغر فتضعف ولا تكبر فتثقل أو تفصم الحلق، فتجتمع القوة والخفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص772، تحت عنوان «دلالة التعبير بمفردة (التقدير) دون (الإحكام)»","url":""}]},{"id":"s34-15","number":15,"surah":34,"verses":[12],"references":[{"surah":34,"verses":[12]}],"verseLabel":"سبأ: 12","question":"ما المحذوف في قوله عن الريح: ﴿غُدُوُّهَا شَهْرٌ وَرَوَاحُهَا شَهْرٌ﴾؟","answer":"المعنى: غدوها مسيرة شهر ورواحها مسيرة شهر؛ حُذفت ﴿مسيرة﴾ إيجازًا لوضوحها، وفي الحذف تصوير أسرع لقدرة الريح المسخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص789، تحت عنوان «بلاغة الحذف في الآية الكريمة»","url":""}]},{"id":"s34-56","number":56,"surah":34,"verses":[12],"references":[{"surah":34,"verses":[12]}],"verseLabel":"سبأ: 12","question":"لماذا تكرر لفظ ﴿شَهْرٌ﴾ في قوله: ﴿غُدُوُّهَا شَهْرٌ وَرَوَاحُهَا شَهْرٌ﴾؟","answer":"ليثبت مقدار شهر لكل من الغدو والرواح مستقلًا، فلا يتوهم أن الشهر مجموعهما؛ فتقطع الريح في يوم مسيرة شهرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص790، تحت عنوان «سر تكرار لفظ ﴿شهر﴾»","url":""}]},{"id":"s34-16","number":16,"surah":34,"verses":[12],"references":[{"surah":34,"verses":[12]}],"verseLabel":"سبأ: 12","question":"لماذا قيل: ﴿وَأَسَلْنَا لَهُ عَيْنَ الْقِطْرِ﴾ ولم يقل: فجّرنا؟","answer":"لأن الإسالة تلائم النحاس المذاب؛ فهي تصور تحويل المعدن الصلب إلى مادة سائلة طيعة يسهل تشكيلها والانتفاع بها، بخلاف التفجير الذي يناسب خروج الماء من منبعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص791، تحت عنوان «نكتة التعبير بـ(الإسالة) دون التفجير في ﴿وأسلنا﴾»","url":""}]},{"id":"s34-57","number":57,"surah":34,"verses":[12],"references":[{"surah":34,"verses":[12]}],"verseLabel":"سبأ: 12","question":"ما الصورة التي يرسمها التعبير عن النحاس المذاب بـ﴿عَيْنَ الْقِطْرِ﴾؟","answer":"يصوره كعين ماء غزيرة يتدفق منها النحاس المذاب بلا كلفة، فتظهر كثرة النعمة ودوامها وتسخيرها لسليمان عليه السلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص793، تحت عنوان «دلالة التعبير بالعين في ﴿عين القطر﴾»","url":""}]},{"id":"s34-17","number":17,"surah":34,"verses":[13],"references":[{"surah":34,"verses":[13]}],"verseLabel":"سبأ: 13","question":"لماذا قيل لآل داود: ﴿اعْمَلُوا﴾ شكرًا، فجُعل الشكر عملًا؟","answer":"ليدل على أن الشكر لا يقتصر على القول، بل يلتزم فيه القلب واللسان والجوارح؛ فتُقابل النعمة بالطاعة والعمل الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص20، تحت عنوان «سر إيثار الأمر بالعمل»","url":""}]},{"id":"s34-18","number":18,"surah":34,"verses":[13],"references":[{"surah":34,"verses":[13]}],"verseLabel":"سبأ: 13","question":"لماذا وصف الله الشاكرين بأنهم ﴿قَلِيلٌ﴾؟","answer":"لأن من يستوفي الشكر قلبًا وقولًا وعملًا قليل، وفي التصريح بقلتهم حث على المسارعة إلى هذه المرتبة والتنبيه إلى خطر الغفلة عن النعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص21، تحت عنوان «دلالة التعبير بـ(القلة)، ولطيفة تنكيرها»","url":""}]},{"id":"s34-19","number":19,"surah":34,"verses":[14],"references":[{"surah":34,"verses":[14]}],"verseLabel":"سبأ: 14","question":"لماذا لم يدلّ الجن على موت سليمان إلا سقوطه بعد أن أكلت دابة الأرض عصاه؟","answer":"ليظهر عجز الجن عن علم الغيب؛ ظلوا يعملون وهو ميت حتى كشفت دابة ضعيفة موته، فانهدمت دعواهم بأوضح صورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص29، تحت عنوان «دلالة القصر بالنفي والاستثناء في الآية»","url":""}]},{"id":"s34-58","number":58,"surah":34,"verses":[14],"references":[{"surah":34,"verses":[14]}],"verseLabel":"سبأ: 14","question":"لماذا قيل: ﴿دَابَّةُ الْأَرْضِ﴾ من غير تعيين؟","answer":"لإبراز أن مخلوقًا أرضيًا صغيرًا مجهول الشأن كان سبب انكشاف الحقيقة، وفي ذلك زيادة إهانة لدعوى الجن علم الغيب وإظهار لعجزهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص31، تحت عنوان «دلالة التعبير بـ﴿دابة﴾، ولطيفة إضافتها»","url":""}]},{"id":"s34-20","number":20,"surah":34,"verses":[14],"references":[{"surah":34,"verses":[14]}],"verseLabel":"سبأ: 14","question":"ما سرّ التعبير عن العصا بـ﴿مِنْسَأَتَهُ﴾؟","answer":"المنسأة عصا يُنسأ بها، أي يؤخر ويزجر. واستحضر الاسم هيبة سليمان وسلطانه، حتى ظل منظر اتكائه عليها مانعًا من تبيّن موته؛ فلما أكلتها الدابة وخرّ، انكشف جهل الجن بالغيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص32–33، تحت عنوان «دلالة التعبير بـ﴿منسأته﴾، ولطيفة الإضافة فيه»","url":""}]},{"id":"s34-21","number":21,"surah":34,"verses":[15],"references":[{"surah":34,"verses":[15]}],"verseLabel":"سبأ: 15","question":"لماذا جُعلت آية سبأ ﴿فِي مَسْكَنِهِمْ﴾؟","answer":"لأن النعمة كانت حاضرة في موطنهم ملازمة لهم، يرونها ويستقرون في ظلالها؛ فكانت الحجة أقرب إلى الإدراك وأدعى إلى الشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص46، تحت عنوان «سر تقييد ﴿لسبإ﴾ بالجار والمجرور»","url":""}]},{"id":"s34-59","number":59,"surah":34,"verses":[15],"references":[{"surah":34,"verses":[15]}],"verseLabel":"سبأ: 15","question":"لماذا عبّر عن بساتين سبأ بقوله: ﴿جَنَّتَانِ عَنْ يَمِينٍ وَشِمَالٍ﴾؟","answer":"لأن بساتين كل جهة لكثرتها واتصالها بدت كأنها جنة واحدة عظيمة؛ فالتثنية تصور إحاطة الخصب بمساكنهم من الجانبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص47–48، تحت عنوان «نكتة تثنية ﴿جنتان﴾، ولطيفة تنكيرهما»","url":""}]},{"id":"s34-22","number":22,"surah":34,"verses":[15],"references":[{"surah":34,"verses":[15]}],"verseLabel":"سبأ: 15","question":"ما سر الجمع بين ﴿بَلْدَةٌ طَيِّبَةٌ وَرَبٌّ غَفُورٌ﴾؟","answer":"جمع لهم خير الدنيا بطيب البلدة وخير الآخرة بمغفرة الرب؛ فالواو تصل نعمة المعاش بنعمة العفو وتصور كمال الإحسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص57، تحت عنوان «معنى (الواو) ودلالتها في ﴿ورب غفور﴾»","url":""}]},{"id":"s34-60","number":60,"surah":34,"verses":[15],"references":[{"surah":34,"verses":[15]}],"verseLabel":"سبأ: 15","question":"لماذا قيل: ﴿وَرَبٌّ غَفُورٌ﴾ ولم يقل: وإله غفور؟","answer":"لأن مقام الآية مقام تربية ورعاية وإنعام؛ فاسم الرب يذكرهم بمن يتعهدهم بالنعم ويدعوهم إلى دوام الطاعة والشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص58، تحت عنوان «إيثار التعبير بالربوبية دون الألوهية»","url":""}]},{"id":"s34-61","number":61,"surah":34,"verses":[15],"references":[{"surah":34,"verses":[15]}],"verseLabel":"سبأ: 15","question":"لماذا وُصف الرب هنا بأنه ﴿غَفُورٌ﴾؟","answer":"ليطمئنهم إلى أن تقصيرهم في شكر النعمة لا يغلق باب العفو إذا رجعوا، فيجتمع الترغيب في الشكر والرجاء في المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص59، تحت عنوان «دلالة وصف الرب بـ﴿غفور﴾»","url":""}]},{"id":"s34-23","number":23,"surah":34,"verses":[16],"references":[{"surah":34,"verses":[16]}],"verseLabel":"سبأ: 16","question":"لماذا قيل: ﴿وَبَدَّلْنَاهُمْ بِجَنَّتَيْهِمْ﴾ ولم يقل: وبدلناهم بهما؟","answer":"أُظهر لفظ الجنتين بدل الضمير ليذكّرهم صراحة بالنعمة العظيمة التي أضاعوها، فتشتد الحسرة ويظهر التفاوت بين الأصل والبديل.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص72، تحت عنوان «نكتة الإظهار في مقام الإضمار في ﴿بجنتيهم﴾»","url":""}]},{"id":"s34-62","number":62,"surah":34,"verses":[16],"references":[{"surah":34,"verses":[16]}],"verseLabel":"سبأ: 16","question":"لماذا سُمّي البديل الرديء أيضًا ﴿جَنَّتَيْنِ﴾؟","answer":"على سبيل المشاكلة والتهكم؛ فقد بقي الاسم بينما انقلبت الحقيقة من جنتين مثمرتين إلى أرض ذات ثمر مرّ وشجر قليل النفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص73، تحت عنوان «بلاغة المشاكلة في البديلين ﴿جنتين﴾»","url":""}]},{"id":"s34-63","number":63,"surah":34,"verses":[16],"references":[{"surah":34,"verses":[16]}],"verseLabel":"سبأ: 16","question":"لماذا عُدّدت أوصاف البديل: ﴿خَمْطٍ وَأَثْلٍ وَشَيْءٍ مِنْ سِدْرٍ قَلِيلٍ﴾؟","answer":"ليتدرج التصوير في كشف رداءة البديل وقلة نفعه: مرارة الخمط، وضعف منفعة الأثل، ثم شيء يسير من السدر؛ فتتضاعف الحسرة على الجنتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص76، تحت عنوان «نكتة تعديد الأوصاف ﴿خمط﴾، ﴿وأثل﴾، ﴿وسدر﴾»","url":""}]},{"id":"s34-24","number":24,"surah":34,"verses":[16],"references":[{"surah":34,"verses":[16]}],"verseLabel":"سبأ: 16","question":"لماذا عبّر عن مجيء السيل بقوله: ﴿فَأَرْسَلْنَا عَلَيْهِمْ﴾؟","answer":"ليصوره عقوبة موجهة بأمر الله لا حادثًا طبيعيًا عابرًا؛ فالسيل رسالة عذاب سلطها الله عليهم جزاء إعراضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص67، تحت عنوان «دلالة التعبير بـ(الإرسال)»","url":""}]},{"id":"s34-64","number":64,"surah":34,"verses":[16],"references":[{"surah":34,"verses":[16]}],"verseLabel":"سبأ: 16","question":"لماذا قيل: ﴿سَيْلَ الْعَرِمِ﴾ ولم يقل: صَيِّبًا؟","answer":"لأن السيل ماء مندفع جارٍ يجرف ويدمر، وهو الأنسب لخراب مساكنهم وجنتيهم؛ أما الصيب فمطر نازل قد يكون رحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص69، تحت عنوان «دلالة التعبير بـ﴿سيل﴾ دون ﴿صيب﴾»","url":""}]},{"id":"s34-65","number":65,"surah":34,"verses":[16],"references":[{"surah":34,"verses":[16]}],"verseLabel":"سبأ: 16","question":"ماذا توحي كلمة ﴿الْعَرِمِ﴾ في وصف السيل؟","answer":"توحي بالشدة والاندفاع والمرارة والاتساع، فتجمع إيحاءات تناسب سيلًا جارفًا أهلك عمرانهم وأذهب نعمتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص69، تحت عنوان «دلالة التعبير بـ﴿العرم﴾، ومعنى (اللام) ودلالتها فيه»","url":""}]},{"id":"s34-25","number":25,"surah":34,"verses":[17],"references":[{"surah":34,"verses":[17]}],"verseLabel":"سبأ: 17","question":"لماذا قيل: ﴿الْكَفُورَ﴾ ولم يقل: الكافر؟","answer":"لأن صيغة فعول تدل على المبالغة؛ فالجزاء المستأصل المذكور يناسب من تمادى في كفر النعمة وجحدها، لا مجرد من وقع منه تقصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص86، تحت عنوان «نكتة التعبير بصيغة (فعول)»","url":""}]},{"id":"s34-66","number":66,"surah":34,"verses":[17],"references":[{"surah":34,"verses":[17]}],"verseLabel":"سبأ: 17","question":"ما الذي يقصره قوله: ﴿وَهَلْ نُجَازِي إِلَّا الْكَفُورَ﴾ على الكفور؟","answer":"يقصر عليه هذا الجزاء الشديد المستأصل أو استيفاء العقوبة على هذا الوجه، فلا يعني أن غيره لا يؤاخذ مطلقًا؛ بل يبرز تناسب عظم الجزاء مع المبالغة في الكفران.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص87–88، تحت عنوان «بلاغة القصر»","url":""}]},{"id":"s34-26","number":26,"surah":34,"verses":[18],"references":[{"surah":34,"verses":[18]}],"verseLabel":"سبأ: 18","question":"لماذا وُصفت القرى بين سبأ والشام بأنها ﴿ظَاهِرَةً﴾؟","answer":"لأنها كانت متقاربة بارزة يرى بعضها من بعض، فلا يضل المسافر ولا ينقطع عن العمران والزاد؛ فالوصف يصور سهولة الطريق وأمنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص97–98، تحت عنوان «سر وصف القرى بالظهور»","url":""}]},{"id":"s34-67","number":67,"surah":34,"verses":[18],"references":[{"surah":34,"verses":[18]}],"verseLabel":"سبأ: 18","question":"ما دلالة قوله: ﴿وَقَدَّرْنَا فِيهَا السَّيْرَ﴾؟","answer":"يدل على أن مراحل الطريق ضُبطت بمقادير متناسبة؛ ينتقل المسافر من قرية إلى أخرى في زمن مريح من غير مشقة أو انقطاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص98–99، تحت عنوان «دلالة التعبير بالتقدير في الفعل ﴿وقدرنا﴾»","url":""}]},{"id":"s34-68","number":68,"surah":34,"verses":[18],"references":[{"surah":34,"verses":[18]}],"verseLabel":"سبأ: 18","question":"لماذا قُيّد السير بقوله: ﴿آمِنِينَ﴾؟","answer":"لإبراز تمام النعمة؛ فلم يكن الطريق قريب المنازل فحسب، بل كان سالكه مطمئنًا على نفسه وماله ليلًا ونهارًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص105، تحت عنوان «سر التقييد بالحال ﴿آمنين﴾»","url":""}]},{"id":"s34-27","number":27,"surah":34,"verses":[19],"references":[{"surah":34,"verses":[19]}],"verseLabel":"سبأ: 19","question":"لماذا طلب أهل سبأ: ﴿رَبَّنَا بَاعِدْ بَيْنَ أَسْفَارِنَا﴾ مع أن قرب المنازل نعمة؟","answer":"بطروا النعمة واستثقلوا سهولة السفر، وقيل أراد مترفوهم أن ينفردوا بالتجارة فلا يشاركهم الفقراء؛ فطلبوا المشقة بدل الراحة ظلمًا لأنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص111–112، تحت عنوان «دلالة التعبير بالمباعدة في قوله: ﴿ربنا باعد بين أسفارنا﴾»","url":""}]},{"id":"s34-69","number":69,"surah":34,"verses":[19],"references":[{"surah":34,"verses":[19]}],"verseLabel":"سبأ: 19","question":"ما الصورة التي يرسمها قوله: ﴿وَمَزَّقْنَاهُمْ كُلَّ مُمَزَّقٍ﴾؟","answer":"يشبه تفريقهم في البلاد بتمزيق الثوب قطعًا متناثرة؛ فبعد اجتماعهم وعمرانهم صاروا جماعات متباعدة يُضرب بتفرقها المثل.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص119، تحت عنوان «بلاغة التعبير بالاستعارة في ﴿ومزقناهم﴾»","url":""}]},{"id":"s34-28","number":28,"surah":34,"verses":[20],"references":[{"surah":34,"verses":[20]}],"verseLabel":"سبأ: 20","question":"كيف توسع القراءتان معنى قوله: ﴿وَلَقَدْ صَدَّقَ عَلَيْهِمْ إِبْلِيسُ ظَنَّهُ﴾؟","answer":"قراءة التخفيف تفيد أن ظن إبليس فيهم وافق الواقع، وقراءة التشديد تفيد أنه حقق ظنه بإغوائهم؛ فتجمعان بين صدق توقعه ووقوع أثر وسوسته.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص131، تحت عنوان «أثر تنوع القراءات في ﴿صدق عليهم إبليس ظنه﴾»","url":""}]},{"id":"s34-70","number":70,"surah":34,"verses":[20],"references":[{"surah":34,"verses":[20]}],"verseLabel":"سبأ: 20","question":"لماذا سُمّي توقع إبليس عنهم ﴿ظَنَّهُ﴾؟","answer":"لأنه لا يعلم الغيب؛ إنما توقع استجابتهم بالوسوسة لما عرف من ضعف البشر، فلما اتبعوه صدق ظنه من غير علم سابق بما سيكون.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص134–135، تحت عنوان «دلالة التعبير بالظن في ﴿ظنه﴾»","url":""}]},{"id":"s34-29","number":29,"surah":34,"verses":[21],"references":[{"surah":34,"verses":[21]}],"verseLabel":"سبأ: 21","question":"ما الذي ينفيه قوله عن إبليس: ﴿وَمَا كَانَ لَهُ عَلَيْهِمْ مِنْ سُلْطَانٍ﴾؟","answer":"ينفي أن تكون له حجة أو قهر أو قدرة تجبرهم على الكفر؛ سلطانه لا يتجاوز الوسوسة، وهم اتبعوه باختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص144–145، تحت عنوان «دلالة التعبير بـ(السلطان)»","url":""}]},{"id":"s34-71","number":71,"surah":34,"verses":[21],"references":[{"surah":34,"verses":[21]}],"verseLabel":"سبأ: 21","question":"كيف يُفهم الاستثناء في قوله: ﴿إِلَّا لِنَعْلَمَ﴾ بعد نفي سلطان إبليس؟","answer":"ليس معناه أن إبليس مُنح سلطانًا قاهرًا، بل استُثنيت حكمة إمهاله ووسوسته: أن يقع الابتلاء الذي يتميز به المؤمن بالآخرة من الشاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص145، تحت عنوان «معنى ﴿إلا﴾ ودلالتها في جملة ﴿إلا لنعلم﴾»","url":""}]},{"id":"s34-30","number":30,"surah":34,"verses":[22],"references":[{"surah":34,"verses":[22]}],"verseLabel":"سبأ: 22","question":"لماذا نُفي عن المعبودات ملك ﴿مِثْقَالَ ذَرَّةٍ﴾؟","answer":"لأن مثقال الذرة يمثل أدق مقدار يتصوره السامع؛ فنفي ملكه يقطع أن يكون لها أدنى استقلال في السماوات أو الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص166، تحت عنوان «سر إضافة ﴿مثقال﴾ إلى ﴿ذرة﴾»","url":""}]},{"id":"s34-72","number":72,"surah":34,"verses":[22],"references":[{"surah":34,"verses":[22]}],"verseLabel":"سبأ: 22","question":"ماذا يضيف قوله: ﴿وَمَا لَهُمْ فِيهِمَا مِنْ شِرْكٍ﴾ بعد نفي ملك الذرة؟","answer":"ينفي احتمال أن يكون لهم نصيب مشترك في ملك الكون بعدما نُفي ملكهم المستقل، فتسقط شبهة الشراكة من أصلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص169، تحت عنوان «معنى (الواو) ودلالتها في قوله: ﴿وما لهم﴾»","url":""}]},{"id":"s34-73","number":73,"surah":34,"verses":[22],"references":[{"surah":34,"verses":[22]}],"verseLabel":"سبأ: 22","question":"ماذا يضيف قوله: ﴿وَمَا لَهُ مِنْهُمْ مِنْ ظَهِيرٍ﴾؟","answer":"ينفي أن يكون الله محتاجًا إلى واحد منهم معينًا أو معاونًا؛ فبعد نفي استقلالهم وشركتهم نُفي حتى أن يكون لهم دور في الإعانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص172، تحت عنوان «معنى (الواو) ودلالتها في ﴿وما له﴾»","url":""}]},{"id":"s34-31","number":31,"surah":34,"verses":[23],"references":[{"surah":34,"verses":[23]}],"verseLabel":"سبأ: 23","question":"لماذا قُيّد نفع الشفاعة بقوله: ﴿عِنْدَهُ إِلَّا لِمَنْ أَذِنَ لَهُ﴾؟","answer":"ليقرر أن الشفاعة لا تعمل بضغط شافع ولا باستحقاق أحد، وإنما تقع في حضرة ملكه وبإذنه وحده؛ فيبطل اعتماد المشركين على شفعاء مستقلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص181–182، تحت عنوان «نكتة تقييد نفي الشفاعة بالظرف»","url":""}]},{"id":"s34-32","number":32,"surah":34,"verses":[24],"references":[{"surah":34,"verses":[24]}],"verseLabel":"سبأ: 24","question":"ما غرض السؤال: ﴿مَنْ يَرْزُقُكُمْ مِنَ السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"هو تقرير وتبكيت؛ فالجواب معلوم لهم، والسؤال يستدعي اعترافهم بأن رازقهم الله ثم يلزمهم أن العبادة لا تكون إلا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص197، تحت عنوان «غرض الاستفهام وفائدته»","url":""}]},{"id":"s34-74","number":74,"surah":34,"verses":[24],"references":[{"surah":34,"verses":[24]}],"verseLabel":"سبأ: 24","question":"كيف يستدرجهم قوله: ﴿وَإِنَّا أَوْ إِيَّاكُمْ لَعَلَى هُدًى أَوْ فِي ضَلَالٍ مُبِينٍ﴾ إلى الإنصاف؟","answer":"يعرض الاحتمالين في ظاهر منصف من غير مصادرة، مع وضوح أن أحد الفريقين مهتد والآخر ضال؛ فيدعو الخصم إلى التفكر حتى يقر بالحقيقة بنفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص201–202، تحت عنوان «فن الاستدراج في الخطاب»","url":""}]},{"id":"s34-33","number":33,"surah":34,"verses":[25],"references":[{"surah":34,"verses":[25]}],"verseLabel":"سبأ: 25","question":"لماذا نسب الرسول ﷺ الإجرام إلى نفسه فقال: ﴿عَمَّا أَجْرَمْنَا﴾؟","answer":"جاء على سبيل الإنصاف واللطف في المحاورة، فافترض الجرم في جانب المتكلم ليبعد عناد الخصم ويفتح له باب النظر الهادئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص213، تحت عنوان «نكتة إسناد فعل الإجرام إلى ضمير المتكلم»","url":""}]},{"id":"s34-75","number":75,"surah":34,"verses":[25],"references":[{"surah":34,"verses":[25]}],"verseLabel":"سبأ: 25","question":"لماذا قوبل ﴿عَمَّا أَجْرَمْنَا﴾ بقوله: ﴿عَمَّا تَعْمَلُونَ﴾؟","answer":"سمّى ما في جانبه جرمًا على سبيل التواضع الجدلي، وسمّى ما في جانبهم عملًا بلا تقبيح؛ فبلغ غاية الأدب والإنصاف مع تقرير استقلال كل نفس بتبعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص214، تحت عنوان «بلاغة المقابلة بين الجمل المتعاطفة»","url":""}]},{"id":"s34-34","number":34,"surah":34,"verses":[28],"references":[{"surah":34,"verses":[28]}],"verseLabel":"سبأ: 28","question":"ماذا يفيد القصر في قوله: ﴿وَمَا أَرْسَلْنَاكَ إِلَّا كَافَّةً لِلنَّاسِ﴾؟","answer":"يثبت أن رسالة محمد ﷺ عامة لجميع الناس، لا تختص بمكة أو العرب؛ فهو بشير ونذير للبشر كافة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص234–235، تحت عنوان «بلاغة القصر»","url":""}]},{"id":"s34-76","number":76,"surah":34,"verses":[28],"references":[{"surah":34,"verses":[28]}],"verseLabel":"سبأ: 28","question":"لماذا اختيرت كلمة ﴿كَافَّةً﴾ في وصف الرسالة؟","answer":"لأنها تجمع معنى الإحاطة بالناس ومعنى كفهم وردعهم عن الكفر؛ فتلخص شمول الرسالة ووظيفتها في لفظ واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص235، تحت عنوان «بلاغة استعمال مفردة ﴿كافة﴾ وأوجه إعرابها»","url":""}]},{"id":"s34-35","number":35,"surah":34,"verses":[31],"references":[{"surah":34,"verses":[31]}],"verseLabel":"سبأ: 31","question":"ماذا تكشف ﴿لَوْلَا﴾ في قول المستضعفين للمستكبرين: ﴿لَوْلَا أَنْتُمْ لَكُنَّا مُؤْمِنِينَ﴾؟","answer":"تكشف محاولتهم تعليق ضلالهم كله على قادتهم والتنصل من مسؤوليتهم؛ جعلوا وجود المستكبرين مانعًا من الإيمان مع أنهم اتبعوهم باختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص267، تحت عنوان «دلالة ﴿لولا﴾ في الجملة»","url":""}]},{"id":"s34-77","number":77,"surah":34,"verses":[31],"references":[{"surah":34,"verses":[31]}],"verseLabel":"سبأ: 31","question":"لماذا قالوا: ﴿لَكُنَّا مُؤْمِنِينَ﴾ بصيغة الماضي؟","answer":"ليصوروا الإيمان كأنه كان وصفًا ثابتًا متحققًا لهم لولا المستكبرون، وفي ذلك مبالغة في دعوى البراءة وكشف لكذب اعتذارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص268، تحت عنوان «دلالة التعبير بالكون الماضي»","url":""}]},{"id":"s34-36","number":36,"surah":34,"verses":[34],"references":[{"surah":34,"verses":[34]}],"verseLabel":"سبأ: 34","question":"لماذا أُسند تكذيب النذير إلى ﴿مُتْرَفُوهَا﴾؟","answer":"لأن المترفين غالبًا رؤساء القرى وأصحاب النفوذ، فيقودون التكذيب ثم يتبعهم غيرهم؛ فإسناد القول إليهم يكشف مصدر الصد والعداوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص310، تحت عنوان «وجه إسناد فعل القول إلى المترفين»","url":""}]},{"id":"s34-37","number":37,"surah":34,"verses":[35],"references":[{"surah":34,"verses":[35]}],"verseLabel":"سبأ: 35","question":"لماذا حُكي قولهم عن الأموال والأولاد بصيغة الماضي: ﴿وَقَالُوا﴾؟","answer":"لتصوير اعتقادهم الباطل بأنه قول راسخ متكرر لا خاطر عابر؛ استقر عندهم أن كثرة المال والولد دليل رضا الله وأمان من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص315، تحت عنوان «دلالة التعبير بفعل القول ماضيًا»","url":""}]},{"id":"s34-78","number":78,"surah":34,"verses":[35],"references":[{"surah":34,"verses":[35]}],"verseLabel":"سبأ: 35","question":"ماذا يفيد قولهم: ﴿وَمَا نَحْنُ بِمُعَذَّبِينَ﴾؟","answer":"يفيد ثقتهم المغرورة بأنهم هم خاصة بمنأى عن العذاب، فكأن ما نالوه في الدنيا ضمان لمكانتهم في الآخرة، وهو استدلال قلبته الآيات عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص318، تحت عنوان «دلالة تقديم النفي على الضمير»","url":""}]},{"id":"s34-38","number":38,"surah":34,"verses":[37],"references":[{"surah":34,"verses":[37]}],"verseLabel":"سبأ: 37","question":"ما الصورة في قوله: ﴿مَا أَمْوَالُكُمْ وَلَا أَوْلَادُكُمْ بِالَّتِي تُقَرِّبُكُمْ عِنْدَنَا زُلْفَى﴾؟","answer":"تصور القرب من الله منزلة لا تحمل إليها الأموال والأولاد؛ فنفت أن تكون زينة الدنيا وسيلة تشريف، وجاء المضارع لنفي ذلك في كل وقت.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص338، تحت عنوان «بلاغة الكناية في ﴿تقربكم﴾ وصوغها مضارعًا»","url":""}]},{"id":"s34-79","number":79,"surah":34,"verses":[37],"references":[{"surah":34,"verses":[37]}],"verseLabel":"سبأ: 37","question":"ماذا يبين الاستثناء: ﴿إِلَّا مَنْ آمَنَ وَعَمِلَ صَالِحًا﴾؟","answer":"يبين أن المال والولد لا ينفعان بذاتهما، وإنما ينفع صاحبهما إيمانه وعمله الصالح بما يسخرهما فيه؛ فالعبرة باستعمال النعمة لا بمجرد امتلاكها.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص341، تحت عنوان «دلالة الاستثناء في قوله: ﴿إلا من آمن﴾»","url":""}]},{"id":"s34-80","number":80,"surah":34,"verses":[37],"references":[{"surah":34,"verses":[37]}],"verseLabel":"سبأ: 37","question":"لماذا قُدّم الإيمان على العمل الصالح؟","answer":"لأن الإيمان أصل قبول العمل وروحه؛ فلا يكون العمل صالحًا مثمرًا عند الله إلا إذا قام على إيمان صحيح.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص343، تحت عنوان «نكتة تقديم ذكر الإيمان على العمل»","url":""}]},{"id":"s34-39","number":39,"surah":34,"verses":[39],"references":[{"surah":34,"verses":[39]}],"verseLabel":"سبأ: 39","question":"ماذا يفيد تنكير ﴿شَيْءٍ﴾ في قوله: ﴿وَمَا أَنْفَقْتُمْ مِنْ شَيْءٍ﴾؟","answer":"يفيد العموم والتوكيد: أي نفقة مهما صغرت أو كبرت إذا كانت في سبيل الله داخلة في الوعد بالخلف، وفيه حث على البذل.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص369، تحت عنوان «غرض تنكير لفظ ﴿شيء﴾»","url":""}]},{"id":"s34-81","number":81,"surah":34,"verses":[39],"references":[{"surah":34,"verses":[39]}],"verseLabel":"سبأ: 39","question":"لماذا لم يذكر نوع الخلف في قوله: ﴿فَهُوَ يُخْلِفُهُ﴾؟","answer":"ليعم الوعد كل خلف يختاره الله: مالًا أو ثوابًا أو بركة ودفع سوء؛ فالحذف يوسع الرجاء ولا يقيده بصورة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص370–371، تحت عنوان «نكتة حذف متعلق فعل ﴿يخلفه﴾»","url":""}]},{"id":"s34-40","number":40,"surah":34,"verses":[40],"references":[{"surah":34,"verses":[40]}],"verseLabel":"سبأ: 40","question":"لماذا يسأل الله الملائكة: ﴿أَهَؤُلَاءِ إِيَّاكُمْ كَانُوا يَعْبُدُونَ﴾ وهو يعلم الحقيقة؟","answer":"لتبكيت المشركين وفضح دعواهم على رؤوس الأشهاد؛ يسمعون الملائكة أنفسهم يتبرؤون من عبادتهم فتقوم الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص384، تحت عنوان «غرض الاستفهام في الآية»","url":""}]},{"id":"s34-41","number":41,"surah":34,"verses":[46],"references":[{"surah":34,"verses":[46]}],"verseLabel":"سبأ: 46","question":"لماذا قُيّد القيام بقوله: ﴿أَنْ تَقُومُوا لِلَّهِ﴾؟","answer":"ليكون النظر خالصًا لطلب الحق، بعيدًا عن العصبية والهوى والمصلحة؛ فالإخلاص يحرر العقل من الموانع التي تصده عن الإنصاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص457، تحت عنوان «معنى (اللام) في ﴿لله﴾»","url":""}]},{"id":"s34-82","number":82,"surah":34,"verses":[46],"references":[{"surah":34,"verses":[46]}],"verseLabel":"سبأ: 46","question":"لماذا دُعوا إلى النظر ﴿مَثْنَى وَفُرَادَى﴾؟","answer":"لأن التشاور بين اثنين يكشف ما قد يغيب عن الواحد، والانفراد يبعد ضغط الجماعة؛ فتجتمع مراجعة الفكر وحرية الضمير للوصول إلى الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص458، تحت عنوان «دلالة التعبير بالفرد والاثنين»","url":""}]},{"id":"s34-83","number":83,"surah":34,"verses":[46],"references":[{"surah":34,"verses":[46]}],"verseLabel":"سبأ: 46","question":"لماذا جاء التفكر بعد القيام لله مثنى وفرادى؟","answer":"لأن التحرر من الهوى وضغط الجماعة يهيئ العقل للتفكر العميق؛ فرتبت الآية سلامة القصد أولًا ثم النظر الذي يكشف صدق الرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص460–461، تحت عنوان «دلالة التعبير بالتفكر في: ﴿تتفكروا﴾»","url":""}]},{"id":"s34-42","number":42,"surah":34,"verses":[48],"references":[{"surah":34,"verses":[48]}],"verseLabel":"سبأ: 48","question":"ما الصورة في قوله: ﴿إِنَّ رَبِّي يَقْذِفُ بِالْحَقِّ﴾؟","answer":"يشبه الحق بسهم قوي يصيبه الله موضعه فيدمغ الباطل؛ فالقذف يصور سرعة إظهاره وقوته ودقته في إصابة الهدف.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص479، تحت عنوان «بلاغة الاستعارة في ﴿يقذف﴾»","url":""}]},{"id":"s34-84","number":84,"surah":34,"verses":[48],"references":[{"surah":34,"verses":[48]}],"verseLabel":"سبأ: 48","question":"لماذا حُذف الموضع الذي يُقذف فيه الحق؟","answer":"ليعم كل موضع يصلح له: يقذف الله الحق في قلوب المؤمنين وفي وجوه الباطل، فتبدو الجملة شاملة لا يحدها ميدان واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص481، تحت عنوان «نكتة حذف متعلق الفعل ﴿يقذف﴾»","url":""}]},{"id":"s34-43","number":43,"surah":34,"verses":[49],"references":[{"surah":34,"verses":[49]}],"verseLabel":"سبأ: 49","question":"لماذا صُوِّر الباطل بأنه لا يُبدئ ولا يُعيد؟","answer":"لأن الابتداء والإعادة من آثار القدرة والحياة؛ فنفيهما يصوّر الباطل هالكًا منزوع الفاعلية، لا يملك إنشاء أثر ولا إحياء ما زال منه بعد مجيء الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص490، تحت عنوان «بلاغة الكناية في ﴿وما يبدئ الباطل وما يعيد﴾»","url":""}]},{"id":"s34-85","number":85,"surah":34,"verses":[49],"references":[{"surah":34,"verses":[49]}],"verseLabel":"سبأ: 49","question":"لماذا تكررت ﴿مَا﴾ في قوله: ﴿وَمَا يُبْدِئُ الْبَاطِلُ وَمَا يُعِيدُ﴾؟","answer":"ليستقل كل فعل بنفي مؤكد؛ فلا يملك الباطل ابتداءً ولا إعادةً، وبذلك يعم النفي وجهي الفعل ويقرر زوال الباطل من جميع الوجوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص490، تحت عنوان «علة تكرار ﴿ما﴾ في: ﴿وما يعيد﴾»","url":""}]},{"id":"s34-44","number":44,"surah":34,"verses":[51],"references":[{"surah":34,"verses":[51]}],"verseLabel":"سبأ: 51","question":"لماذا قيل: ﴿فَلَا فَوْتَ﴾ ولم يقل: فلا سَبْق؟","answer":"لأن الفوت ينفي مجرد إمكان النجاة والانفكاك، أما السبق فقد يوهم مسافةً أو قدرةً على التقدم؛ فاختير الفوت لتصوير أنهم مقهورون لا يملكون مهربًا أصلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص504، تحت عنوان «دلالة التعبير بالفوت دون السّبق»","url":""}]},{"id":"s34-86","number":86,"surah":34,"verses":[51],"references":[{"surah":34,"verses":[51]}],"verseLabel":"سبأ: 51","question":"لماذا قيل إنهم أُخذوا ﴿مِنْ مَكَانٍ قَرِيبٍ﴾؟","answer":"كناية عن سرعة أخذهم وسهولته وتمام القدرة عليهم؛ فسلطان الله لا تعوقه مسافة، وهم في قبضته أينما كانوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص507، تحت عنوان «بلاغة الكناية في قرب المكان»","url":""}]},{"id":"s34-45","number":45,"surah":34,"verses":[52],"references":[{"surah":34,"verses":[52]}],"verseLabel":"سبأ: 52","question":"ما الصورة في قوله: ﴿وَأَنَّى لَهُمُ التَّنَاوُشُ مِنْ مَكَانٍ بَعِيدٍ﴾؟","answer":"مثّل طلبهم الإيمان النافع بعد فوات زمنه بمن يحاول تناول شيء من موضع بعيد لا تبلغه يده؛ فقد كان الإيمان قريبًا ميسورًا في الدنيا، ثم صار بعد المعاينة متعذرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص510، تحت عنوان «بلاغة الاستعارة التمثيلية في ﴿وأنى لهم التناوش﴾»","url":""}]},{"id":"s34-46","number":46,"surah":34,"verses":[54],"references":[{"surah":34,"verses":[54]}],"verseLabel":"سبأ: 54","question":"لماذا قيل: ﴿وَحِيلَ بَيْنَهُمْ وَبَيْنَ مَا يَشْتَهُونَ﴾؟","answer":"يصور فعل الحيلولة انفصالًا قهريًا تامًا بينهم وبين مطلوبهم بعد أن ظنوا إمكان بلوغه؛ فيورثهم عزلًا وحسرةً أشد من مجرد الإخبار بالحرمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص519، تحت عنوان «دلالة التعبير بفعل الحيلولة»","url":""}]},{"id":"s34-87","number":87,"surah":34,"verses":[54],"references":[{"surah":34,"verses":[54]}],"verseLabel":"سبأ: 54","question":"لماذا أُبهم المرغوب في قوله: ﴿مَا يَشْتَهُونَ﴾؟","answer":"ليعم كل ما تتعلق به رغباتهم: النجاة من النار، والإيمان النافع، والرجوع إلى الدنيا، وسائر ما يرجونه؛ فالإبهام يوسّع الوعيد ويصور حرمانًا شاملًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص520، تحت عنوان «دلالة ﴿ما﴾ في: ﴿ما يشتهون﴾»","url":""}]},{"id":"s34-88","number":88,"surah":34,"verses":[54],"references":[{"surah":34,"verses":[54]}],"verseLabel":"سبأ: 54","question":"لماذا قيل: ﴿كَمَا فُعِلَ بِأَشْيَاعِهِمْ مِنْ قَبْلُ﴾؟","answer":"لبيان أن عاقبتهم ليست حادثة منفردة؛ فقد جرت سنة الله في أمثالهم من المكذبين أن يُحال بينهم وبين ما يشتهون حين يفوت زمن الإيمان، فتتأكد حتمية المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص521، تحت عنوان «بلاغة التشبيه المرسل في الآية»","url":""}]},{"id":"s35-1","number":1,"surah":35,"verses":[1],"references":[{"surah":35,"verses":[1]}],"verseLabel":"فاطر: 1","question":"لماذا افتتحت سورة فاطر بالحمد؟","answer":"لأن السورة تعرض دلائل القدرة والنعم ومصير الخلق، فكان الحمد براعة استهلال تهيئ القلب للاعتراف بالمنعم قبل تفصيل آيات فضله وقدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص542، تحت عنوان «براعة الاستهلال في الافتتاح بالحمد»","url":""}]},{"id":"s35-2","number":2,"surah":35,"verses":[1],"references":[{"surah":35,"verses":[1]}],"verseLabel":"فاطر: 1","question":"ما دلالة قوله عن أجنحة الملائكة: ﴿مَثْنَى وَثُلَاثَ وَرُبَاعَ﴾؟","answer":"يدل على تفاوت الملائكة في عدد الأجنحة؛ فمنهم ذو جناحين أو ثلاثة أو أربعة، وليس المقصود حصر الخلق في هذه الأعداد، بدليل قوله بعده: ﴿يزيد في الخلق ما يشاء﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص547، تحت عنوان «توجيه الدلالة العددية في ﴿مثنى وثلاث ورباع﴾»","url":""}]},{"id":"s35-3","number":3,"surah":35,"verses":[2],"references":[{"surah":35,"verses":[2]}],"verseLabel":"فاطر: 2","question":"لماذا صُوّرت الرحمة في قوله: ﴿مَا يَفْتَحِ اللَّهُ لِلنَّاسِ مِنْ رَحْمَةٍ﴾ بشيء يُفتح؟","answer":"شُبه وصول الرحمة بفتح باب أو خزانة مغلقة؛ فإذا فتحها الله اندفعت إلى الناس ولم يقدر أحد على حبسها، فالصورة تجمع السعة واليسر وانفراد الله بالمنح.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص553، تحت عنوان «بلاغة المجاز والاستعارة في ﴿ما يفتح﴾»","url":""}]},{"id":"s35-43","number":43,"surah":35,"verses":[2],"references":[{"surah":35,"verses":[2]}],"verseLabel":"فاطر: 2","question":"ماذا يفيد تنكير ﴿رَحْمَةٍ﴾ في قوله: ﴿مِنْ رَحْمَةٍ﴾؟","answer":"يعمم كل لون من الرحمة مهما دق أو عظم؛ فأي رحمة يفتحها الله للناس لا يستطيع أحد إمساكها.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص554، تحت عنوان «دلالة التنكير في ﴿رحمة﴾»","url":""}]},{"id":"s35-44","number":44,"surah":35,"verses":[2],"references":[{"surah":35,"verses":[2]}],"verseLabel":"فاطر: 2","question":"ماذا يفيد قوله: ﴿فَلَا مُمْسِكَ لَهَا﴾ بعد فتح الرحمة؟","answer":"يفيد نفي القدرة على حبسها عن جميع الخلق نفيًا قاطعًا؛ فمتى أرسلها الله نفذت ولم يقف في طريقها مانع.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص555، تحت عنوان «دلالة النفي في الجواب: ﴿فلا ممسك لها﴾»","url":""}]},{"id":"s35-4","number":4,"surah":35,"verses":[2],"references":[{"surah":35,"verses":[2]}],"verseLabel":"فاطر: 2","question":"ما دلالة المقابلة بين فتح الرحمة وإمساكها في الآية؟","answer":"تُظهر أن خزائن النفع كلها بيد الله: ما يفتحه لا يقدر أحد على إمساكه، وما يمسكه لا يقدر أحد على إرساله؛ فتُحكم جهتا العطاء والمنع في صورة متقابلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص556، تحت عنوان «توجيه المقابلة المعنوية بين (الفتح) و(الإمساك)»","url":""}]},{"id":"s35-5","number":5,"surah":35,"verses":[3],"references":[{"surah":35,"verses":[3]}],"verseLabel":"فاطر: 3","question":"لماذا جُمع في الحجة بين الخلق والرزق: ﴿خَالِقٍ... يَرْزُقُكُمْ﴾؟","answer":"لأن الخالق هو الذي أوجدهم، والرازق هو الذي يمد حياتهم؛ فاجتماع بدء الوجود واستمراره يثبت كمال افتقارهم إلى الله ويبطل أن يستحق العبادة سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص572، تحت عنوان «نكتة اختصاص صفتي الخالقية والرازقية في إثبات الألوهية»","url":""}]},{"id":"s35-6","number":6,"surah":35,"verses":[5],"references":[{"surah":35,"verses":[5]}],"verseLabel":"فاطر: 5","question":"لماذا سُمّي الشيطان ﴿الْغَرُورُ﴾؟","answer":"لأنه بالغ في خداع الإنسان وتزيين الباطل حتى صار كأنه الخداع نفسه؛ فصيغة الوصف تحذر من كثرة تغريره، ولا سيما حين يمني العاصي بعفو الله ليجرئه على الذنب.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص599–600، تحت عنوان «علة التعبير بـ﴿الغرور﴾»","url":""}]},{"id":"s35-7","number":7,"surah":35,"verses":[6],"references":[{"surah":35,"verses":[6]}],"verseLabel":"فاطر: 6","question":"لماذا قيل: ﴿فَاتَّخِذُوهُ عَدُوًّا﴾ مع أن الشيطان عدو بالفعل؟","answer":"لأن المطلوب ألا تبقى عداوته معلومة في الذهن فحسب، بل أن يعامله الإنسان معاملة العدو فيحذره ويخالفه؛ فالتعبير بالاتخاذ ينقل العلم إلى موقف عملي دائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص609–610، تحت عنوان «علة التعبير بالأخذ»","url":""}]},{"id":"s35-8","number":8,"surah":35,"verses":[8],"references":[{"surah":35,"verses":[8]}],"verseLabel":"فاطر: 8","question":"لماذا قيل في صاحب العمل السيئ: ﴿فَرَآهُ حَسَنًا﴾ ولم يقل: فظنه حسنًا؟","answer":"لأن تزيين الباطل بلغ منه مبلغ اليقين الراسخ حتى صار يعتقد قبحه جمالًا كأنه يراه بعينه؛ فالرؤية هنا قلبية لكنها تصور شدة انخداعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص643–644، تحت عنوان «علة التعبير بالرؤية»","url":""}]},{"id":"s35-45","number":45,"surah":35,"verses":[8],"references":[{"surah":35,"verses":[8]}],"verseLabel":"فاطر: 8","question":"لماذا حُذف خبر ﴿أَفَمَنْ زُيِّنَ لَهُ سُوءُ عَمَلِهِ﴾؟","answer":"لأن المقابِل مفهوم من السياق: أفهذا كمن عرف الحق ورأى القبيح قبيحًا؟ وحذف الجواب يفتح الذهن لتقدير كل وجوه المفارقة، ويقرر أن الفريقين لا يستويان.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص645–646، تحت عنوان «سر حذف الخبر في الاستفهام»","url":""}]},{"id":"s35-9","number":9,"surah":35,"verses":[8],"references":[{"surah":35,"verses":[8]}],"verseLabel":"فاطر: 8","question":"ما سرّ جمع ﴿حَسَرَاتٍ﴾ في قوله ﴿فَلَا تَذْهَبْ نَفْسُكَ عَلَيْهِمْ حَسَرَاتٍ﴾؟","answer":"الجمع يدل على تضاعف الأسف على أحوالهم وأعمالهم الموجبة للعقوبة. وصيغة جمع القلة تصور أن أدنى تلك الحسرات يكفي لإذهاب النفس، تعظيمًا لرحمة الرسول ﷺ وحرصه على هداية قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص655–656، تحت عنوان «نكتة إيراد الجمع جمع قلة في ﴿حسرات﴾»","url":""}]},{"id":"s35-10","number":10,"surah":35,"verses":[9],"references":[{"surah":35,"verses":[9]}],"verseLabel":"فاطر: 9","question":"لماذا قيل بعد إحياء الأرض: ﴿كَذَلِكَ النُّشُورُ﴾؟","answer":"لأن إحياء الأرض بعد موتها مشهد محسوس يقاس عليه بعث الأجساد؛ فالذي أعاد الحياة إلى التراب بالنبات قادر على إخراج الموتى من قبورهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص677، تحت عنوان «دلالة الكاف في قوله ﴿كذلك﴾»","url":""}]},{"id":"s35-11","number":11,"surah":35,"verses":[10],"references":[{"surah":35,"verses":[10]}],"verseLabel":"فاطر: 10","question":"لماذا حُذف جواب قوله: ﴿مَنْ كَانَ يُرِيدُ الْعِزَّةَ﴾؟","answer":"لأن ما بعده يدل عليه: من أراد العزة فليطلبها من الله؛ وحذف الجواب يجعل السامع يستحضره بنفسه ويقطع الطريق على طلبها من غير مالكها.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص687، تحت عنوان «سر حذف جواب الشرط»","url":""}]},{"id":"s35-46","number":46,"surah":35,"verses":[10],"references":[{"surah":35,"verses":[10]}],"verseLabel":"فاطر: 10","question":"ماذا يفيد تقديم ﴿فَلِلَّهِ﴾ في قوله: ﴿فَلِلَّهِ الْعِزَّةُ﴾؟","answer":"يفيد اختصاص العزة الحقيقية بالله؛ فهو مالكها ومصدرها، ولا ينالها أحد إلا بطاعته والانتساب إلى جانبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص688، تحت عنوان «نكتة تقديم الجار والمجرور»","url":""}]},{"id":"s35-47","number":47,"surah":35,"verses":[10],"references":[{"surah":35,"verses":[10]}],"verseLabel":"فاطر: 10","question":"ماذا تضيف كلمة ﴿جَمِيعًا﴾ في قوله: ﴿فَلِلَّهِ الْعِزَّةُ جَمِيعًا﴾؟","answer":"تنفي أن يكون لغير الله جزء مستقل من العزة؛ فكل أنواعها ودرجاتها له، وما يظهر عند الخلق فمن عطائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص689، تحت عنوان «علة التعبير بـ﴿جميعًا﴾»","url":""}]},{"id":"s35-12","number":12,"surah":35,"verses":[10],"references":[{"surah":35,"verses":[10]}],"verseLabel":"فاطر: 10","question":"لماذا عبّر عن وصول الكلم الطيب إلى الله بالصعود: ﴿إِلَيْهِ يَصْعَدُ الْكَلِمُ الطَّيِّبُ﴾؟","answer":"لأن الصعود يناسب شرف الكلمة وقبولها وبلوغها محل الرضا؛ فصُور القول الطيب كشيء كريم يرتقي ولا يضيع.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص691، تحت عنوان «علة التعبير بالصعود»","url":""}]},{"id":"s35-48","number":48,"surah":35,"verses":[10],"references":[{"surah":35,"verses":[10]}],"verseLabel":"فاطر: 10","question":"لماذا عبّر عن أثر العمل الصالح بقوله: ﴿وَالْعَمَلُ الصَّالِحُ يَرْفَعُهُ﴾؟","answer":"لأن الرفع انتقال إلى الأعلى، فكُني به عن قبول العمل ورفعة صاحبه؛ فكما يصعد الكلم الطيب بصاحبه إلى مقام القبول، يرفعه العمل الصالح منزلةً وعزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص695، تحت عنوان «علة التعبير بالرفع»","url":""}]},{"id":"s35-13","number":13,"surah":35,"verses":[11],"references":[{"surah":35,"verses":[11]}],"verseLabel":"فاطر: 11","question":"ماذا يفيد الانتقال بـ﴿ثُمَّ﴾ من الخلق من تراب إلى الخلق من نطفة؟","answer":"يلفت إلى التفاوت البعيد بين أصل الإنسان الأول من تراب وبين تناسل ذريته من نطفة، ويصور الانتقال العجيب بين مرحلتين مختلفتين من الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص712–713، تحت عنوان «علة التعبير بـ﴿ثم﴾»","url":""}]},{"id":"s35-14","number":14,"surah":35,"verses":[12],"references":[{"surah":35,"verses":[12]}],"verseLabel":"فاطر: 12","question":"لماذا قال بعد نفي استواء البحرين: ﴿وَمِنْ كُلٍّ تَأْكُلُونَ لَحْمًا طَرِيًّا﴾؟","answer":"ليبين أن اختلاف العذب والملح لا يمنع اشتراكهما في منافع سخرها الله؛ فمن كل واحد يأتي الطعام والحلية، فتجتمع دقة التمييز وسعة الانتفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص740، تحت عنوان «دلالة التعبير بالواو في ﴿ومن كل﴾»","url":""}]},{"id":"s35-15","number":15,"surah":35,"verses":[12],"references":[{"surah":35,"verses":[12]}],"verseLabel":"فاطر: 12","question":"لماذا أُدخل قوله: ﴿لِتَبْتَغُوا مِنْ فَضْلِهِ﴾ في مشهد الفلك المواخر؟","answer":"لأن شق السفن للبحر ليس منظر قدرة فحسب، بل نعمة تمكّن الناس من السفر والتجارة وطلب الرزق؛ فأُدمج الامتنان بمصالحهم في أثناء عرض الآية الكونية.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص750، تحت عنوان «بلاغة الإدماج في الآية»","url":""}]},{"id":"s35-16","number":16,"surah":35,"verses":[13],"references":[{"surah":35,"verses":[13]}],"verseLabel":"فاطر: 13","question":"لماذا ضُرب القطمير مثلًا لما لا تملكه المعبودات من دون الله؟","answer":"لأن القطمير قشرة رقيقة جدًا على نواة التمر لا تكاد تُذكر؛ فنفي ملكه يصور عجز تلك المعبودات عن أدنى شيء، فضلًا عن جلب نفع أو دفع ضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص779–780، تحت عنوان «سر اختيار القطمير دون غيره»","url":""}]},{"id":"s35-17","number":17,"surah":35,"verses":[14],"references":[{"surah":35,"verses":[14]}],"verseLabel":"فاطر: 14","question":"لماذا سُمّي تبرؤ المعبودات يوم القيامة ﴿كفرًا﴾ بشرك عابديها؟","answer":"لأنها تنكر عبادتهم وتتبرأ منها وتبطل نسبتهم الشراكة إليها؛ فالتعبير بالكفر يصور الرفض التام لما كانوا يثبتونه لها في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص791، تحت عنوان «سر التعبير بالكفر في قوله: ﴿يكفرون بشرككم﴾»","url":""}]},{"id":"s35-18","number":18,"surah":35,"verses":[15],"references":[{"surah":35,"verses":[15]}],"verseLabel":"فاطر: 15","question":"لماذا أتبع وصف الله بـ﴿الْغَنِيُّ﴾ وصفه بـ﴿الْحَمِيدُ﴾؟","answer":"ليبين أن غناه ليس غنى منع وجفاء؛ فهو مع استغنائه عن الخلق محمود في عطائه وتدبيره، يمنحهم من فضله ويستحق حمدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص18، تحت عنوان «سر إتباع صفة ﴿الغني﴾ بـ ﴿الحميد﴾»","url":""}]},{"id":"s35-19","number":19,"surah":35,"verses":[18],"references":[{"surah":35,"verses":[18]}],"verseLabel":"فاطر: 18","question":"ماذا يضيف قوله: ﴿وَإِنْ تَدْعُ مُثْقَلَةٌ إِلَى حِمْلِهَا لَا يُحْمَلْ مِنْهُ شَيْءٌ﴾ بعد ﴿وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى﴾؟","answer":"ينقل القاعدة إلى مشهد حي: نفس أثقلتها الذنوب تستغيث بمن يحمل عنها فلا تجد من يأخذ شيئًا؛ فيتحول نفي انتقال الوزر إلى صورة محسوسة لشدة الحاجة والعجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص38–39، تحت عنوان «بلاغة ذكر ﴿وإن تدع مثقلة إلى حملها﴾ بعد الجملة السابقة»","url":""}]},{"id":"s35-49","number":49,"surah":35,"verses":[18],"references":[{"surah":35,"verses":[18]}],"verseLabel":"فاطر: 18","question":"لماذا قيل فيمن يُدعى لحمل الذنب: ﴿وَلَوْ كَانَ ذَا قُرْبَى﴾؟","answer":"لأن القريب أرجى الناس للنصرة في الدنيا؛ فإذا لم يحمل يوم القيامة شيئًا عن قريبه، كان غيره أولى بالعجز، وظهر أن كل نفس مرهونة بعملها.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص43–44، تحت عنوان «دلالة (لو) في قوله: ﴿ولو كان ذا قربى﴾»","url":""}]},{"id":"s35-20","number":20,"surah":35,"verses":[19,20,21,22],"references":[{"surah":35,"verses":[19,20,21,22]}],"verseLabel":"فاطر: 19-22","question":"لماذا رُتبت أمثال المؤمن والكافر من الأعمى والبصير حتى الأحياء والأموات بهذا التدرج؟","answer":"بدأت بآلة الإدراك: البصر والعمى، ثم بما لا تتم الرؤية إلا به: النور والظلمات، ثم بمآلهما: الظل المريح والحرور المتعب، وانتهت بما هو أبلغ: الحياة والموت؛ فتترقى المفارقة حتى تجعل الإيمان حياة والكفر موتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص74، تحت عنوان «بلاغة ترتيب التمثيلات»","url":""}]},{"id":"s35-21","number":21,"surah":35,"verses":[19,20,21,22],"references":[{"surah":35,"verses":[19,20,21,22]}],"verseLabel":"فاطر: 19-22","question":"لماذا تكررت ﴿لَا﴾ في المقابلات: ﴿وَلَا الظُّلُمَاتُ وَلَا النُّورُ وَلَا الظِّلُّ وَلَا الْحَرُورُ﴾؟","answer":"لتستقل كل مقابلة بنفيها ويتأكد امتناع التسوية في كل وجه؛ فلا يلتبس الهدى بالضلال ولا الراحة بالعذاب، كما لا يستوي البصير والأعمى.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص65، تحت عنوان «براعة تكرار حرف النفي (لا)»","url":""}]},{"id":"s35-50","number":50,"surah":35,"verses":[19,20,21,22],"references":[{"surah":35,"verses":[19,20,21,22]}],"verseLabel":"فاطر: 19-22","question":"لماذا أُعيدت عبارة ﴿وَمَا يَسْتَوِي﴾ قبل الأحياء والأموات؟","answer":"لأن المقابلة الأخيرة أبلغ من سابقاتها وتمثل خلاصة مستقلة: المؤمن حي القلب والكافر ميت القلب؛ فأعيد نفي الاستواء لتوكيدها وإبراز انتقال الكلام إلى ذروة التمثيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص70، تحت عنوان «نكتة تكرار نفي الاستواء»","url":""}]},{"id":"s35-22","number":22,"surah":35,"verses":[24],"references":[{"surah":35,"verses":[24]}],"verseLabel":"فاطر: 24","question":"ماذا يفيد القصر في قوله: ﴿وَإِنْ مِنْ أُمَّةٍ إِلَّا خَلَا فِيهَا نَذِيرٌ﴾؟","answer":"يفيد أن إرسال النذر سنة شملت الأمم كلها؛ فلم تُترك أمة بلا من يقيم عليها الحجة ويدعوها إلى الهدى، وفي ذلك تسلية للنبي ﷺ بأن رسالته امتداد لسنة الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص91، تحت عنوان «بلاغة القصر وغرضه»","url":""}]},{"id":"s35-51","number":51,"surah":35,"verses":[24],"references":[{"surah":35,"verses":[24]}],"verseLabel":"فاطر: 24","question":"ما الصورة في قوله عن النذير: ﴿خَلَا فِيهَا﴾؟","answer":"أصل الخلو فراغ المكان، فنُقل إلى مضي النذير في الأمة وانقضاء عهده؛ وفيه تصوير الرسالة السابقة بأمر تحقق واستقر في تاريخ الأمم، لا بخبر مستبعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص92، تحت عنوان «بلاغة المجاز في لفظ ﴿خلا﴾»","url":""}]},{"id":"s35-23","number":23,"surah":35,"verses":[27],"references":[{"surah":35,"verses":[27]}],"verseLabel":"فاطر: 27","question":"لماذا تكرر ذكر ﴿أَلْوَانُهَا﴾ في الثمرات والجبال والناس والدواب والأنعام؟","answer":"ليلفت إلى وحدة سنّة التنويع في عوالم متباعدة؛ فالماء واحد وتختلف به الثمرات، وتتنوع خطوط الجبال وألوان الأحياء، فيشهد اختلاف الألوان لوحدة القدرة وحسن التدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص119، تحت عنوان «بلاغة استعمال مفردة الألوان»","url":""}]},{"id":"s35-52","number":52,"surah":35,"verses":[27],"references":[{"surah":35,"verses":[27]}],"verseLabel":"فاطر: 27","question":"لماذا خُصت الجبال بالذكر في مشهد اختلاف الألوان؟","answer":"لأن ألوان الجبال ثابتة ظاهرة على امتدادها، وفي جددها البيض والحمر والغرابيب السود مشهد عظيم لا يخفى؛ فكانت أنسب ما يمثل تنوع ألوان الجماد وجماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص121، تحت عنوان «توجيه تخصيص الجبال بالذكر دون الأرض»","url":""}]},{"id":"s35-24","number":24,"surah":35,"verses":[28],"references":[{"surah":35,"verses":[28]}],"verseLabel":"فاطر: 28","question":"ماذا يفيد القصر في قوله: ﴿إِنَّمَا يَخْشَى اللَّهَ مِنْ عِبَادِهِ الْعُلَمَاءُ﴾؟","answer":"يفيد أن الخشية الكاملة ثمرة العلم بالله وآياته؛ فكلما ازداد العبد معرفة بعظمته وقدرته ازداد خوفًا منه وتعظيمًا له، ولذلك خُص العلماء بهذه المنزلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص133، تحت عنوان «بلاغة الاستئناف بجملة القصر»","url":""}]},{"id":"s35-53","number":53,"surah":35,"verses":[28],"references":[{"surah":35,"verses":[28]}],"verseLabel":"فاطر: 28","question":"لماذا قُدّم اسم الله في قوله: ﴿إِنَّمَا يَخْشَى اللَّهَ... الْعُلَمَاءُ﴾؟","answer":"للعناية بالمخشيّ وتعظيمه، ولإبقاء لفظ العلماء في ختام الجملة موضع البيان بعد عرض دلائل القدرة؛ فالمقصود أن العلم بهذه الآيات هو الذي يورث خشية الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص135، تحت عنوان «نكتة تقديم لفظ الجلالة»","url":""}]},{"id":"s35-25","number":25,"surah":35,"verses":[29],"references":[{"surah":35,"verses":[29]}],"verseLabel":"فاطر: 29","question":"لماذا صُوّرت أعمال أهل القرآن بأنها ﴿تِجَارَةً﴾؟","answer":"لأنهم يبذلون التلاوة والصلاة والإنفاق طلبًا لثواب الله، فشُبه عملهم بتجارة يرجو صاحبها الربح؛ غير أن هذه التجارة مضمونة العاقبة مع الله وليست عرضة للخسارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص150، تحت عنوان «بلاغة الاستعارة وفائدتها»","url":""}]},{"id":"s35-54","number":54,"surah":35,"verses":[29],"references":[{"surah":35,"verses":[29]}],"verseLabel":"فاطر: 29","question":"لماذا قيل: ﴿لَنْ تَبُورَ﴾ ولم يقل: لا تبور؟","answer":"لأن ﴿لن﴾ تؤكد نفي الخسران في المستقبل؛ فتطمئنهم إلى أن تجارتهم لا تكسد عند لقاء الله، بل يبقى ربحها ويضاعف جزاؤها.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص150–151، تحت عنوان «سر النفي بـ ﴿لن﴾ دون (لا)»","url":""}]},{"id":"s35-26","number":26,"surah":35,"verses":[30],"references":[{"surah":35,"verses":[30]}],"verseLabel":"فاطر: 30","question":"لماذا قُدّم ﴿غَفُورٌ﴾ على ﴿شَكُورٌ﴾؟","answer":"لأن سلامة العمل من تبعات التقصير تسبق نيل الزيادة في الثواب؛ فبدأ بالمغفرة التي تزيل المانع، ثم بالشكر الذي يضاعف الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص154، تحت عنوان «نكتة تقديم الغفور على الشكور»","url":""}]},{"id":"s35-27","number":27,"surah":35,"verses":[32],"references":[{"surah":35,"verses":[32]}],"verseLabel":"فاطر: 32","question":"إلى من يعود الضمير في قوله: ﴿فَمِنْهُمْ ظَالِمٌ لِنَفْسِهِ﴾ بعد ﴿الَّذِينَ اصْطَفَيْنَا﴾؟","answer":"يعود إلى الذين أورثهم الله الكتاب؛ فحتى الظالم لنفسه لم يخرج من جماعة الأمة المصطفاة، وفي ذلك تحذير من التفريط مع فتح باب الرجاء له بالمغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص173–174، تحت عنوان «نكتة عود الضمير في ﴿فمنهم﴾»","url":""}]},{"id":"s35-55","number":55,"surah":35,"verses":[32],"references":[{"surah":35,"verses":[32]}],"verseLabel":"فاطر: 32","question":"لماذا أُشير إلى السبق بالخيرات بقوله: ﴿ذَلِكَ هُوَ الْفَضْلُ الْكَبِيرُ﴾؟","answer":"أشير إليه باسم البعيد لتعظيم منزلته ورفع شأنه؛ فالسبق ليس ثمرة القدرة البشرية وحدها، بل فضل كبير من الله وإذن منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص179، تحت عنوان «غرض التعبير باسم الإشارة البعيد»","url":""}]},{"id":"s35-28","number":28,"surah":35,"verses":[33],"references":[{"surah":35,"verses":[33]}],"verseLabel":"فاطر: 33","question":"ماذا يوحي قوله عن أهل الجنة: ﴿يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ﴾؟","answer":"يوحي بأن التحلية تُجرى عليهم تكريمًا وخدمة، لا أنهم يتكلفونها بأنفسهم؛ فالمشهد مشهد إكرام متجدد في دار النعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص188، تحت عنوان «دلالة التعبير بقوله ﴿يحلون﴾»","url":""}]},{"id":"s35-29","number":29,"surah":35,"verses":[33],"references":[{"surah":35,"verses":[33]}],"verseLabel":"فاطر: 33","question":"لماذا قُدمت حلي الأساور على لباس الحرير في وصف نعيم الجنة؟","answer":"لأن الحلي زيادة تجمل فوق أصل اللباس، فبدء الوصف بها أسرع في إظهار الترف والتكريم، ثم ذُكر الحرير لباسًا دائمًا يحيط بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص193، تحت عنوان «بلاغة تقديم تحلية الأساور على اللباس»","url":""}]},{"id":"s35-30","number":30,"surah":35,"verses":[34],"references":[{"surah":35,"verses":[34]}],"verseLabel":"فاطر: 34","question":"ما سرّ التعبير في قول أهل الجنة ﴿الَّذِي أَذْهَبَ عَنَّا الْحَزَنَ﴾ معرفًا؟","answer":"التعريف للاستغراق، فيشمل كل فرد من أفراد الحزن؛ فلا يصيبهم منه شيء بعد دخول الجنة. ومن أعظم ما زال حزن الخوف من سوء العاقبة، كما تزول هموم الدنيا ومتاعبها كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص200، تحت عنوان «معنى (أل) في لفظ ﴿الحزن﴾»","url":""}]},{"id":"s35-31","number":31,"surah":35,"verses":[35],"references":[{"surah":35,"verses":[35]}],"verseLabel":"فاطر: 35","question":"لماذا أعيدت عبارة ﴿وَلَا يَمَسُّنَا﴾ مع ﴿لُغُوبٌ﴾؟","answer":"ليستقل نفي كل نوع من التعب ويتأكد: فلا يلحقهم نصب أثناء العمل، ولا لغوب أو إعياء بعده؛ وإعادة الفعل تصور انتفاءهما التام والدائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص207–208، تحت عنوان «نكتة إعادة ذكر ﴿ولا يمسنا﴾»","url":""}]},{"id":"s35-32","number":32,"surah":35,"verses":[36],"references":[{"surah":35,"verses":[36]}],"verseLabel":"فاطر: 36","question":"لماذا قيل عن أهل النار: ﴿لَا يُقْضَى عَلَيْهِمْ فَيَمُوتُوا وَلَا يُخَفَّفُ عَنْهُمْ مِنْ عَذَابِهَا﴾؟","answer":"لأن انقطاع الحياة راحة من الألم، وتخفيف العذاب راحة مع البقاء؛ فنفت الآية الطريقين معًا، فلا موت ينهي عذابهم ولا تخفيف يهون استمراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص221، تحت عنوان «فائدة ذكر جملة نفي التخفيف بعد نفي الموت»","url":""}]},{"id":"s35-33","number":33,"surah":35,"verses":[37],"references":[{"surah":35,"verses":[37]}],"verseLabel":"فاطر: 37","question":"ما غرض السؤال: ﴿أَوَلَمْ نُعَمِّرْكُمْ مَا يَتَذَكَّرُ فِيهِ مَنْ تَذَكَّرَ﴾؟","answer":"هو توبيخ يقطع عذرهم؛ فقد مُنحوا عمرًا كافيًا للتفكر والرجوع، فلم تكن خسارتهم من ضيق الفرصة بل من إضاعة ما أمهلوا فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص228، تحت عنوان «بلاغة الاستفهام ونوعه وغرضه»","url":""}]}]);
